update content_bodies set title = '沖縄観光: 県内最大の外人住宅街での早朝さんぽ ♯140 【４K】北谷町のおきなわさんぽ', description = 'この動画では、沖縄の北谷町にある県内最大の外人住宅街での早朝のさんぽを楽しむことができます。現地の美しい風景を紹介し、実際に訪れることが難しい方々にバーチャルな体験を提供しています。チャンネル「@おきなわ👣さんぽⓇ」では、沖縄の観光名所や文化を探るための動画が多数公開されています。' where id = 'V0HNubaab7T_Y4_4tvXAS';
