update content_bodies set title = 'キャニオニング', description = 'この動画はキャニオニングについて紹介しています。キャニオニングは、渓谷や峡谷を下るアクティビティで、自然の中での冒険を楽しむことができます。水流や岩を利用して、滑り降りたり、飛び込んだりすることが特徴です。初心者から上級者まで楽しめる内容があり、自然の美しさを体感しながら、スリルを味わうことができます。' where id = 'YQKvWS44BmH17HrIAep9N';
