update content_bodies set title = '北山川ラフティング', description = 'この動画は北山川ラフティングについて紹介しています。北山川は美しい自然に囲まれた場所で、ラフティングを楽しむことができるスポットです。初心者から経験者まで、さまざまなレベルの参加者が楽しめるアクティビティが用意されています。' where id = 'ZpYVdwGGuWxjNLFkttnyx';
