update content_bodies set title = 'ユニバーサル・スタジオ・ジャパン 2025: プラントベースフードガイド（全フードオプション！）', description = 'このガイドでは、ユニバーサル・スタジオ・ジャパンで提供されるさまざまなプラントベースの食事オプションを探ります。著者は異なる料理を試食し、訪問者にとってのベストとワーストの選択肢を強調しています。動画では、ファラフェル、グリルサラダ、野菜アイリッシュシチューなどのアイテムを含む詳細なフードツアーが紹介されています。食事制限、チケット、ホテル宿泊に関する便利なリンクも提供されており、プラントベースの食事をする人々がパークの提供を効果的にナビゲートできるようにすることを目的としています。' where id = 'eGET41DgUzS1sr6PQrUaR';
update content_bodies set title = 'Universal Studios Japan 2025: Plant-Based Food Guide (All Food Options!)', description = 'This guide explores the various plant-based meal options available at Universal Studios Japan. The author samples different dishes, highlighting both the best and worst choices for visitors. The video includes a detailed food tour featuring items such as falafel, grilled salad, vegetable Irish stew, and more. Useful links are provided for those interested in dietary restrictions, tickets, and hotel accommodations. The guide aims to assist plant-based eaters in navigating the park''s offerings effectively.' where id = 'z-4o3yBGCSM5rfpz-DYGe';
update content_bodies set title = '天野の風景', description = '標高450mの天野盆地は、和歌山県かつらぎ町に位置し、四季折々の美しい田園風景が広がっています。「歴史の里　天野」として知られ、1700年前の丹生明神や1200年前の空海に関連する史跡が点在しています。『にほんの里100選』にも選ばれたこの地域は、自然環境が豊かで、初夏には真国川で源氏ボタルが舞う光景が見られます。特に春の新緑や秋の稲穂の美しさは桃源郷を思わせるものです。また、真言密教の守り神である丹生都比売神社があり、歴史と信仰の深い里でもあります。' where id = 'E-37B50mVL72O3Ghtg8hr';
update content_bodies set title = 'Scenery of Amano', description = 'Amano Basin, located at an elevation of 450m in Katsuragi Town, Wakayama Prefecture, offers picturesque rural landscapes throughout the seasons. Known as ''the historical village of Amano,'' it is home to numerous historical sites related to Niu Myojin from 1700 years ago and Kukai from 1200 years ago. Selected as one of ''Japan''s 100 Best Countryside,'' Amano is a true ''healing village.'' The area is recognized for its rich natural environment, including the Genji fireflies that dance in the clear waters of Makuni River during early summer. The stunning seasonal changes, especially the fresh greenery in spring and the golden waves of rice in autumn, evoke the image of a paradise. The Niu Myojin Shrine, a protector of Shingon Buddhism, is also located here, making Amano a place rich in history and spirituality.' where id = 'IUC9eOWrerFlrMdnKVFVv';
update content_bodies set title = '動画でわかる！和歌山観光をもっと楽しむための防災対策', description = '国内外からの観光客が自然災害時に迅速かつ適切に対応できるよう、特に地震や津波に関する初動対応をわかりやすく説明した動画を制作しました。内容は、旅先での“もしも”に備えて知っておきたい防災のポイント、役立つ便利アイテムや防災グッズの紹介、和歌山県防災ナビや防災リーフレット等の案内が含まれています。' where id = 'vmr9tGy2LQJOUnrWlw1xm';
update content_bodies set title = 'Disaster Preparedness for Enjoying Wakayama Tourism', description = 'A video has been created to help both domestic and international tourists respond quickly and appropriately during natural disasters, particularly focusing on initial responses to earthquakes and tsunamis. The content includes essential disaster preparedness points to know while traveling, recommendations for useful items and disaster supplies, and information on Wakayama Prefecture''s disaster navigation and brochures.' where id = 'aT_SJUl_FbyZIZ8z5Wwog';
update content_bodies set title = '災害対策動画が利用可能になりました！！', description = '国内外の観光客が自然災害に迅速かつ適切に対応できるように、特に地震や津波に関する初期対応を明確に説明した動画を作成しました。内容には、旅行中の緊急時に知っておくべき災害防止の重要なヒント、役立つアイテムやガジェットの紹介、和歌山災害防止ナビゲーションアプリと災害防止のリーフレットの紹介が含まれています。' where id = 'ZIkpE3CvVnsT-vkUhibyR';
update content_bodies set title = 'Disaster preparedness videos now available!!', description = 'To assist both domestic and international tourists in responding effectively during natural disasters, we have produced a video that outlines essential initial responses, focusing on earthquakes and tsunamis. The content includes key disaster prevention tips for travelers, an introduction to useful items and gadgets, and information about the Wakayama Disaster Prevention Navigation App along with disaster prevention leaflets.' where id = 'UPbRYiFtp0fG-16W7PFeV';
