update content_bodies set title = 'JR西日本×和歌山県　わかやま線サイクルトレイン', description = 'ご乗車には予約が必要です！公式サイトより予約をお願いします。ご利用前に必ずご一読ください。施設情報として、旧名手宿本陣、道の駅青洲の里（春林軒）、粉河寺、力寿し、藤桃庵（桃のしあわせ館）、プチツール、T-NARUSEなどがあります。' where id = 'wogUWoBzprtkol0GlHQmb';
update content_bodies set title = 'JR West Japan x Wakayama Prefecture: Wakayama Line Cycle Train', description = 'Reservations are required to board! Please make a reservation through the official website. Be sure to read the information before use. The facilities include the former Nate-juku Honjin, Roadside Station Seishunosato, Kokawadera Temple, Chikara Sushi, Toutouan (Peach Happiness Hall), Petite Tour, and T-NARUSE.' where id = 'TLXLikhhLJ4FQ2LzRjI0i';
update content_bodies set title = '今日は和歌山の日　～女子旅～', description = '和歌山県南部の熊野エリアを楽しむ女子旅プランを紹介します。普段運動しない方にもおすすめの熊野古道「大門坂」を歩き、熊野那智大社や那智山青岸渡寺、那智の滝を参拝します。歩いた後は足湯で癒やし、マグロ丼でエネルギーを補給。太平洋を望む絶景温泉が楽しめる宿に宿泊します。2日目は、珍しい鯨類専門の博物館やインスタ映えスポットの橋杭岩を訪れ、熊野エリアの見どころを満喫できる1泊2日のモデルコースです。' where id = 'FavbXXMwTUODy0vAeYplh';
update content_bodies set title = 'Today is Wakayama Day - Girls'' Trip', description = 'This is a recommended girls'' trip plan to fully enjoy the Kumano area in southern Wakayama Prefecture. The itinerary includes a walk along the Kumano Kodo ''Daimon-zaka'', suitable for those who may not usually exercise, visiting Kumano Nachi Taisha, Nachi San Seiganto-ji, and Nachi Falls. After the walk, relax in a foot bath and recharge with a tuna bowl. Stay at a hotel with a stunning ocean-view hot spring. On the second day, drive to a unique whale museum and the popular Instagram spot, Hashikui-iwa, to enjoy the highlights of the Kumano area in a recommended one-night, two-day course.' where id = 'lSFuHw-COXdPCk6lGB-Hk';
update content_bodies set title = '今日は和歌山の日　～ペット旅～', description = '愛犬と共に楽しむ1泊2日のモデルプランで、有田、日高、和歌山市を巡ります。フルーツ狩りや海沿いのカフェ、グランピング、映える写真が撮れるアミューズメント施設などが含まれています。愛犬と一緒に楽しめるペットフレンドリーなスポットを巡るおすすめのプランです。' where id = 'FlVqya99kxU1oMQS5-HN0';
update content_bodies set title = 'Wakayama Day - Pet Travel', description = 'This is a model plan for a 1-night, 2-day trip with your beloved dog, exploring the areas of Arida, Hidaka, and Wakayama City. The itinerary includes fruit picking, seaside cafes, glamping, and amusement facilities where you can take Instagram-worthy photos. It is a recommended plan that allows you to enjoy pet-friendly spots with your dog.' where id = 'SL6M9vwWF9uKu2ccEth-C';
update content_bodies set title = '今日は和歌山の日　～ひとり旅・高野山～', description = '約1200年前に弘法大師空海が開いた高野山を、レンタサイクルで巡る1泊2日のモデルプランです。高野山は東西約6km、南北約3kmのコンパクトな街に117の寺院や見どころが集まっています。各スポットを自転車で移動し、散策を楽しんだ後は宿坊に宿泊。写経や阿字観（瞑想体験）、精進料理を体験し、心身ともにリラックスできます。日常の喧噪から離れ、高野山でゆったりとしたひとり時間を過ごしてみませんか。' where id = 'HVzwNWYgVHAEge_dExYfV';
update content_bodies set title = 'Koyasan: A Solo Journey on Wakayama Day', description = 'This is a 2-day, 1-night model plan to explore Koyasan, a religious city established by the monk Kukai (Kobo Daishi) about 1,200 years ago, using rental bicycles. Koyasan is a compact area measuring approximately 6 km east to west and 3 km north to south, filled with 117 temples and attractions. Visitors can cycle between various spots, enjoy a stay at a temple lodging, and partake in activities such as sutra copying, meditation (Ajikan), and shojin ryori (Buddhist vegetarian cuisine), allowing for relaxation of both body and mind. Escape the daily hustle and spend some peaceful time in Koyasan.' where id = 'SvhJ3Gc65x3zN8xzD7wLO';
update content_bodies set title = '今日は和歌山の日　～ひとり旅・高野山～', description = '約1200年前、弘法大師空海が開いた高野山を巡る1泊2日のモデルプランです。高野山は東西約6km、南北約3kmのコンパクトな街に117の寺院や見どころが集まっています。レンタサイクルで各スポットを移動し、街中を散策した後は宿坊に宿泊。写経や阿字観（瞑想体験）、精進料理を楽しみ、心身をリラックスさせることができます。日常の喧噪から離れ、高野山でゆったりとしたひとり時間を過ごしてみませんか。' where id = '68sYu3lKnQE2iY1atmhd_';
update content_bodies set title = 'Wakayama Day - Solo Trip to Mount Koya', description = 'This is a model plan for a 1-night, 2-day trip to Mount Koya, a religious city established by the monk Kukai (Kobo Daishi) about 1,200 years ago. Mount Koya is a compact area measuring approximately 6 km east to west and 3 km north to south, featuring 117 temples and attractions. Visitors can explore the area using rental bicycles, and after a day of sightseeing, they can stay at a temple lodging, enjoying activities such as sutra copying, meditation (Ajikan), and shojin ryori (Buddhist vegetarian cuisine) for relaxation. Escape the daily hustle and bustle and spend some peaceful time alone in Mount Koya.' where id = 'XfQJKj0rI8JdeKWL-vPM_';
update content_bodies set title = '今日は和歌山の日　～ひとり旅・高野山～', description = '約1200年前に弘法大師空海が開いた高野山を巡る1泊2日のモデルプランです。高野山は東西約6km、南北約3kmのコンパクトなエリアに117の寺院や見どころが集まっています。レンタサイクルを利用して各スポットを移動し、街中を散策した後は宿坊に宿泊。写経や阿字観（瞑想体験）、精進料理を楽しむことで、心身ともにリラックスできます。日常の喧噪から離れ、高野山でゆったりとしたひとり時間を過ごしてみませんか。' where id = 'jnJDw7Xsjpeqm4aQwsx3a';
update content_bodies set title = 'Koyasan: A Solo Journey in Wakayama', description = 'This is a 2-day model plan for exploring Koyasan, a religious city established by the monk Kukai (Kobo Daishi) about 1,200 years ago. Koyasan is a compact area measuring approximately 6 km east to west and 3 km north to south, featuring 117 temples and attractions. Visitors can use rental bicycles to navigate between various spots. After exploring the town, guests can stay at a shukubo (temple lodging), where they can enjoy activities such as sutra copying, Ajikan meditation, and shojin ryori (Buddhist vegetarian cuisine), allowing for relaxation of both mind and body. Escape the hustle and bustle of daily life and spend some peaceful time in Koyasan.' where id = 'aCX5hE-dx8lkLGztmkNqr';
update content_bodies set title = 'なななさんの“WAKAYAMA800”おいしいとこだけサイクリング！ショート版', description = 'この動画では、なななさんが行う“WAKAYAMA800”のサイクリングのショート版を紹介しています。美味しいスポットを巡る内容で、和歌山の魅力を短時間で楽しむことができます。' where id = '72LAdWubu5ZXBPgS5hGZJ';
update content_bodies set title = 'Nanana''s ''WAKAYAMA800'' Delicious Cycling! Short Version', description = 'This video introduces Nanana''s ''WAKAYAMA800'' Delicious Cycling! Short Version.' where id = 'SuNR3Kl4CM1nGseb7htl-';
update content_bodies set title = '今日は和歌山の日　～女子旅～', description = '和歌山県南部の熊野エリアを楽しむ女子旅プランを紹介します。普段運動しない方にもおすすめの熊野古道「大門坂」を歩き、熊野那智大社や那智山青岸渡寺、那智の滝を参拝します。歩いた後は足湯で癒やし、マグロ丼でエネルギーを補給。太平洋を望む絶景温泉が楽しめる宿に宿泊します。2日目は、珍しい鯨類専門の博物館やインスタ映えスポットの橋杭岩を訪れ、熊野エリアの見どころを満喫できる1泊2日のモデルコースです。' where id = 'hPbasfx-Vu4yWwMmNMI08';
update content_bodies set title = 'Today is Wakayama Day - Girls'' Trip', description = 'This is a recommended girls'' trip plan to fully enjoy the Kumano area in southern Wakayama Prefecture. The itinerary includes a walk along the Kumano Kodo ''Daimon-zaka'', suitable for those who may not usually exercise, visiting Kumano Nachi Taisha, Nachi San Seiganto-ji, and Nachi Falls. After the walk, relax in a foot bath and recharge with a tuna bowl. Stay at a hotel with a stunning ocean-view hot spring. On the second day, drive to a unique whale museum and the popular Instagram spot, Hashikui-iwa, to enjoy the highlights of the Kumano area in a recommended one-night, two-day course.' where id = 'hHv1ZnDBvKMcdrw-5krZf';
update content_bodies set title = '今日は和歌山の日　～女子旅～', description = '和歌山県南部の熊野エリアを楽しむ女子旅プランを紹介します。普段運動しない方にもおすすめの熊野古道「大門坂」を歩き、熊野那智大社や那智山青岸渡寺、那智の滝を参拝します。歩いた後は足湯で癒やし、マグロ丼でエネルギーを補給。太平洋を望む絶景温泉が楽しめる宿に宿泊します。2日目は、珍しい鯨類専門の博物館やインスタ映えスポットの橋杭岩を訪れ、熊野エリアの見どころを満喫できる1泊2日のモデルコースです。' where id = 'zHSq8EIyldJ0mpQ7FNdPm';
update content_bodies set title = 'Today is Wakayama Day - Girls'' Trip', description = 'This is a recommended girls'' trip plan to fully enjoy the Kumano area in southern Wakayama Prefecture. The itinerary includes a walk along the Kumano Kodo ''Daimon-zaka'', suitable for those who may not usually exercise, visiting Kumano Nachi Taisha, Nachi San Seiganto-ji, and Nachi Falls. After the walk, relax in a foot bath and recharge with a tuna bowl. Stay at a hotel with a stunning ocean-view hot spring. On the second day, drive to a unique whale museum and the popular Instagram spot, Hashikui-iwa, to enjoy the highlights of the Kumano area in a recommended one-night, two-day course.' where id = 'SxAE1Z2BSA83JASsoHS0_';
update content_bodies set title = 'なななさんの“WAKAYAMA800”のおいしいとこだけ！サイクリング', description = '自転車系YouTubeチャンネル「なななチャンネル」のなななさんが和歌山県の美味しいスポットを巡るサイクリングを楽しみました。絶景を堪能し、地元の人気グルメを味わうことができました。また、自転車をそのまま電車に乗せることができる「サイクルトレイン」を利用し、初心者でも欲張りなコースを走ることが可能です。さらに、サイクリストに優しい宿「ベーカリーホテル」に宿泊し、大切な自転車を部屋に置ける安心感を得ました。朝食にはホテル併設のベーカリーで焼きたてのパンを楽しみました。' where id = 'hyQaS0-4CJP4_hXBQtd2X';
update content_bodies set title = 'Nanana''s Delicious Cycling Adventure in WAKAYAMA800!', description = 'Nanana from the cycling YouTube channel ''Nanana Channel'' enjoyed a cycling trip focused on the delicious spots in Wakayama Prefecture. She experienced breathtaking views and popular local gourmet foods. Additionally, she took advantage of the ''Cycle Train,'' which allows cyclists to bring their bikes on the train, making it easier for beginners to explore ambitious routes. Furthermore, she stayed at the cyclist-friendly ''Bakery Hotel,'' where she could safely keep her bike in her room. In the morning, she enjoyed freshly baked bread from the hotel''s bakery!' where id = '-uKoO4bCUOCTaQ74OHWgw';
update content_bodies set title = '今日は和歌山の日　～家族旅～', description = '和歌山市、紀美野町、紀の川市を1泊2日で巡るモデルプランです。自然と食を楽しむ5つのエリアがあり、道の駅では地元の産品や農家が作るジェラートを味わえます。また、肉眼で天の川を観察できる天文台やご当地の和歌山ラーメン、ラッピング列車でのねこ駅長との出会いも楽しめます。お子さんも大満足の内容で、家族全員が楽しめるプランです。' where id = 'FUNW6nNKuRzkzLqMgBZU-';
update content_bodies set title = 'Wakayama Day - Family Trip', description = 'This model plan for a 1-night, 2-day trip covers Wakayama City, Kimino Town, and Kinokawa City. It offers a delightful experience of nature and food across five areas, including a roadside station with local produce, gelato made by farmers, an observatory where you can see the Milky Way, local Wakayama ramen, and a chance to meet the cat stationmaster on a themed train. This plan is sure to satisfy children and families alike.' where id = 'ZPvg0Y0W_HUE9N_6KvqiD';
update content_bodies set title = '今日は和歌山の日　～家族旅～', description = '和歌山市、紀美野町、紀の川市を1泊2日で巡るモデルプランです。自然と向き合い、食を楽しむ5つのエリアがあり、道の駅や農家が作るジェラート、肉眼で天の川が見える天文台、地元の和歌山ラーメン、ラッピング列車でのねこ駅長との出会いなど、お子さんも大満足の内容となっています。' where id = 'TRJHBxn0NpyOPRvkjYpkD';
update content_bodies set title = 'Wakayama Day - Family Trip', description = 'This model plan features a 1-night, 2-day trip through Wakayama City, Kimino Town, and Kinokawa City. Enjoy nature and local cuisine at five different areas, including a roadside station, gelato made by local farmers, an observatory where you can see the Milky Way with the naked eye, local Wakayama ramen, and a chance to meet the cat stationmaster on a themed train. This plan promises satisfaction for both children and adults.' where id = 'GDdFN-VoV9TRLmofrtmnf';
update content_bodies set title = '今日は和歌山の日　～家族旅～', description = '和歌山市、紀美野町、紀の川市を1泊2日で巡るモデルプランです。自然と触れ合いながら、地元の食を楽しむことができる5つのエリアを訪れます。道の駅や農家が作るジェラート、肉眼で天の川を観察できる天文台、地元の和歌山ラーメン、ラッピング列車でのねこ駅長との出会いなど、お子さんも大満足の内容です。' where id = 'sijrXcscEIDsDqALKE9j0';
update content_bodies set title = 'Wakayama Day - Family Trip', description = 'This model plan outlines a 1-night, 2-day trip through Wakayama City, Kimino Town, and Kinokawa City. It offers a chance to connect with nature and enjoy local cuisine across five areas, including a roadside station, gelato made by local farmers, an observatory where you can see the Milky Way with the naked eye, local Wakayama ramen, and a chance to meet the cat station master on a wrapped train. This plan is sure to delight children and families alike.' where id = 'GG7VaS8u0TVSPdpo68qqX';
update content_bodies set title = '【Full HD】志摩スペイン村　ピレネー最前列【1080p】', description = '志摩スペイン村で、ジェットコースター好きのための「ピレネー」の最前列に乗った様子をお届けします。迫力満点の映像をお楽しみください。特別に許可を得て撮影したこの映像には、2017年度津クイーンの井本水夏さんが登場します。志摩スペイン村パルケエスパーニャは、インスタ映えスポットが満載で、アトラクションだけでなく多くの魅力を楽しむことができます。三重県の観光情報や宿泊予約については、三重県観光連盟の公式サイトをご覧ください。' where id = 'wVWjNmdajks-Jryaub8Dz';
update content_bodies set title = 'Shima Spain Village: Front Row on the Pyrenees Coaster [1080p]', description = 'This video showcases a thrilling ride on the Pyrenees roller coaster at Shima Spain Village, perfect for coaster enthusiasts. Enjoy the exhilarating visuals captured with special permission. The video features Mizuka Imoto, the 2017 Tsu Queen. Shima Spain Village, also known as Parque Espana, is filled with Instagram-worthy spots and offers a variety of attractions beyond just rides. For more information on tourism in Mie Prefecture, including events and accommodations, visit the official Mie Prefecture Tourism Federation website.' where id = 'R2a9fEfraow70ViqaniVg';
update content_bodies set title = '名古屋発！Re:和歌山・熊野の”とっておき”に出逢う。', description = 'この動画では、名古屋を出発点として、和歌山・熊野の隠れた魅力や特別なスポットを紹介しています。' where id = 'A2uI77W0zlURVbsuazHEz';
update content_bodies set title = 'Discovering the Hidden Gems of Kumano, Wakayama from Nagoya', description = 'This video introduces the hidden gems of Kumano, Wakayama, starting from Nagoya.' where id = 'zjjwRYwysYGo46DULBgH4';
update content_bodies set title = '写真で楽しむ世界遺産「紀伊山地の霊場と参詣道」～和歌山県 高野山編', description = '2024年12月、フォトグラファーの鎌田風花さんが丹生都比売神社から高野山を訪れ、「写真で楽しむ」をテーマにした内容です。高野山は、真言密教の聖地として1200年以上にわたり多くの信仰を集めてきました。このエリアは自然と文化が織り成す美しい景色が広がっており、訪れる人々に感動を与えています。' where id = 'LsgqIf59V9ngnRf1M8yjZ';
update content_bodies set title = 'Enjoying World Heritage through Photography: Kii Mountain Range Pilgrimage Routes - Mount Koya Edition', description = 'In December 2024, photographer Fuka Kamada visited the Niu Tamataregu Shrine to Mount Koya, focusing on the theme of ''enjoying through photography.'' Mount Koya, a sacred site of Shingon Buddhism, has attracted many believers for over 1,200 years and encompasses the surrounding area. Visitors can experience the beautiful scenery created by the intertwining of nature and culture.' where id = '6GjzjSIL9-Vu2FC1lVQRo';
