update content_bodies set title = 'しょうゆ蔵', description = 'この動画はしょうゆ蔵について紹介しています。しょうゆ蔵は、伝統的な製法でしょうゆを醸造する場所であり、地域の文化や歴史と深く結びついています。動画では、しょうゆの製造過程や使用される原材料、そしてその独特な風味について詳しく説明されています。また、しょうゆ蔵の役割や重要性についても触れられており、視聴者にとって興味深い内容となっています。' where id = 'WniPz5V9JWev3_ozYn31M';
