update content_bodies set title = '紀州漆器', description = 'この動画は紀州漆器について紹介しています。紀州漆器は、日本の伝統的な漆器の一つで、特に和歌山県で生産されています。美しいデザインと高い耐久性が特徴で、日常使いから贈り物まで幅広く利用されています。漆の塗り重ねや細かな装飾技術が施され、職人の技が光る作品が多く見られます。' where id = 'nORlxV5VS2lDj0Kd6zJgs';
