update content_bodies set title = '蘇りの地　熊野', description = '熊野は和歌山に位置し、「蘇りの地」として知られています。この地域は文化的および精神的な重要性が高く、独自の遺産や自然の美しさを探求したい旅行者を惹きつけています。' where id = 'Rjpi0zDTAlNH2ebJ2ZrAy';
update content_bodies set title = 'Land of Resurrection: Kumano', description = 'Kumano, located in Wakayama, is often referred to as the ''Land of Resurrection.'' This area is rich in cultural and spiritual significance, attracting travelers interested in exploring its unique heritage and natural beauty.' where id = 'AD2S_dtPr9bTyimwonTW9';
update content_bodies set title = '天空の聖地　高野山', description = '高野山は和歌山に位置し、「天空の聖地」として知られています。豊かな文化遺産と静かな雰囲気を持つこの場所は、多くの訪問者を惹きつける重要な精神的なスポットです。' where id = 'EtwPgo0HERhnwBmAfTOzF';
update content_bodies set title = 'Koyasan: The Sacred Land in the Sky', description = 'Koyasan, located in Wakayama, is often referred to as the ''Sacred Land in the Sky.'' It is a significant spiritual site, attracting visitors for its rich cultural heritage and serene atmosphere.' where id = 'fWowNyqM8Iy8zJgRuoWxd';
update content_bodies set title = 'アウトドアパーク、わかやまPR動画【１５秒】', description = 'アウトドアパーク、わかやまで和歌山ならではのアウトドアを楽しむことができます。キャンプや多様なアクティビティ、そして美しい自然を満喫しましょう。' where id = '2WbX5MFm-HckPY0D8-jFk';
update content_bodies set title = 'Outdoor Park, Wakayama PR Video [15 seconds]', description = 'Experience the unique outdoor activities that Wakayama has to offer at the Outdoor Park. Enjoy camping, various activities, and the beautiful nature of the region.' where id = 'hW5_CATm4w9rrLbBoFVvw';
update content_bodies set title = '【高野山観光】地元女性ガイドが明かす深い楽しみ方と絶対外せないポイント！初心者/リピーターも必見！', description = '和歌山県の世界遺産「高野山」を、地元出身のガイド西ノドカさんが紹介します。高野山をより深く楽しむためのポイントを解説し、初めて訪れる方やリピーターにとっても必見の内容です。動画では、総門「大門」や聖地「壇上伽藍」、重要文化財、宿坊体験、精進料理など、多彩な見どころが紹介されています。また、和歌山の他の観光スポットについての質問やリクエストも受け付けています。' where id = 'a8eRVOEz8NrjiQQ-dF9za';
update content_bodies set title = 'Exploring Mount Koya: Insights from a Local Female Guide on Must-See Points for Beginners and Repeat Visitors!', description = 'Mount Koya, a UNESCO World Heritage site in Wakayama Prefecture, is introduced by local guide Nodoka Nishino, who was born and raised there. She shares essential tips for a deeper and more enjoyable experience of Mount Koya, making it a must-watch for both first-time visitors and those returning. The video covers various highlights, including the main gate ''Daimon'', the sacred sites ''Danjo Garan'' and ''Okunoin'', important cultural properties, and unique experiences like staying at a temple and enjoying shojin ryori (Buddhist vegetarian cuisine). Viewers are encouraged to comment on other attractions in Wakayama they wish to learn about.' where id = '2tahcUGvsqJNn3doUfhUR';
update content_bodies set title = 'アウトドアパーク、わかやまPR動画【３分】', description = 'アウトドアパーク、わかやまで和歌山ならではのアウトドアを満喫することができます。キャンプや多様なアクティビティ、自然の美しさを楽しむことができる場所です。' where id = 'Tmb4SzOfZEjNo8FxgCxRK';
update content_bodies set title = 'Outdoor Park, Wakayama PR Video [3 Minutes]', description = 'Experience the unique outdoor activities that Wakayama has to offer at the Outdoor Park. Enjoy camping, various activities, and the natural beauty of the region.' where id = 'rG-nAm6uIgWWuCSVUJ1US';
update content_bodies set title = '【おすすめ】高知市内で絶対行ってほしいスポット【2023高知】', description = '高知市内の観光スポットを紹介します。追手筋・帯屋町エリアでは、美味しいグルメを楽しみながら歴史を学ぶことができます。桂浜エリアでは、龍馬と共に海を眺め、可愛い海の生き物に癒される水族館もあります。また、五台山エリアでは、牧野博士が愛した草花が風にそよぐ心地よい空間が広がっています。食べる・遊ぶ・学ぶを一度に楽しむことができるスポットです。主な場所には、日曜市、ひろめ市場、高知城、桂浜公園、桂浜水族館、牧野植物園があります。' where id = 'y3SucMqDQZXJHcv7qqAZV';
update content_bodies set title = 'Recommended Spots in Kochi City You Must Visit【2023 Kochi】', description = 'This article introduces must-visit tourist spots in Kochi City. Explore the Otesuji and Obiyamachi areas, where you can enjoy delicious food and learn about history. In the Katsurahama area, gaze at the sea alongside Ryoma and relax with adorable marine creatures at the aquarium. The Godaisan area offers a pleasant space filled with the flowers loved by Dr. Makino. Experience a combination of eating, playing, and learning all in one go! Key locations include Sunday Market, Hirome Market, Kochi Castle, Katsurahama Park, Katsurahama Aquarium, and Makino Botanical Garden.' where id = 'Kr9V-9P-A_syUR3797Dgv';
update content_bodies set title = '伊勢市にある、日本一“距離感ゼロ”な水族館を知ってますか?!', description = '伊勢市に位置するこの水族館は、訪問者が海の生き物と非常に近い距離で触れ合えるユニークな体験を提供しています。全国で3園館しか飼育されていないツメナシカワウソと握手したり、ゴマフアザラシをなでたり、タツノオトシゴを指に巻き付けたりすることができます。毎日多くのイベントが開催されており、特に土日は10個以上のアクティビティが用意されています。友達や恋人とのデートにも最適なスポットで、映えスポットも豊富です。メインイベントは屋外で行われるため、雨天時には雨具が必要です。伊勢シーパラダイスで忘れられない体験をしてみてください！' where id = 'RVBr1gb2h_M_8hQR0P3-v';
update content_bodies set title = 'Have you heard of Japan''s most ''zero-distance'' aquarium in Ise City?!', description = 'Located in Ise City, this aquarium offers an unparalleled experience where visitors can interact closely with marine life. You can shake hands with the rare clawless otter, pet a spotted seal, and even have a seahorse wrap around your finger. The aquarium hosts numerous events daily, with over ten activities on weekends, making it a perfect spot for dates with friends or loved ones. There are also many Instagram-worthy spots to capture memorable moments. Note that the main events are held outdoors, so rain gear is necessary on rainy days. Visit Ise Sea Paradise for an unforgettable experience!' where id = '_LXGzUIriH32t1J5d6EyZ';
update content_bodies set title = '【超穴場】和歌山の万能キャンプ場！SUP・カヤック・釣り・ダイビングも出来ちゃう！', description = '和歌山県のアウトドアスポットの中でも、まだあまり知られていない穴場を紹介します。特に「すさみ町」は、キャンプやアクティビティを楽しむには最適な場所です。これからの夏や秋に向けて、アウトドアを計画している方はぜひご覧ください。また、和歌山の観光スポットについての質問があれば、コメントで教えてください。' where id = 'dCVPsRmJyDc6TiSeGkX6N';
update content_bodies set title = 'Hidden Gem: A Versatile Campsite in Wakayama! Enjoy SUP, Kayaking, Fishing, and Diving!', description = 'This article introduces a lesser-known outdoor spot in Wakayama Prefecture, where various outdoor activities can be enjoyed. ''Susami Town'' is highlighted as a prime location for outdoor enthusiasts, especially as summer and autumn approach. Those planning camping or activities in Wakayama should definitely check it out! Readers are encouraged to ask questions about Wakayama''s tourist spots in the comments.' where id = 'cnCxOFSYn4Nu2zRB1QFOo';
update content_bodies set title = '六華苑（旧二代諸戸清六邸）【ドローン撮影】(桑名市)｜観光三重｜三重県の観光・旅行情報', description = '六華苑は、大正2年（1913年）に桑名の実業家、二代諸戸清六の新居として完成しました。4層の塔屋を持つ洋館は、著名な建築家ジョサイア・コンドルの設計によるもので、鹿鳴館を手掛けたことでも知られています。洋館に連結した和館や蔵、池泉回遊式庭園などがあり、創建当時の姿がほぼそのまま残されています。洋館と和館は国の重要文化財に指定されています。' where id = 'nWYLX1_hV60fD-_Te5_Gn';
update content_bodies set title = 'Rikkaen (Former Residence of Second Moroto Seiroku) [Drone Footage] (Kuwana City) | Tourism Mie | Mie Prefecture Travel Information', description = 'Rikkaen was completed in 1913 as the new residence of the prominent businessman Moroto Seiroku. This distinctive Western-style building features a four-story tower and was designed by the famous British architect Josiah Conder, who also worked on the renowned Rokumeikan. The property includes a Japanese-style building, storehouses, and a pond-style garden, all of which have largely retained their original appearance since its construction. Both the Western and Japanese buildings are designated as Important Cultural Properties of Japan.' where id = 'dDREDea0eepyubSc_EE3V';
update content_bodies set title = '全国旅行支援「わかやまリフレッシュプランワイドSワイド2nd」TVCM（TBS）', description = 'この動画は、全国旅行支援の一環として提供される「わかやまリフレッシュプランワイドSワイド2nd」のTVCMについて紹介しています。' where id = 'gkl3HzCJshoYBiClHHOxH';
update content_bodies set title = 'National Travel Support ''Wakayama Refresh Plan Wide S Wide 2nd'' TV Commercial (TBS)', description = 'This video introduces the national travel support program ''Wakayama Refresh Plan Wide S Wide 2nd'' TV commercial aired on TBS.' where id = 'LA0WQZaB6qiz6FlXKgdrZ';
update content_bodies set title = 'Cycle Sports　フォトグラファー・辻啓さん×WAKAYAMA800　カメラと巡る和歌山じてんしゃ旅', description = '世界的なサイクルフォトグラファーであり、サイクリスト、インフルエンサーとしても活躍する辻啓さんが、カメラを持って和歌山を自転車で巡ります。辻さんが推奨する和歌山のコースは、海、山、川といった多様な景観が楽しめるもので、まさにWAKAYAMA800の魅力を体現しています。このコースの詳細は、2023年2月20日発行の雑誌「Cycle Sports」4月号に掲載されています。' where id = 'EZ4fdsS4nwpxiyybTrJ7w';
update content_bodies set title = 'Cycle Sports Photographer Kei Tsuji x WAKAYAMA800: A Cycling Journey Through Wakayama with a Camera', description = 'Kei Tsuji, a world-renowned cycle photographer who captures domestic and international bicycle races, and is also an active cyclist and influencer, embarks on a cycling journey through Wakayama with his camera. Tsuji recommends a course in Wakayama that features a rich variety of landscapes, including the sea, mountains, and rivers, embodying the essence of WAKAYAMA800. Details of the course are featured in the April 2023 issue of ''Cycle Sports'' magazine, published on February 20, 2023.' where id = 'wdI4RL4wfzNBWLksNrLfA';
update content_bodies set title = '城ノ浜プールの魅力をご紹介！', description = '三重県紀北町に新たに誕生した「城ノ浜プール＆ビーチ」は、まるで水平線と一体化したようなインフィニティプールが特徴です。プールはインフィニティプールと子ども用プールの2種類があり、子ども用プールには楽しいアトラクションも用意されています。センターハウス内にはカフェがあり、軽食やドリンクを楽しむことができます。また、車で約3分の場所には「孫太郎オートキャンプ場」があり、おしゃれなグランピングドームで快適な宿泊や地元産の食材を使ったBBQが体験できます。家族旅行やデートにも最適なスポットです。営業期間は7月16日から8月31日まで、営業時間は9:30から16:00までで、紀勢道「紀伊長島IC」から車で約10分のアクセスです。' where id = 'HPtfJNsTTa0hDV25AhrFb';
update content_bodies set title = 'Introducing the Charm of Jōnohama Pool!', description = 'Located in Kihoku Town, Mie Prefecture, the new ''Jōnohama Pool & Beach'' features an infinity pool that creates the illusion of merging with the horizon. There are two types of pools: an infinity pool and a children''s pool with fun attractions. The center house includes a café offering light meals and drinks. Just a 3-minute drive away is the ''Magotaro Auto Campground,'' where visitors can enjoy stylish glamping domes and BBQs using local ingredients. This destination is perfect for family trips or dates. Operating from July 16 to August 31, the pool is open from 9:30 AM to 4:00 PM, accessible via a 10-minute drive from Kii Nagashima IC on the Kisei Expressway.' where id = 'HGL5uik4__JabbLJJYdsX';
update content_bodies set title = '和歌山 高野山', description = '今こそ、パワーみなぎる世界遺産・高野山へ出かけよう。2023年は高野山を開いた弘法大師空海の御誕生1250年にあたり、普段は非公開の御本尊の特別公開や限定御朱印など、パワースポット旅として注目が高まっています。いざ、遊休の歴史を紡ぐ高野山へ出かけよう！' where id = 'izJ8URnFu7ChH_a2-JRhb';
update content_bodies set title = 'Wakayama Koyasan', description = 'Now is the time to visit Koyasan, a UNESCO World Heritage site filled with spiritual energy. The year 2023 marks the 1250th anniversary of the birth of Kobo Daishi Kukai, the founder of Koyasan. This special occasion includes the rare public opening of the main deity and limited edition goshuin (temple stamps), drawing attention to Koyasan as a power spot travel destination. Let''s embark on a journey to Koyasan, where history unfolds.' where id = 'qWpQEPPz1dGHVGs5leL5m';
update content_bodies set title = 'WAKAYAMA800×JRきのくに線サイクルトレイン', description = 'きのくに線サイクルトレインは、自転車を持ったままJRきのくに線を利用できるサービスです。利用する前に、必ず提供された情報を確認することが重要です。詳細については、公式ウェブサイトを訪れてください。' where id = 'KYtOHfDTUq-uzzBs0yr0V';
update content_bodies set title = 'WAKAYAMA800 × JR Kinokuni Line Cycle Train', description = 'The Kinokuni Line Cycle Train is a service that allows cyclists to travel with their bicycles on the JR Kinokuni Line. Before using the service, it is essential to read the provided information. For more details, visit the official website.' where id = 'mM8JiqzS4e7bSrbTVIxzd';
update content_bodies set title = 'わかやま「おもてなし宣言」研修動画', description = '「わかやまおもてなし宣言」は、和歌山県を訪れる方々に「和歌山に来てよかった」と感じてもらい、再訪を促すことを目的としています。この宣言は、県民自らが「おもてなし」を実践することを奨励するものです。本動画は、いつでもどこでもおもてなしの心やマナーを学べるように、7つの動画コンテンツとして提供されています。内容は、心に届くあいさつ、気持ちを伝える話し方、良い印象を与える身だしなみ、正しい姿勢、心を伝えるおじぎ、感じの良い電話応対、心のバリアフリーについてです。' where id = 'rtcgQha8OxVQtknr-Lwv5';
update content_bodies set title = 'Wakayama ''Omotenashi Declaration'' Training Video', description = 'The ''Wakayama Omotenashi Declaration'' aims to ensure that visitors to Wakayama feel that they are glad to have come and wish to return. This initiative encourages residents to practice hospitality. The training video is designed to allow anyone to learn about the spirit and manners of hospitality anytime and anywhere, featuring seven video segments. These segments cover topics such as effective greetings, conveying feelings through speech, presenting a good impression through appearance, maintaining proper posture, bowing to express sincerity, pleasant telephone etiquette, and creating a barrier-free environment.' where id = '8imnfQh9o1xBwHPdH6HTS';
update content_bodies set title = '全国旅行支援「わかやまリフレッシュプランワイドSワイド2nd」TVCM（TOKYO MX）', description = 'この動画は、全国旅行支援の一環として提供される「わかやまリフレッシュプランワイドSワイド2nd」のTVCMを紹介しています。このプランは、旅行を通じて地域の活性化を図ることを目的としており、特に和歌山県の魅力を伝える内容となっています。TOKYO MXで放送されるこのCMは、視聴者に和歌山の観光地や体験を促進することを意図しています。' where id = '6NfC0NNwbWjInFozQ6qQp';
update content_bodies set title = 'National Travel Support ''Wakayama Refresh Plan Wide S Wide 2nd'' TVCM (TOKYO MX)', description = 'This video introduces the national travel support program ''Wakayama Refresh Plan Wide S Wide 2nd'' TV commercial aired on TOKYO MX.' where id = '6BgYymDXt5SxpMb32stFW';
update content_bodies set title = '全国旅行支援「わかやまリフレッシュプランワイドSワイド2nd」TVCM（フジテレビ）', description = 'この動画は、全国旅行支援の一環として提供される「わかやまリフレッシュプランワイドSワイド2nd」のTVCMを紹介しています。このプランは、旅行を促進するための支援策の一つであり、観光地の魅力を伝えることを目的としています。' where id = 'B-TGsSNC4IPzR5M91a0Y1';
update content_bodies set title = 'National Travel Support ''Wakayama Refresh Plan Wide S Wide 2nd'' TV Commercial (Fuji TV)', description = 'This video introduces the TV commercial for the national travel support program ''Wakayama Refresh Plan Wide S Wide 2nd''.' where id = 'e_v3p7u1EnmYMldZ4FYk3';
update content_bodies set title = '和歌山県アウトドアPR動画', description = 'この動画は和歌山県のアウトドア活動を紹介しています。' where id = '3od-zu5oJCjOgvB_4_r79';
update content_bodies set title = 'Wakayama Prefecture Outdoor PR Video', description = 'This video introduces the outdoor activities available in Wakayama Prefecture.' where id = 'KkeU7o8tTER-8Ju22iDXQ';
update content_bodies set title = '紀州浪漫 2022冬号「温泉に癒されて 大地を感じる旅」', description = '田辺市本宮町に位置する熊野本宮温泉郷には、異なる魅力を持つ3つの温泉があります。熊野詣での湯垢離場としての歴史を持つ湯の峰温泉、河原を掘ることで温泉が湧き出る川湯温泉、広大な露天風呂が自慢のわたらせ温泉です。これらの温泉を最大限に楽しむために、七越峰トレッキングや熊野古道の散策など、自然の中でのアクティビティを体験してみてはいかがでしょうか。' where id = 'r6buULJNstQ0m6KDXdcpx';
update content_bodies set title = 'Kishu Romance Winter 2022: A Journey to Heal in Hot Springs and Feel the Earth', description = 'Kumano Hongu Onsen area in Tanabe City, Hongu Town, features three distinct hot springs. Yunomine Onsen, known for its historical significance as a purification site for Kumano pilgrimage, offers a unique experience. Kawarayu Onsen allows visitors to dig in the river to find hot spring water, while Watarase Onsen boasts expansive outdoor baths. To fully enjoy the hot springs, consider engaging in outdoor activities such as trekking at Nanako Peak or walking along the Kumano Kodo trail.' where id = 'J5sFhic5Zhg33qTls2Jw1';
update content_bodies set title = '和歌山県の自然をアウトドアで満喫', description = 'この動画では、和歌山県の自然をアウトドアで楽しむ方法について紹介しています。和歌山県は美しい自然環境に恵まれており、様々なアウトドアアクティビティを通じてその魅力を体験することができます。山や海、川など、多様な自然が広がるこの地域で、訪れる人々は新鮮な空気を吸い込みながら、リフレッシュすることができるでしょう。' where id = 'zOSNVFKNwNyVaapNCQuH8';
update content_bodies set title = 'Wakayama Prefecture''s Nature Enjoyed Outdoors', description = 'This video introduces the enjoyment of nature in Wakayama Prefecture through outdoor activities.' where id = 'MBbV5D5VYqPBwb1ykHoy6';
update content_bodies set title = '【仁淀ブルー】日本一青い夏【高知旅】', description = '高知県の仁淀ブルーを楽しむ旅に出かけませんか？家族全員が笑顔になれるスポットがたくさんあります。高知の夏を存分に楽しみましょう！この動画では、仁淀川アウトドアセンター、にこ淵、安居渓谷、中津渓谷、レストランポンテ、浅尾沈下橋、まきのさんの道の駅・佐川おもちゃ美術館など、さまざまな場所が紹介されています。それぞれの場所は独自の体験と美しい景色を提供しており、高知の自然の美しさを探求するための理想的な旅行ガイドとなっています。' where id = 'SKqcSn8rWNNiuHof7g0zt';
update content_bodies set title = 'Niyodo Blue: Japan''s Bluest Summer in Kochi', description = 'Embark on a journey to experience Niyodo Blue in Kochi Prefecture, a destination filled with spots that will bring smiles to the whole family. Enjoy the summer in Kochi to the fullest! The video features various locations including the Niyodo River Outdoor Center, Nikobuchi, An''yo Valley, Nakatsu Valley, Restaurant Ponte, Asaoshinkabashi, and the Sagawa Toy Museum. Each location offers unique experiences and beautiful scenery, making it an ideal travel guide for those looking to explore the natural beauty of Kochi.' where id = 'g97Coki-c_m5Ak7PvmZhw';
update content_bodies set title = 'RE KUMANO ～熊野の水と森～', description = '「RE KUMANO」は、Retreat・Relax・Rebornの三つのキーワードを基に、熊野の水と森の魅力を紹介するPR動画です。熊野に深い縁のある作家の荒俣宏氏と夢枕獏氏が、熊野本宮大社旧社地や那智の滝などのスポットを巡ります。熊野の魅力に触れ、ぜひ訪れてみてください。この取り組みは、世界遺産登録15周年を契機に設立された「高野山・熊野を愛する100人の会」によって支えられており、紀伊山地の霊場と参詣道の価値を継承し、魅力を発信する活動を行っています。' where id = '6VXAGmFau8aTd7Uc4qJLb';
update content_bodies set title = 'RE KUMANO - Water and Forest of Kumano', description = 'RE KUMANO is a promotional video that highlights the charm of Kumano''s water and forests, centered around the keywords Retreat, Relax, and Reborn. The video features authors Hiroshi Aramata and Baku Yumemakura, both deeply connected to Kumano, as they explore significant sites such as the Kumano Hongu Taisha Old Shrine Site and Nachi Falls. Viewers are encouraged to experience the allure of Kumano and visit the region. The initiative is supported by the ''100 People Who Love Koyasan and Kumano'' group, established in July 2019 to promote the value of the World Heritage site and its spiritual paths, offering various activities including online lectures on the attractions of Koyasan and Kumano.' where id = '8ErY0nDOamaYm5fp2a-Ue';
update content_bodies set title = '紀州浪漫2022夏', description = '紀州浪漫2022夏では、和歌山の自然を楽しむアクティビティとして、クリスタルリバー「古座川」でのカヌー体験を紹介しています。カヌーに乗って川を下ることは心地よいだけでなく、澄んだ水のおかげで川底まで見通せるという感動的な体験ができます。この素晴らしい体験を通じて、自然の美しさを満喫してみませんか。サポートはKAC古座川アドベンチャー倶楽部が行っています。' where id = '6cFsNw9lUlSq5ROHfkMW-';
update content_bodies set title = 'Kishu Romance Summer 2022', description = 'Experience the beauty of nature in Wakayama with a canoe ride on the crystal-clear Kozagawa River. Not only is it enjoyable to paddle down the river, but the clarity of the water allows you to see all the way to the riverbed, providing a truly breathtaking experience. Supported by the Kozagawa Adventure Club.' where id = 'NSxQeGXaZcUNdZi68imPF';
update content_bodies set title = '和歌山、日本 / 長い英語版', description = 'このコンテンツは、和歌山に関する長い英語版を紹介しています。短いバージョンを見たい方は、リンクされた動画（https://youtu.be/R5lSBvoT-aw）をご覧ください。' where id = 'Amuc0rvogX6o3WM8cx75P';
update content_bodies set title = 'Wakayama Japan / long English ver', description = 'This content features a long English version about Wakayama, Japan. For a shorter version, viewers can watch the linked video at https://youtu.be/R5lSBvoT-aw.' where id = 'O5PBq7VBXQKq6dCkF1GYo';
update content_bodies set title = '紀州浪漫2022秋　秋は和歌山でレトロモダン探しの旅', description = '世界遺産エリアの熊野に位置する新宮市は、大正・昭和初期の著名な建築家、西村伊作の故郷です。今もなお、西村伊作にゆかりのあるレトロモダンな建築物が残り、芸術と文化が息づく町です。この秋、世界遺産巡りに加え、フォトジェニックな建築を訪れながら文化に触れてみませんか。観光情報誌「紀州浪漫」では、他にもレトロモダンな建築を訪ねる旅を紹介しています。' where id = '8aXehROZSWq_BXf59AZXG';
update content_bodies set title = 'Kishu Romance Autumn 2022: A Journey to Discover Retro Modern in Wakayama', description = 'Shingu City, located in the World Heritage area of Kumano, is the hometown of the renowned architect Isaku Nishimura, who represents the Taisho and early Showa periods. The city still retains retro modern architectural structures associated with Nishimura, exuding an atmosphere of art and culture. This autumn, why not explore the World Heritage sites while also discovering photogenic buildings and immersing yourself in the local culture? The travel information magazine ''Kishu Romance'' also introduces other journeys to visit retro modern architecture.' where id = 'wPd9VkUasWJoqfxHxgnn8';
update content_bodies set title = '全国旅行支援「わかやまリフレッシュプランワイドSワイド2nd」TVCM（TBS）', description = '東京（羽田）から南紀白浜への臨時便は、令和5年2月27日（月）まで運行されます。' where id = 'RebgbmWnttN42BMyj4-5L';
update content_bodies set title = 'National Travel Support ''Wakayama Refresh Plan Wide S Wide 2nd'' TV Commercial (TBS)', description = 'The temporary flights from Tokyo (Haneda) to Nanki Shirahama will operate until February 27, 2023.' where id = 'ET0eF3A7pKrhzvvsTHi1f';
update content_bodies set title = '和歌山、日本 / 短い英語版', description = 'これは和歌山、日本に関する短い英語版です。詳細な内容を知りたい方は、提供されたYouTubeリンクから長い英語版をご覧ください。' where id = 'DnfPnQXr-2tq1TvZM1Wf3';
update content_bodies set title = 'Wakayama Japan / short English ver', description = 'This is a short English version about Wakayama, Japan. For a more detailed exploration, you can watch the long English version available at the provided YouTube link.' where id = 'mtj5ZXKY_-cyw7g-zXya6';
update content_bodies set title = '熊野エリア', description = '熊野エリアは、滝や岩、川などの自然を神として崇敬する自然崇拝の聖地です。この地域では、聖地熊野へ続く巡礼の道である熊野古道を歩く参詣者を癒す温泉や、日本で唯一の飛び地の村での筏下り体験など、他にはないユニークな体験ができます。詳細については、「和み、わかやま」のロングバージョンを[こちら](https://www.youtube.com/watch?v=Al8aE_zTeGI&t=936s)、ショートバージョンを[こちら](https://www.youtube.com/watch?v=gS86Dozo2os&t=15s)でご覧ください。' where id = 'T5qk7VF2wxQphxRNkvn8t';
update content_bodies set title = 'Kumano Area', description = 'The Kumano area is a sacred site of nature worship, where natural elements like waterfalls, rocks, and rivers are revered as deities. Visitors can experience unique activities such as walking the Kumano Kodo pilgrimage routes leading to the sacred Kumano, relaxing in hot springs that soothe pilgrims, and enjoying rafting experiences in Japan''s only exclave village. For more information, you can watch the long version of ''Nagomi, Wakayama'' [here](https://www.youtube.com/watch?v=Al8aE_zTeGI&t=936s) and the short version [here](https://www.youtube.com/watch?v=gS86Dozo2os&t=15s).' where id = 'alXhUIGhg2WadPel8r9nK';
update content_bodies set title = '有田・日高エリア　～和み、わかやま～', description = '「有田・日高エリア」は、入り組んだ海岸部の風光明媚な景色と深い山あいが広がる地域です。ここでは、自然の恵みを受けた特産物が豊富に揃い、有田みかんや湯浅醤油、金山寺味噌、幻の魚クエ、南高梅などが楽しめます。白い岩と青い海の美しいコントラストや、四季折々に変化する棚田など、写真映えするスポットも多く、訪れる人々を魅了します。' where id = 'XmFZYd7DFTklZNHumhihD';
update content_bodies set title = 'Arita and Hidaka Area - Nagomi, Wakayama', description = 'The Arita and Hidaka area, known for its scenic coastal landscapes and deep mountainous regions, is a treasure trove of natural beauty. This area is rich in local specialties such as Arita mikan (mandarins), Yuasa soy sauce, Kaneyama miso, the elusive fish called Kue, and Nanko ume (plum). Visitors can enjoy stunning views characterized by the contrast of white rocks and blue seas, as well as picturesque terraced rice fields that change with the seasons, making it a perfect spot for photography.' where id = '-6psDSh5Bpb8T-3uxKXRz';
update content_bodies set title = '高野山エリア　～和み、わかやま～', description = '高野山エリアは、弘法大師空海によって開かれた天空の聖地であり、弘法大師に関連する見どころが集まっています。高野山には50以上の宿坊があり、精進料理や写経、瞑想を体験することができ、自分を見つめ直す旅に最適です。また、武将・真田幸村にゆかりのある寺院や、天野の里にある高野山ゆかりの神社も訪れる価値があります。' where id = 'TJy9097Ll3CgD7xHYhoVy';
update content_bodies set title = 'Koyasan Area - Harmony, Wakayama', description = 'The Koyasan area, a sacred place in the sky opened by Kobo Daishi Kukai, is rich in attractions related to him. Visitors can experience shojin ryori (Buddhist vegetarian cuisine), sutra copying, and meditation at over 50 shukubo (temple lodgings) in Koyasan, making it a journey for self-reflection. Additionally, there are temples associated with the warrior Sanada Yukimura and shrines linked to Koyasan in the nearby Amano region, which are also worth visiting.' where id = '7P--jKGi6TQU_k79fxOOM';
update content_bodies set title = '和歌山市近郊エリア　～和み、わかやま～', description = '「和み、わかやま」エリアは、徳川御三家の一つである紀州藩の居城・和歌山城や根来寺、粉河寺などの歴史的な名所が点在しています。また、万葉集に詠まれた美しい景勝地や、アニメの舞台のような無人島など、インスタ映えする絶景スポットも豊富です。さらに、和歌山ラーメンやフルーツなどの地元グルメも楽しめ、サイクリストにとっても魅力的なエリアとなっています。' where id = 'm1vKuO44JVSXvKYEsvkYj';
update content_bodies set title = 'Wakayama City and Surrounding Area - Nagomi, Wakayama', description = 'The ''Nagomi, Wakayama'' area features historical sites such as Wakayama Castle, the residence of the Kishu Domain, one of the Tokugawa''s three major families, as well as Negoro-ji Temple and Koyakadera Temple. It is home to scenic spots celebrated in the Manyoshu, and uninhabited islands that resemble anime settings, making it a perfect location for Instagram-worthy photos. Additionally, the area offers delicious local cuisine, including Wakayama ramen and fruits, and is also a great destination for cyclists.' where id = 'irr3JA_fO6B2f2e5jFi_l';
update content_bodies set title = '蘇りの聖地　熊野', description = '深く豊かな自然に抱かれた熊野を旅すると、再生へと導かれるような不思議なパワーを感じることができます。この旅は和歌山の『蘇りの聖地　熊野』に表現されています。詳細は、長バージョンをこちらでご覧いただけます: https://www.youtube.com/watch?v=Al8aE_zTeGI&t=936s、短バージョンはこちら: https://www.youtube.com/watch?v=gS86Dozo2os&t=15sです。' where id = '-v1mnQF-kj17tctYONgCO';
update content_bodies set title = 'The Sacred Land of Resurrection: Kumano', description = 'Traveling through Kumano, embraced by its deep and rich nature, allows one to feel a mysterious power that seems to guide them towards rebirth. This journey in Wakayama is encapsulated in ''The Sacred Land of Resurrection: Kumano.'' For more details, you can watch the long version here: https://www.youtube.com/watch?v=Al8aE_zTeGI&t=936s and the short version here: https://www.youtube.com/watch?v=gS86Dozo2os&t=15s.' where id = 'FaYvRlAuYjUsGpFFvHEF-';
update content_bodies set title = '天空の聖地　高野山', description = '高野山は、1200年以上の歴史を持つ日本を代表する宗教都市です。この静寂に包まれた地は、喧騒から離れ、自分自身を見つめ直すのに最適な場所です。『天空の聖地　高野山』で和歌山の旅を体験してください。' where id = 'L_E4T61FM_LG_Ix3nvc25';
update content_bodies set title = 'Sacred Land in the Sky: Mount Koya', description = 'Mount Koya, a representative religious city in Japan, has a history spanning over 1,200 years. This tranquil place is ideal for those looking to escape the hustle and bustle of everyday life and reflect on themselves. Experience the journey through Wakayama in ''Sacred Land in the Sky: Mount Koya.''' where id = 'ySDOlrNAwvks_RCV2rmQm';
update content_bodies set title = '雨の夜の京都', description = 'これは私の初めてのHDR（ハイダイナミックレンジ）映画です。実験的で短い作品となっています。雨の中の夜の京都を4K HDR形式で表現しています。' where id = 'q1pYEIpRU0mryUv61dPMy';
update content_bodies set title = 'Kyoto in the Rain at Night', description = 'This is an experimental short film showcasing Kyoto at night during rain, presented in 4K HDR (High Dynamic Range) format. It marks the creator''s first attempt at producing an HDR movie.' where id = '7QkgIne_HnoR2HsbvC69U';
update content_bodies set title = '温泉の旅　和歌山 ～和み、わかやま～', description = '「和み、わかやま」のロングバージョンとショートバージョンはYouTubeで視聴可能です。和歌山の旅の醍醐味は、自然の中で身を浸し、休息を取ることにあります。太平洋に面した絶景の露天風呂や、山中の秘湯など、和歌山には魅力的な温泉が点在しています。『温泉の旅　和歌山』で、和歌山の美しさと静けさを体験してください。' where id = 'pXyAoWQ4C2c9YyvTQ9X_c';
update content_bodies set title = 'Onsen Journey in Wakayama - Relaxation in Wakayama', description = 'The ''Relaxation in Wakayama'' video offers a long version and a short version available on YouTube. The essence of traveling in Wakayama lies in pausing to immerse oneself in nature and find rest. The region features stunning open-air baths facing the Pacific Ocean and hidden hot springs nestled in the mountains. Experience the beauty and tranquility of Wakayama through the ''Onsen Journey in Wakayama.''' where id = 'ATyDajOmOY_mt0Qvg3tc6';
update content_bodies set title = '大自然と遊ぶ　和歌山', description = '「和み、わかやま」のロングバージョンはコチラ → https://www.youtube.com/watch?v=Al8aE_zTeGI&t=936s。ショートバージョンはコチラ → https://www.youtube.com/watch?v=gS86Dozo2os&t=15s。地球の長い歴史が刻まれた和歌山の自然に身を置くと、時が経つのを忘れる不思議な体験ができます。「大自然と遊ぶ　和歌山」で、和歌山の旅を楽しんでください。' where id = 'Xg-NuRCef-dpIBuMyGuCh';
update content_bodies set title = 'Playing with Nature in Wakayama', description = 'The long version of ''Nagomi, Wakayama'' can be found here: https://www.youtube.com/watch?v=Al8aE_zTeGI&t=936s. The short version is available here: https://www.youtube.com/watch?v=gS86Dozo2os&t=15s. The natural beauty of Wakayama, shaped by the Earth''s long history, allows visitors to lose track of time. Experience the journey through Wakayama''s great outdoors.' where id = '40x8fMIXnmoI0jhOBvPLB';
update content_bodies set title = '歴史の旅　和歌山', description = '「和み、わかやま」は、和歌山の人々が大切に受け継いできた伝統や、知られざる歴史の一面を紹介する動画です。この旅を通じて、和歌山の歴史や文化のさまざまな側面に出会うことができます。動画のロングバージョンとショートバージョンは、それぞれYouTubeのリンクから視聴可能です。和歌山の遺産の重要性を強調し、視聴者にその歴史的な旅を楽しむよう促しています。' where id = 'qILsBjTjJpWyU6YTBNfMo';
update content_bodies set title = 'Journey Through History: Wakayama', description = 'The video ''Nagomi, Wakayama'' showcases the rich traditions and lesser-known historical pages that have been cherished by the people of Wakayama. Throughout this journey, viewers can encounter various aspects of Wakayama''s history and culture. The long version of the video can be found at the provided YouTube link, as well as a shorter version. This exploration highlights the significance of Wakayama''s heritage and invites viewers to appreciate the historical journey it offers.' where id = 'GHHgv1oZ1jc6MtMe5O1A1';
update content_bodies set title = '『水の国、わかやま。』　～和み、わかやま～', description = '和歌山では、緑深い山々を清らかな川が流れ、その先には青い海が広がっています。『水の国、わかやま。』では、和歌山の旅を体験できます。長いバージョンは、こちらのリンクからご覧いただけます: https://www.youtube.com/watch?v=Al8aE_zTeGI&t=936s。短いバージョンは、こちらから: https://www.youtube.com/watch?v=gS86Dozo2os&t=15s。' where id = 'w6EXfk9oKOZAgd1MPYAHg';
update content_bodies set title = 'The Land of Water, Wakayama.', description = 'In Wakayama, clear rivers flow through lush green mountains, leading to a vast blue sea. The journey through Wakayama is encapsulated in ''The Land of Water, Wakayama.'' For a longer version, visit: https://www.youtube.com/watch?v=Al8aE_zTeGI&t=936s. For a short version, visit: https://www.youtube.com/watch?v=gS86Dozo2os&t=15s.' where id = 'oQZRpDts56WveNx0GWn_2';
update content_bodies set title = '和み、わかやま', description = '和歌山は、海・山・川に恵まれた広大な自然を持ち、古来より自然と精神的なつながりを育んできた「蘇りの地」として知られています。この地で得られる「和み」や「安らぎ」は、訪れる人々を惹きつける特別な魅力を持っています。和歌山の魅力を紹介する内容です。' where id = 'K7i40yRusHSrgYUsdUCrA';
update content_bodies set title = 'Wakayama, Japan - Short', description = 'Wakayama, known as the ''land of revival,'' is blessed with vast natural beauty, including the sea, mountains, and rivers. This region has nurtured a spiritual connection with nature since ancient times. The unique charm of Wakayama lies in the ''harmony'' and ''peace'' that travelers experience, making it a special destination that attracts many visitors.' where id = 'JpPBGh4XumvjWRGZd0R5l';
update content_bodies set title = '和み、わかやま', description = '和歌山は、海・山・川に恵まれた広大な自然を持ち、古来より自然と精神的なつながりを育んできた「蘇りの地」として知られています。この地で得られる「和み」や「安らぎ」は、訪れる人々を惹きつける特別な魅力を持っています。和歌山の自然の美しさと精神的な体験が、旅行者にとっての特別な場所を形成しています。' where id = 'QUIdWRDpcqm3afdnh3glA';
update content_bodies set title = 'Wakayama Japan_Long', description = 'Wakayama, known as the ''land of revival,'' is blessed with vast natural beauty, including the sea, mountains, and rivers. This region has nurtured a deep spiritual connection with nature since ancient times. The unique charm of Wakayama lies in the ''harmony'' and ''serenity'' that travelers experience, making it a special destination that attracts many visitors.' where id = 'vAYvP91UaBBZINJZNjSFJ';
update content_bodies set title = '日本遺産「葛城修験」PR動画', description = '和歌山から始まり、大阪、奈良へと続く祈りの道「葛城修験」。この地域は「葛城」と呼ばれ、多くの神々が住む山として古くから崇められてきました。修験道の開祖である役行者が最初に修行の地として選んだのもこの葛城です。現在でも修験者たちはこの地で巡礼の旅を続けています。' where id = 'ZO6hktpphXiXAn4CI3O-b';
update content_bodies set title = 'Katsuragi Shugendo PR Video', description = 'The Katsuragi Shugendo, a path of prayer that begins in Wakayama and continues through Osaka and Nara, is revered for its mountains known as ''Katsuragi,'' where many deities reside. This area has been worshipped by people since ancient times. The founder of Shugendo, En no Gyōja, chose Katsuragi as his first training ground. Even today, practitioners of Shugendo continue their pilgrimage in this sacred land.' where id = 'wJTwl7QDroNK8DC9SLzeD';
update content_bodies set title = '任天堂がクリスマスのために東京を占拠した（そしてプレゼントをもらった！）🎁', description = '東京の丸の内エリアで開催される「丸の内ブライトホリデー2024」では、スーパーマリオとその仲間たちが登場し、無料のイルミネーション展示やグッズ、食べ物が楽しめます。また、200円で参加できるスタンプラリーもあり、ヨッシーやピーチ、マリオなどのキャラクターからスタンプを集めると、完了時に賞品がもらえます。このイベントは、東京でのホリデーシーズンを楽しむための楽しい体験です。' where id = 'jeQSaxvKaL85SDCVSSkpk';
update content_bodies set title = 'Nintendo Took Over Tokyo for Christmas (and I got a present!) 🎁', description = 'The Marunouchi Bright Holiday 2024 event in Tokyo''s Marunouchi area features Super Mario and friends, offering a festive experience with free illumination displays, merchandise, and food. Visitors can participate in a stamp rally for ¥200, collecting stamps from various characters like Yoshi, Peach, and Mario, and receive a prize upon completion. This event is a fun and engaging way to celebrate the holidays in Tokyo.' where id = '3YyBQ5aQuaZQ_cFwgQSO8';
update content_bodies set title = '【高知旅】五感で楽しむ、自然のおもてなし。', description = '東高知で自然とグルメを満喫できる旅の紹介です。北川村と室戸市では、心と体を癒す自然のおもてなしが豊富に用意されています。モネの庭やキンメ丼、むろと廃校水族館、不動の滝、北川村温泉ゆずの宿など、訪れる価値のあるスポットが盛りだくさんです。' where id = 'ABvYmoKj76C-lrbl4VsFJ';
update content_bodies set title = 'Kochi Trip: Enjoying Nature''s Hospitality with All Five Senses', description = 'Experience the beauty of nature and gourmet delights in East Kochi! In Kitagawa Village and Muroto City, you can find plenty of natural hospitality that heals both the mind and body. Highlights include Monet''s Garden, Kinmedai Donburi, Muroto''s Abandoned School Aquarium, Fudo Falls, and Kitagawa Village Onsen Yuzu no Yado.' where id = 'Xvnt21arwcTqzDWAoQ7WX';
update content_bodies set title = 'わかやま遊び', description = 'この動画は、わかやま遊びについて紹介しています。わかやま遊びは、地域の文化や伝統を体験することができる活動であり、観光客や地元の人々にとって魅力的な内容となっています。動画では、具体的な遊びの内容やその楽しさ、参加方法などが説明されており、視聴者にわかやま遊びの魅力を伝えることを目的としています。' where id = 'tQ0v2xgeg1l4M7-Lz-NVd';
update content_bodies set title = 'Wakayama Play', description = 'This video introduces Wakayama play.' where id = 'sa0xZw3g7QTIeHl9KyKHJ';
update content_bodies set title = 'ニタマ卿授与式', description = 'この動画はニタマ卿授与式について紹介しています。' where id = 'Y_bOy1waAD7KQ71dQCYsh';
update content_bodies set title = 'Nitamakyō Award Ceremony', description = 'This video introduces the Nitamakyō Award Ceremony.' where id = 'mx9t--wQJjjdKk_d63TZ1';
update content_bodies set title = '仁淀川四季・冬 - NIYODO BLUE! 冬 -', description = '映画『竜とそばかすの姫』の舞台のモデルとなり話題となった″奇跡の清流″仁淀川の冬の美しさを集めた内容です。撮影は、仁淀ブルーの名付け親でもある高知在住のネイチャーカメラマン高橋宣之さんが担当しています。冬の仁淀ブルーの魅力を感じることができる作品です。' where id = 'ccWH8UEKNmRGZm7_aquzw';
update content_bodies set title = 'Niyodo River Seasons - NIYODO BLUE! Winter -', description = 'The Niyodo River, known as the ''miraculous clear stream,'' gained attention as the model for the setting of the movie ''Belle.'' This summary showcases the beauty of Niyodo Blue in winter. The photographs were taken by Yoshiyuki Takahashi, a nature photographer residing in Kochi, who is also the one who named ''Niyodo Blue.''' where id = 'zjqiwuKwV1u8vPWVCofQx';
update content_bodies set title = 'サイクリング王国わかやま　Route.2　紀の川サイクリングロード～高野山', description = 'サイクリストに人気の紀の川サイクリングロードから、ヒルクライマーが憧れる世界遺産の高野山までを、人気インスタグラマーのベキさんが走ります。このルートでは、悠久の歴史を感じながら、美しい風景を楽しむことができます。' where id = 'abzZQfvRdSuI5Ech1HXwg';
update content_bodies set title = 'Cycling Kingdom Wakayama: Route 2 - Kinokawa Cycling Road to Mount Koya', description = 'This route features the popular Kinokawa Cycling Road, favored by cyclists, leading to the world heritage site of Mount Koya, a dream destination for hill climbers. Influential Instagrammer Beki will be riding this scenic route, inviting you to experience the profound history of the area.' where id = '5r2LK1FGlZ_5VuJzwAnuQ';
update content_bodies set title = '紀州浪漫 2021冬　1300年の歴史を誇る「白浜温泉」', description = '白浜温泉は1300年の歴史を持つ名湯であり、温泉ソムリエによってその魅力が紹介されます。散策の途中で楽しめる手軽な足湯も各所に設置されているため、訪れた際にはぜひ立ち寄ってみてください。' where id = 'nkq5-mIaBKyn_uYpxOoG6';
update content_bodies set title = 'Kishu Romance Winter 2021: The 1300-Year History of Shirahama Onsen', description = 'Shirahama Onsen boasts a long history and is introduced by an onsen sommelier. There are many foot baths available for easy enjoyment, so feel free to take a break and enjoy them during your stroll.' where id = 'AFJPv4FS2jSBsLGxyVIdl';
update content_bodies set title = 'サイクリング王国わかやま　Route.3　箕島漁港～千葉山～あらぎ島', description = '箕島漁港の黄色い漁船が並ぶ光景はこの港町ならではのものです。この町から有田川を遡り、日本のラルプデュエズとして知られる「千葉山」に立ち寄り、ヒルクライムを楽しみます。最終目的地は、日本の棚田百選に選ばれた美しいスポット「あらぎ島」で、ヒルクライマーの筧五郎さんが案内します。' where id = 'Fkf0zgGq4XcBfREOiaT1Q';
update content_bodies set title = 'Cycling Kingdom Wakayama: Route 3 - Minoshima Fishing Port to Chibayama to Aragi Island', description = 'The scene of yellow fishing boats lined up is unique to Minoshima Fishing Port. From this port town, cyclists will ride upstream along the Arida River and stop at ''Chibayama,'' known as Japan''s Alpe d''Huez, for a hill climb. The destination is ''Aragi Island,'' a picturesque spot selected as one of Japan''s top 100 terraced rice fields, led by the dedicated hill climber Goro Kakei.' where id = 'mgYddAW5zUf1atyM901Zh';
update content_bodies set title = 'サイクリング王国わかやま　Route.1　太平洋岸自転車道', description = '令和3年5月にナショナルサイクルルートに指定された「太平洋岸自転車道」は、三重県と和歌山県の県境に位置する新宮市から、和歌山市加太までのサイクリングロードです。このルートは見どころが豊富で、人気インスタグラマーのベキさんがその魅力を体験します。' where id = '4wOdaZIcrw-i3o_1c6D34';
update content_bodies set title = 'Cycling Kingdom Wakayama: Route 1 - Pacific Coast Cycling Road', description = 'Designated as a National Cycle Route in May 2021, the Pacific Coast Cycling Road stretches from Shingu City at the border of Mie and Wakayama Prefectures to Kada in Wakayama City. This scenic cycling route is filled with attractions, and popular Instagrammer Beki rides along it.' where id = 'S2gMF-zAw-W6X5dkLtNnV';
update content_bodies set title = '【360°動画】白樺高原国際スキー場を滑っている気分になっちゃおう(@_@)', description = '2019-20シーズンは全国的に雪不足ですが、白樺高原ではスキーを楽しむことができます。この360°映像は、スキー場の様子を知りたい方や、忙しくて滑りに行けない方、週末に滑りに行く前に予習したい方に最適です。画面を自由に動かしたり、VRゴーグルで視聴することで、より臨場感を味わえます。ぜひ白樺高原に滑りに来てください！' where id = 'gh954CfigVZHA5qLnz9Jj';
update content_bodies set title = 'Experience the Thrill of Skiing at Shirakaba Kogen International Ski Resort with 360° Video', description = 'The 2019-20 ski season has seen a nationwide shortage of snow, but Shirakaba Kogen offers great skiing opportunities! This 360° video is perfect for those who want to know more about the ski resort, are too busy to go skiing, or want to prepare for their weekend trip. You can move the screen around or watch it with VR goggles for an immersive experience. And of course, we invite you to come and ski at Shirakaba Kogen!' where id = '6R0k7wZH-M6FAzdwbaaG1';
update content_bodies set title = '信州たてしな白樺高原', description = '首都圏から3時間の距離にある信州の立科町には、女神湖と白樺湖という2つの湖を有する高原リゾートがあります。真夏でも平均気温は22℃と快適で、爽やかな風が吹き抜け、女神を感じることができます。この夏、白樺高原にぜひお越しください。かかとのある靴でも手軽に行ける大自然が広がっており、自然を愛する方々にとって理想的な目的地です。' where id = 'v3hXGn42aSUvwUaC4NDpG';
update content_bodies set title = 'Shinshu Tateshina Shirakaba Highlands', description = 'Located just three hours from the Tokyo metropolitan area, the Tateshina area in Shinshu features a highland resort with two beautiful lakes: Lake Megami and Lake Shirakaba. Even in the height of summer, the average temperature is a pleasant 22°C, offering a refreshing breeze that makes you feel connected to the divine. This summer, we invite you to visit Shirakaba Highlands and enjoy the natural beauty. Accessible even with heeled shoes, it’s a perfect destination for nature lovers.' where id = 'GlV2k74aCvtQ5sXCiZUzV';
update content_bodies set title = '[VR体験] コダレンジャーとまわる小平ふるさと村 [360度動画]', description = 'この動画では、東京都小平市のご当地ヒーローであるコダレンジャーが小平ふるさと村を案内します。江戸や明治時代にタイムスリップした気持ちで、コダレンジャーと一緒に村を見学することができます。小平ふるさと村は東京都小平市天神町3丁目9番1号に位置し、開園時間は午前10時から午後4時までで、月曜日や第3火曜日、休日の翌日が休園日です。入場は無料ですが、障がい者用以外の駐車場はないため、徒歩またはバスでの来園を推奨しています。' where id = '6joT1VMqF7rcvRXwZijoF';
update content_bodies set title = '[VR Experience] Explore Kodaira Furusato Village with Kodaranger [360-degree Video]', description = 'This video features Kodaranger, the local hero of Kodaira City, Tokyo, guiding viewers through the Kodaira Furusato Village. Experience a journey back in time to the Edo and Meiji periods while exploring the village alongside Kodaranger. The village is located at 3-9-1 Tenjin-cho, Kodaira City, Tokyo, and is open from 10 AM to 4 PM, closed on Mondays, the third Tuesday of the month, and the day after holidays. Admission is free, but visitors are encouraged to arrive on foot or by bus, as there is no parking available except for disabled access.' where id = 'iGoJvTlmgewbw7h14qOGE';
update content_bodies set title = '和歌山県観光プロモーション動画', description = '南北に伸びる和歌山県は、海・山・川に恵まれ、世界遺産を含む歴史的観光スポットやレジャー、温泉、グルメなど、旅の魅力が満載の県です。季節ごとに多様な体験ができるのも特徴で、春と秋は熊野古道のウォーキングやサイクリングがオススメです。夏にはウォーターアクティビティや「那智の扇祭り」といった歴史ある祭りが楽しめます。冬は温泉でリラックスし、この時期ならではのグルメを堪能することができます。' where id = 'ISR7nMG0PoZGSrjH-CkMy';
update content_bodies set title = 'Wakayama Prefecture Tourism Promotion Video', description = 'Wakayama Prefecture, stretching from north to south, is blessed with beautiful seas, mountains, and rivers. It is rich in historical tourist spots, including World Heritage sites, as well as leisure activities, hot springs, and gourmet experiences. The region offers various seasonal experiences, with spring and autumn being ideal for walking the Kumano Kodo or cycling. In summer, visitors can enjoy water activities and historical festivals like the Nachi Fire Festival. Winter is perfect for relaxing in hot springs and savoring seasonal delicacies unique to this time of year.' where id = 'w7uHHcb0HWROyA10FGVOe';
update content_bodies set title = 'パックンマックンのなるほど！日本旅サーチ／南紀白浜', description = 'お笑いコンビのパックンマックンが、サイクリング王国わかやまで「南紀白浜の数字の謎を自転車で探れ」というミッションを掲げ、南紀白浜を旅サーチしました。この旅番組では、その土地ならではのお勧めスポットやグルメを紹介します。パックンマックンのミッションは、街やエリアを旅サーチしてレポートすることで、地図をもとにその街のスポットを巡り、調査や体験を通じて街の魅力を探ります。' where id = 'pLv6IlOLEEKJdXxB1o0Hs';
update content_bodies set title = 'Packun Makkun''s Interesting Japan Travel Search / Nanki Shirahama', description = 'The comedy duo Packun Makkun undertakes a mission to explore the mysteries of numbers in Nanki Shirahama by cycling through Wakayama, known as the cycling kingdom. This travel program introduces unique spots and gourmet experiences specific to the area. Packun Makkun''s mission is to report on various towns and regions, using maps to navigate and investigate local attractions. Through their experiences and research, they aim to uncover the charm of each location.' where id = '5uC75C3igLYbMLMC6E9m6';
update content_bodies set title = 'サイクリング王国わかやま WAKAYAMA800を走る　～色川から絶景ライド世界遺産の那智の滝へ～', description = '色川から妙法山阿弥陀寺までのサイクリングでは、熊野灘の絶景が広がります。この地点までの努力のごほうびを楽しんだ後、世界遺産である那智の滝に立ち寄り、熊野の自転車旅を締めくくります。' where id = 'jGkqxH3sUTYvkJxzviJHf';
update content_bodies set title = 'Cycling Kingdom Wakayama: Riding WAKAYAMA800 from Irokawa to the Scenic World Heritage Site Nachi Falls', description = 'The ride from Irokawa to Myohosan Amida Temple offers breathtaking views of Kumano-nada. After enjoying the reward of reaching this point, the journey concludes with a visit to the World Heritage Site, Nachi Falls, marking the end of a cycling adventure in Kumano.' where id = 'JOuBeADrt6BStx3LTnpAo';
update content_bodies set title = 'サイクリング王国わかやま WAKAYAMA800 【女子旅編】', description = '和歌山県は「サイクリング王国わかやま」としてサイクリストを歓迎しています。和歌山県でのサイクリングをぜひ楽しんでください。さまざまなタイプのサイクリストが楽しめる無限のサイクリングコースがあります。' where id = '700DB9k1mP7GLtTcAyCcS';
update content_bodies set title = 'Cycling Kingdom Wakayama WAKAYAMA800 - Women''s Travel Edition', description = 'Wakayama Prefecture welcomes cyclists as the ''Cycling Kingdom Wakayama.'' Enjoy cycling in Wakayama, where there are endless cycling courses suitable for various types of cyclists.' where id = 'iVFWiJ2kBFWlUEOzrPPXP';
update content_bodies set title = '[360度動画]小平市平櫛田中彫刻美術館 記念館探検[VR体験]', description = '小平市平櫛田中彫刻美術館の記念館をVR体験できる360度動画です。スマートフォンのYouTubeアプリからの視聴をお勧めします。この美術館は東京都小平市学園西町1-7-5に位置し、1984年に日本近代彫刻の巨匠・平櫛田中の作品を保存・展示するために設立されました。平櫛田中の功績を顕彰し、市民文化の向上を目指しています。1994年には新しい展示館が建設され、2006年には遺族からの寄贈を受けて館名が現在のものに変更されました。美術館では平櫛田中の作品の常設展示や、関連作家の特別展を2年ごとに開催しています。また、春と秋にお茶会や夏休みに親子向けのワークショップも行い、最近ではボランティアを組織して市民との協働を進めています。' where id = 'ZXq5eS1wG_XPq2hmE3oyR';
update content_bodies set title = '[360-degree Video] Kodaira City Hirakushi Denchu Sculpture Museum Memorial Exploration [VR Experience]', description = 'This 360-degree video offers a VR experience of the memorial at the Kodaira City Hirakushi Denchu Sculpture Museum. It is recommended to watch it using the YouTube app on your smartphone. The museum, located at 1-7-5 Gakuen Nishimachi, Kodaira City, Tokyo, was established in 1984 to preserve and exhibit the works of Hirakushi Denchu, a master of modern Japanese sculpture. The museum aims to honor his contributions and enhance local culture. In 1994, a new exhibition hall was built, and in 2006, the museum was renamed to its current title after receiving donations from Denchu''s family. The museum hosts regular exhibitions of Denchu''s works and special exhibitions every two years featuring related artists. Additionally, it organizes tea ceremonies and workshops for families during summer vacations, and has recently formed a volunteer group to further engage the community.' where id = 'n6Afxzy6RgzEUW1jiOBl5';
update content_bodies set title = '【高野山】Photographic Video Magazine -KOYASAN- 2015', description = '高野山開創1200年を迎える年に制作されたこの映像マガジンは、高野山の自然や四季、祈り、生活、食などを美しい映像で表現しています。高野山に住む僧侶たちの語りを通じて、この神聖な場所の精神的かつ文化的な本質に深く迫る内容となっています。' where id = 'YJgoKQ2Udv_lT9CMDsMzq';
update content_bodies set title = 'Photographic Video Magazine -KOYASAN- 2015', description = 'Produced and released in the year marking the 1200th anniversary of the founding of Koyasan, this video magazine beautifully captures the nature, seasons, prayers, daily life, and food of Koyasan. It features narratives from the monks living in Koyasan, providing a deep insight into the spiritual and cultural essence of this sacred place.' where id = 'gw_90rHhjOQTsK4LCmKFD';
update content_bodies set title = '世界的著名サイクリスト「アルベルト・コンタドール」氏出演！『サイクリング王国わかやま』プロモーション動画', description = '世界的に有名なサイクリストであるアルベルト・コンタドール氏が、2019年11月20日から11月23日の4日間にわたり、和歌山県内の観光スポットやサイクリングコースをPRしました。彼の参加により、和歌山の魅力が広く伝えられることが期待されています。' where id = 'cNUhyBN0K12uqOxEy7qZV';
update content_bodies set title = 'World-renowned Cyclist Alberto Contador Appears in ''Cycling Kingdom Wakayama'' Promotional Video', description = 'World-renowned cyclist Alberto Contador participated in a promotional event from November 20 to November 23, 2019, where he promoted various tourist spots and cycling routes in Wakayama Prefecture.' where id = 'LVK0t4UrfzZMg6eU--FY1';
update content_bodies set title = '夜の祇園とポントチョウ、京都 | 4K', description = '京都は夜になるとさらに美しくなります。' where id = 'gwnXzCKLDG8P4xQDMNJGK';
update content_bodies set title = 'Gion and Ponto-Cho, Kyoto at Night | 4K', description = 'Kyoto is more beautiful at night.' where id = 'ReRgwLv1oRKXN_DZbXzD6';
update content_bodies set title = 'なまら寒い、冬が来た。', description = '上富良野町に冬が到来しました。東京では紅葉が見ごろとのことですが、かみふらのではすでに雪が積もっています。まだ道路は見えていますが、これからは一面の銀世界になるでしょう。今年も寒いかみふらのの冬をぜひ楽しんでください。' where id = 'rp-r_vARrYePeOsyoTIh7';
update content_bodies set title = 'It''s Really Cold, Winter Has Arrived', description = 'Winter has arrived in Kamifurano. While my friend mentioned that the autumn leaves are at their peak in Tokyo, snow has already accumulated in Kamifurano. The roads are still visible for now, but soon it will be a world covered in white! Enjoy the cold winter in Kamifurano this year.' where id = 'QrrIcMq7cl086h-P2JNNg';
update content_bodies set title = '【絶景茨城】牛久大仏', description = '牛久大仏は茨城県牛久市に位置し、浄土真宗東本願寺派が事業主体となっています。この宗派の開祖である親鸞聖人は、1207年に流罪となり、後に常陸国に入り布教を行いました。牛久大仏の建設は1986年に始まり、1992年に完成しました。全高120m（像高100m、台座20m）で、奈良の大仏や自由の女神像よりもはるかに大きいです。この大仏は、浄土真宗の本尊である阿弥陀如来像を拡大した形状をしています。なお、無許可のドローン使用は禁止されています。' where id = 'znUHohNfGGjxb2Tn9Armk';
update content_bodies set title = 'The Great Buddha of Ushiku: A Scenic View in Ibaraki', description = 'The Great Buddha of Ushiku, located in Ushiku City, Ibaraki Prefecture, is a project initiated by the Higashi Honganji sect of Jodo Shinshu Buddhism. The founder of this sect, Shinran Shonin, was exiled in 1207 but later returned to the Kanto region to spread his teachings. The area is rich in historical sites related to Shinran. The construction of the Great Buddha began in 1986 and was completed in December 1992. Standing at a total height of 120 meters (100 meters for the statue and 20 meters for the pedestal), it is nearly three times the height of the Great Buddha of Nara and significantly taller than the Statue of Liberty in New York. The statue is modeled after the Amida Buddha, the main deity of the sect. Note that unauthorized drone usage is prohibited.' where id = 'WqmyX6eiPodnPuFv06oaN';
update content_bodies set title = 'かみふらの泊得キャンペーン 実施中', description = 'この動画では、かみふらの泊得キャンペーンについて紹介しています。キャンペーンの内容や特典について詳しく説明されており、宿泊を通じて得られるメリットが強調されています。観光客や地元の人々にとって、魅力的な宿泊プランが用意されていることが伝わります。' where id = 'QwvLhbJvFFeEtd0LcA6Qh';
update content_bodies set title = 'Kamikurano Stay Benefit Campaign Now Underway', description = 'This video introduces the Kamikurano Stay Benefit Campaign.' where id = 'nTuPMu7e0JyDL8dLVJV8X';
update content_bodies set title = '上富良野町の色鮮やかな秋を舞台に綴られる紅葉がつなぐストーリー', description = '上富良野町の色鮮やかな秋を舞台にした物語が展開されます。ある日、手紙もカードもない一通の封筒が届き、その中には鮮やかな葉が一枚だけ挟まれていました。その葉を見た彼女は、カメラを持って外に出かけます。目の前には美しい景色が広がり、落ち葉を撮影しながら自然を楽しみます。標高が上がるにつれて冷たい風を感じ、温かい湯に癒されます。上富良野の自然の恵みを堪能し、趣味を満喫する彼女は、ふと足元にもう一枚の色鮮やかな葉を見つけます。' where id = '1mQ8EE_PO2JW9865xEhzy';
update content_bodies set title = 'A Story Connected by Autumn Leaves in Kamifurano Town', description = 'In Kamifurano Town, a vibrant autumn setting unfolds a story connected by colorful leaves. One day, a mysterious envelope arrives containing only a single vivid leaf. Inspired, a young woman, who has recently taken up photography, sets out with her camera. She is greeted by breathtaking scenery, capturing fallen leaves and enjoying the landscape. As the altitude increases, she feels the cool breeze and seeks warmth in a hot spring. Immersed in the natural beauty of Kamifurano, she revels in her hobby. Suddenly, she notices another colorful leaf at her feet, reminding her of the connection between nature and her passion.' where id = 'MA5pW-fgxDmkKbkCHraSu';
update content_bodies set title = 'ラベンダーフェスタかみふらの 2022 オープニング', description = '上富良野の夏を彩る新たなイベント「ラベンダーフェスタかみふらの2022」が開催されます。今年で41年目を迎えるこのイベントは、上富良野町の花であるラベンダーを、町民や日本全国、さらには海外の人々に楽しんでもらうことを目的としています。期間限定で夜間もラベンダーを楽しむことができ、特別に上富良野産のホップや大麦を使用したビールのブースも1日限定で設けられます。幻想的なライティングで彩られたラベンダーの大パノラマを体験できる機会です。初日の点灯式は、日の出ラベンダー園「愛の鐘」の前からライブ配信されます。' where id = '0l270JbYeV6_gk7SlVmVw';
update content_bodies set title = 'Lavender Festa Kamifurano 2022 Opening', description = 'The ''Lavender Festa Kamifurano 2022'' is a new event that brightens up summer in Kamifurano. This year marks the 41st anniversary since lavender became the town''s flower, cherished by locals, people from across Japan, and even overseas. Visitors can enjoy the beauty of lavender during a limited time, including nighttime displays. A special booth featuring beer made from locally sourced hops and barley will be open for one day only. Experience the stunning panorama of lavender illuminated by enchanting lighting. The opening day will feature a live broadcast of the lighting ceremony in front of the ''Bell of Love'' at the Sunrise Lavender Garden.' where id = '3JQtEPcN9j4EmhuPdmXIg';
update content_bodies set title = 'かみふらの桜づつみ夜桜ウォーク', description = 'かみふらの桜づつみ夜桜ウォークは、令和4年5月1日から5月3日、6日、7日の午後6時45分から8時30分まで開催されます。場所はさくら堤遊歩道で、パーラーラッキーズ上富良野店付近から国道237号線しんえい橋の間、富良野川沿いの桜がライトアップされます。コロナ禍の中、身近な場所で町民が癒される隠れた桜スポットとして、健康づくりを推進する上富良野町が今年は桜の夜に魔法をかけました。天候が悪い日もありましたが、多くの町民が楽しむことができました。' where id = 'YsqbMgZNYniGZ619lxSb5';
update content_bodies set title = 'Kamifurano Cherry Blossom Night Walk', description = 'The Kamifurano Cherry Blossom Night Walk will take place from May 1 to May 3, and on May 6 and 7, 2022, from 6:45 PM to 8:30 PM. The event is held along the Sakura Tsutsumi Promenade, approximately 500 meters long, between the Parlor Luckies Kamifurano store and the Shin''ei Bridge on National Route 237, where cherry blossoms along the Furano River will be illuminated. Amidst the COVID-19 pandemic, this hidden cherry blossom spot offers a way for local residents to find solace close to home. The town of Kamifurano, known for promoting health, has added a magical touch to the cherry blossoms this year, creating a beautiful walking path for residents. Despite some unfavorable weather, many locals enjoyed the event.' where id = 'CIF8BX8YGwIfXtd9RPJAT';
update content_bodies set title = '氷瀑「法華の滝」で埋まってしまった！', description = '上富良野に位置する法華の滝は、十勝岳の近くにあり、特に冬の季節にはその美しさが際立つ氷瀑として知られています。しかし、最近の出来事により、この美しい場所での安全性やアクセスに関する懸念が高まっています。法華の滝は観光名所としても人気があり、多くの人々が訪れる場所です。' where id = 'W6RT-CaYD_9XRtgmMM8i_';
update content_bodies set title = 'Buried in the Icefall ''Hokke no Taki''!', description = 'This incident occurred in Kamifurano, near Mount Tokachidake, where the icefall known as ''Hokke no Taki'' has become a significant point of interest. The area is known for its stunning natural beauty, particularly during the winter months when the icefall is at its most impressive. However, the recent events have raised concerns about safety and accessibility in this picturesque location.' where id = '0RpP3Rh7Y3jvpi2p5BwS7';
update content_bodies set title = '【絶景茨城】百段階段ひなまつり-茨城県久慈郡大子町', description = '茨城県大子町の十二所神社の参道に位置する百段階段で毎年開催される「百段階段でひなまつり」では、全国から集められたひな人形が展示され、それぞれに独自の歴史と個性が感じられます。レトロな雰囲気の商店街では、各店舗や民家の軒先に段飾りや雛飾りが並び、訪れる人々を楽しませます。また、同日に駅前通りでは花嫁行列が行われ、新郎新婦が街を練り歩く様子も見られます。' where id = 'B_jpTp0IAy5khK8ShAqZH';
update content_bodies set title = 'Spectacular Ibaraki: Hyakudankaidan Hina Matsuri - Daigo Town, Ibaraki Prefecture', description = 'The ''Hyakudankaidan Hina Matsuri'' is held annually at the hundred-step staircase leading to the Juunishoshrine in Daigo Town, Ibaraki Prefecture. Hina dolls provided from across the country are displayed, each with its own unique history and character. The retro streetscape of the shopping district features tiered displays and hina decorations at various shops and homes. Additionally, on the same day, a bridal procession takes place on the street in front of the station, where newlyweds walk through the town.' where id = 'AwsWvvE86X8aXhu6xFFW_';
update content_bodies set title = '南極生活体験　観測隊の野外テント生活を体験', description = '地球最後の秘境と称される南極には、言葉では表現しきれない絶景と生き物たちの営みがあります。「一度は行ってみたい」と憧れる一方で、実際に行く方法が分からないことも多いです。2022年1月、日本南極地域観測隊によるテントでの野外調査訓練のもと、実際の装備を使用した観測隊の野外テント生活を体験するイベントが、十勝岳温泉凌雲閣近くで行われました。' where id = 'St9iuj7xTxbEDvAM32zh8';
update content_bodies set title = 'Experience Life in Antarctica: Field Tent Living with the Observation Team', description = 'Antarctica, often referred to as the last unexplored frontier of Earth, offers breathtaking landscapes and the natural behaviors of its wildlife. While many dream of visiting, questions about how to actually go can be daunting. In January 2022, an event was held near Tokachidake Onsen Ryouunkaku, where participants could experience the outdoor tent life of the Japanese Antarctic Research Expedition. This event was supervised by team members who had undergone training for field surveys using actual equipment.' where id = 'Zi9E-UawSU40c6AQDgM5B';
update content_bodies set title = '上富良野町の紅葉', description = 'この動画では、上富良野町の美しい紅葉を紹介しています。上富良野町は、北海道に位置し、四季折々の自然の美しさが楽しめる場所です。特に秋になると、色とりどりの葉が山々を彩り、多くの観光客が訪れます。紅葉の見頃やその魅力について詳しく解説されており、訪れる価値のあるスポットとしての上富良野町の魅力が伝わってきます。' where id = '6VsUR5qTLGCrEJItnvPAe';
update content_bodies set title = 'Autumn Foliage in Kamifurano Town', description = 'This video introduces the autumn foliage in Kamifurano Town.' where id = '4XohmtUZWhKcaI5y_EtpF';
update content_bodies set title = 'らべとん花火が出来るまで　ーラベンダーフェスタ2021ー　北海道上富良野町', description = '夏の風物詩である花火。今年の夏はコロナ禍の影響で多くの花火大会が中止となりましたが、上富良野町では地域の方々に元気を届けるため、例年よりも大きな花火を打ち上げ、ラベンダーのライトアップとコラボレーションしました。ラベンダーフェスタ2021で使用される花火は煙火店の海洋化研によって制作され、その制作現場を撮影しました。この動画では、実際の花火大会ではわかりにくかった「らべとん」の顔を模した花火がどのように作られるか、その全工程をわかりやすく紹介しています。' where id = 'DEP6wgdoiXWOhouEWXDKk';
update content_bodies set title = 'The Making of Rabeton Fireworks - Lavender Festa 2021 - Kamifurano, Hokkaido', description = 'Fireworks are a summer tradition. This summer, many fireworks festivals were canceled due to the COVID-19 pandemic. However, in Kamifurano, the local community aimed to uplift spirits by launching larger fireworks in collaboration with lavender light displays. The fireworks used for the Lavender Festa 2021 were created by the pyrotechnics company Kaiyokaken, who allowed filming of the firework production process. This video clearly showcases the entire process of making the ''Rabeton Fireworks,'' which resemble the face of Rabeton, a character that was not easily recognizable during the actual fireworks festival.' where id = 'BYROXTAZW_zXdmMHXwYHt';
update content_bodies set title = 'ラベンダーフェスタ2021上富良野スペシャルオムニバス版', description = 'この動画は、ラベンダーフェスタ2021上富良野スペシャルオムニバス版を紹介しています。イベントのハイライトや特徴が紹介されており、ラベンダーの美しさを楽しむことができます。' where id = 'VIMxK7-UoIkB7TEeLwJ00';
update content_bodies set title = 'Lavender Festa 2021 Kamifurano Special Omnibus Edition', description = 'This video presents the Lavender Festa 2021 Kamifurano Special Omnibus Edition, showcasing the highlights and features of the event.' where id = 'Lu0ymCbaEbxR0_tLNY7Uk';
update content_bodies set title = '十勝岳縦走　上ホロ避難小屋から朝日＆雲海', description = '上富良野町の十勝岳登山口から登り、上富良野岳、上ホロカメットク山、そしてカミホロ避難小屋で1泊しました。翌日は十勝岳、白銀荘に降りる登山に行きました。9月上旬の朝は一桁の気温で、他に宿泊している方は約10人でした。避難小屋に着くとすぐに雨が降り始め、雨漏り対策をして寝ました。翌朝は知床の百名山、羅臼岳も見える絶景が広がり、とても記憶に残る登山となりました。' where id = '5t3xqVjMtQt2m-dhmulv6';
update content_bodies set title = 'Trekking Tokachidake: Asahi and Sea of Clouds from Kamihoro Emergency Shelter', description = 'The trek began at the Tokachidake trailhead in Kamifurano, climbing up to Kamifurano-dake, Kamihorokametoku, and staying overnight at the Kamihoro emergency shelter. The next day, we descended to Tokachidake and Shiraginsou. In early September, the morning temperature was in single digits. There were about ten other guests at the shelter. As soon as we arrived, it started to rain, and we had to take measures against leaks before sleeping. The next morning offered breathtaking views, including Rausudake, one of the 100 famous mountains of Shiretoko, making it a memorable trekking experience.' where id = 'Tv7o-_6m56kN1kF9v0TIp';
update content_bodies set title = '【絶景茨城】山桜｜VISIT IBARAKI, JAPAN', description = '茨城県桜川市の里山には約55万本の山桜が自生しており、淡紅色の桜花と新緑の木々が重なり合い、まるでパッチワークのような美しい風景が広がっています。磯部桜川公園周辺では約550本の桜を見ることができ、櫻川磯部稲村神社や公園を含むこの地域は国の名勝に指定されています。また、神社と公園にある桜は国の天然記念物にも指定されています。' where id = '0nsIhP6x7gUMYJeNI7awJ';
update content_bodies set title = 'Spectacular Ibaraki: Mountain Cherry Blossoms | VISIT IBARAKI, JAPAN', description = 'In the satoyama of Sakuragawa City, Ibaraki Prefecture, approximately 550,000 mountain cherry trees grow naturally, creating a patchwork landscape of pale pink blossoms and fresh green buds. Around Isobe Sakuragawa Park, about 550 cherry trees can be seen. The area, including the Sakuragawa Isobe Inamura Shrine and the park, is designated as a national scenic spot, and the cherry trees in the shrine and park are recognized as national natural monuments.' where id = '29vgUf_lz50cYkVNnmfFV';
update content_bodies set title = 'ラベンダーフェスタ上富良野2021', description = 'この動画は、ラベンダーフェスタ上富良野2021を紹介しています。イベントの内容や見どころを伝えています。' where id = 'AuPWaDclV5GmR-rLVoWmd';
update content_bodies set title = 'Lavender Festa Kamifurano 2021', description = 'This video provides an introduction to the Lavender Festa Kamifurano 2021, showcasing the event and its highlights.' where id = 'aCIF5D7i9dYOr_mcnJIAs';
update content_bodies set title = 'KAMIFURANO LIGHTING-UP ＆ FIREWORKS ONLINE 2020', description = 'この動画はKAMIFURANO LIGHTING-UP ＆ FIREWORKS ONLINE 2020について紹介しています。' where id = 'AqRa3snQnxVampNWxhgEU';
update content_bodies set title = 'KAMIFURANO LIGHTING-UP & FIREWORKS ONLINE 2020', description = 'This video introduces the KAMIFURANO LIGHTING-UP & FIREWORKS ONLINE 2020 event.' where id = 'QWovrqWdM-qxkmJ_FSj9U';
update content_bodies set title = '【絶景茨城】ハス田｜VISIT IBARAKI,JAPAN', description = 'れんこん生産量日本一の茨城県では、7月から8月にかけて霞ヶ浦周辺で美しい蓮の花が見られます。広大な湖のそばに咲く蓮の花は、湖面に輝く太陽の光と共に人々を魅了します。秋になると葉は茶色になり枯れ始めます。れんこんの収穫では「水掘り」という方法を用い、肌を傷つけないように丁寧に掘り上げ、泥を洗い落とします。ぷっくりとした団子状で柔らかな肉質、ほんのりとした甘みが特徴です。霞ヶ浦の豊富な水資源と肥沃な土壌が、日本中で愛される美味しいれんこんを育んでいます。' where id = 'S1AnfJIBnIJmMDp7JQyQa';
update content_bodies set title = 'Scenic Ibaraki: Lotus Fields | VISIT IBARAKI, JAPAN', description = 'Ibaraki Prefecture, known for its highest production of lotus roots in Japan, showcases beautiful lotus flowers around Lake Kasumigaura from July to August. The stunning blooms near the vast lake captivate visitors, especially when illuminated by the sun''s rays on the water''s surface. As autumn approaches, the leaves turn brown and begin to wither. The harvesting of lotus roots employs a method called ''water digging,'' which carefully lifts the roots without damaging their skin, followed by a gentle washing to remove mud. The roots are characterized by their plump, round shape, tender texture, and a hint of sweetness. The rich water resources and fertile soil of Lake Kasumigaura contribute to the cultivation of delicious lotus roots loved throughout Japan.' where id = 'gHBkKdhdkXpqHaJiAQ0kX';
update content_bodies set title = '深山峠を発信～上富の魅力を伝えよう～【上富良野高校２学年 地域探究データ 2班】', description = 'この動画は上富良野高校の生徒によって作成されました。生徒たちは、上富良野の魅力を伝えるには文章よりも動画の方が効果的だと考えています。また、スマートフォンがあれば手軽に視聴できるため、より多くの人に見てもらえると期待しています。' where id = '1qTIGthPSw4Iu9qEbzAqU';
update content_bodies set title = 'Promoting Miyama Pass - Let''s Share the Charm of Kamifurano - [Kamifurano High School 2nd Year Regional Research Data Group 2]', description = 'This video was created by students from Kamifurano High School. The students commented that conveying the charm of Kamifurano is more effective through video than text. They believe that videos are easily accessible on smartphones, allowing a wider audience to view and appreciate the content.' where id = 'Ttr0S3r4wsBqkWSdKuxoz';
update content_bodies set title = '【雪原キャンプ】夏花畑の上で夜景と満天の星空冬キャンプ', description = '雪原キャンプが楽しめるフラワーランドかみふらのでは、晴れた夜に満点の星空が広がり、日が沈むと街の灯りが見えてきます。広々とした丘からは上富良野の大地と大雪山連峰を一望でき、他にはない貴重なロケーションで自然を満喫できます。詳細はフラワーランドかみふらののウェブサイトをご覧ください。' where id = 'iO5O98gYYcQEOkNVeAQCn';
update content_bodies set title = 'Snowfield Camping: Winter Camp with Night Views and Starry Skies Above Summer Flower Fields', description = 'Experience snowfield camping at Flower Land Kamifurano, where clear nights reveal a stunning starry sky and city lights emerge as the sun sets. From the expansive hills, enjoy breathtaking views of Kamifurano''s landscape and the Daisetsuzan mountain range, offering a unique location to immerse yourself in nature. For more information, visit Flower Land Kamifurano''s website.' where id = 'H0BWcnQygk8EZofzCSNtE';
update content_bodies set title = '東京ディズニーシー フードツアー クリスマス2024！🎄', description = '東京ディズニーリゾートのクリスマスイベントが2024年11月15日から12月25日まで開催されます。このフードツアーでは、東京ディズニーシーでのさまざまなクリスマスの美味しい（時にはそうでない）お菓子を紹介します。カフェ・ポルトフィーノやニューヨークデリ、ドックサイドダイナーなど、いくつかの飲食店を訪れ、最後にはおすすめも紹介します。また、東京ディズニーリゾートに関連するチケットやガイド、アプリのリンクも提供されており、フードツアーの各セグメントのタイムスタンプも記載されています。' where id = 'HnQFD1Fj3baTIEkh_qUoc';
update content_bodies set title = 'Tokyo DisneySea FOOD TOUR Christmas 2024! 🎄', description = 'Join the Tokyo Disney Resort for its Christmas event from November 15 to December 25, 2024. This food tour at Tokyo DisneySea showcases a variety of festive treats, both delicious and not-so-delicious. The video includes visits to several dining locations, such as Cafe Portofino, New York Deli, and Dockside Diner, among others. Viewers are encouraged to stay until the end for personal recommendations. Additionally, useful links for tickets, guides, and apps related to Tokyo Disney Resort are provided, along with timestamps for different segments of the food tour.' where id = 'ZckffE3rWfZFbF7cXjtGY';
update content_bodies set title = '2021.06.19 雪渓の中を富良野岳へ向け登山道整備', description = '6月20日に予定されていた第43回十勝岳山開きはコロナ禍の影響で中止となりましたが、十勝岳安全祈願祭とコース整備は有志の協力により行われました。残雪があり、特にカミホロ分岐から富良野岳稜線分岐間では、富良野岳寄りに多くの残雪が見られます。アイゼンは不要ですが、滑りやすくなっているため、登山者は注意して登ることが求められます。' where id = 'sFaVKJd6xtSji8FhinPm0';
update content_bodies set title = 'Trail Maintenance Towards Furano Dake Through Snowfield on June 19, 2021', description = 'The 43rd Tokachidake Mountain Opening, scheduled for June 20, was canceled due to the COVID-19 pandemic. However, the Tokachidake Safety Prayer Ceremony and trail maintenance were carried out with the help of volunteers. There is still residual snow, particularly between the Kamihoro junction and the Furano Dake ridge junction, with more snow observed closer to Furano Dake. While crampons are not necessary, the trail is slippery, so hikers should exercise caution to avoid slipping.' where id = 'f2sua0fM-Os9aCx9JtM0n';
update content_bodies set title = '上富良野町をアピールする 【上富良野高校２学年 地域探究データ 1班】', description = '上富良野高校の生徒が制作した動画です。生徒たちは、上富良野の魅力を多くの人に知ってもらい、興味を持ってもらいたいと考えています。単なる紹介にとどまらず、テンポよくまとめることを目指しました。' where id = 'UEoe3uHvuNhrPoDXF25HP';
update content_bodies set title = 'Promoting Kamifurano Town - Kamifurano High School 2nd Year Regional Research Data Group 1', description = 'This is a video created by students from Kamifurano High School. The students express their desire to share the charm of Kamifurano with a wider audience and spark interest. They aimed to present the information not just as a simple introduction, but in a lively and engaging manner.' where id = 'NHAg4GAYZyhBD4PfXxCS5';
update content_bodies set title = 'LIVE 34th北の大文字カウントダウン2020－2021 北海道上富良野町', description = '「北の大文字」は、元旦午前0時に上富良野町の日の出公園の斜面に、縦70m・横50mの「大」の文字を描く幻想的なイベントです。300本の鉄杭にかみふらの神社からの御神火を灯し、雪に覆われた斜面に大文字を浮かび上がらせます。34回目を迎える今年は、大文字と花火で新年を祝いますが、新型コロナウイルス感染症の影響で無観客での開催となります。その様子はライブ配信され、上富良野町の魅力を全世界に発信します。イベントは23:40にライブ中継が始まり、00:00に大文字に点火、町長の挨拶や花火打ち上げが行われます。' where id = 'jZnOqXMNAxxcEn0a6X0_L';
update content_bodies set title = 'LIVE 34th Northern Daimonji Countdown 2020-2021 in Kamifurano, Hokkaido', description = 'The ''Northern Daimonji'' event takes place at midnight on New Year''s Day, where a 70m by 50m ''Dai'' character is illuminated on a snowy slope in Hinode Park, Kamifurano, using 300 iron stakes lit with sacred fire from Kamifurano Shrine. This spectacular event has become a beloved New Year''s tradition for the local community. Celebrating its 34th year, the event combines the ''Dai'' character and fireworks to create a dynamic and enchanting atmosphere. Due to the COVID-19 pandemic, this year''s event will be held without an audience, but it will be live-streamed to showcase the charm of Kamifurano to the world. The event schedule includes a live broadcast starting at 23:40, with the lighting of the ''Dai'' character at midnight, followed by a greeting from the town mayor and a fireworks display.' where id = 'Z_jAOrrYzXZAjWZFP_k-p';
update content_bodies set title = '【4K空撮】2020夜明け前の富良野岳の紅葉と雲海', description = '北海道の十勝岳温泉は、紅葉を観ることができる最も早い場所の一つです。2020年の紅葉は、富良野岳周辺の白樺やダケカンバの黄色が美しく輝いていました。この日は上富良野町の盆地に雲海が広がり、朝日が前富良野岳の斜面を照らしました。例年は紅葉の見頃が数日で終わりますが、今年は約2週間も続きました。土日には十勝岳温泉の駐車場が常に満車で、道路脇にも長い駐車列ができていました。台風の影響が少なく、初雪も遅れたため、見事な紅葉が長く楽しめました。多くの人々が登山や写真撮影を楽しんでいました。凌雲閣からの紅葉も見納めとなり、これからは麓に向かって降りてくるでしょう。' where id = 'P0Y_l9Xzhn35R5lHZqdT-';
update content_bodies set title = '4K Aerial Footage: Autumn Foliage and Sea of Clouds at Furano-dake Before Dawn 2020', description = 'Tokachidake Onsen in Hokkaido is known for being one of the first places to witness autumn foliage. In 2020, the yellow leaves of the white birch and daikamba trees around Furano-dake shone brightly. On this particular day, a sea of clouds appeared in the basin of Kamifurano Town, with the morning sun illuminating the slopes of Furano-dake. Typically, the peak viewing period lasts only a few days, but this year it extended for about two weeks. The parking lot at Tokachidake Onsen was always full on weekends, with long lines of cars along the roadside. The impact of typhoons was minimal, and the first snowfall was delayed, allowing for a stunning display of autumn colors to last longer. Many visitors enjoyed hiking and capturing the beautiful foliage with their cameras. The autumn colors from Ryouunkaku, which delighted many, are now nearing their end as they gradually descend to the foothills.' where id = 'SHsNJpCpD2fNmgtMCgaaI';
update content_bodies set title = '【絶景茨城】紅葉［4K］｜VISIT IBARAKI, JAPAN', description = '2015年11月17日に撮影されたこの映像では、茨城県の代表的な紅葉スポットを紹介しています。高萩市の花貫渓谷、常陸太田市の竜神大吊橋、大子町の永源寺・袋田の滝、北茨城市の花園渓谷など、茨城の秋の絶景を収めています。鮮やかな赤と黄色で彩られた風景をお楽しみください。' where id = 'T5ZexGvVNEg1121wF7kbX';
update content_bodies set title = 'Stunning Ibaraki: Autumn Foliage [4K] | VISIT IBARAKI, JAPAN', description = 'Captured on November 17, 2015, this video showcases the breathtaking autumn scenery of Ibaraki Prefecture. It features iconic spots such as Hanakuni Valley in Takahagi City, Ryujin Big Suspension Bridge in Hitachiota City, Eigenji and Fukuroda Falls in Daigo Town, and Hanazono Valley in Kitaibaraki City. Enjoy the vibrant reds and yellows that paint the autumn landscape of Ibaraki.' where id = 'l0KQ6IK-3ODCXrd6Cyj0a';
update content_bodies set title = '【絶景茨城】大杉神社 大杉祭（あんばまち）　茨城県稲敷市', description = '大杉神社は茨城県稲敷市に位置し、古くから「あんばさま」として信仰を集めてきました。日本唯一の「夢むすび大明神」としても知られ、奇跡や伝承が語り継がれています。秋に行われる大杉祭（あんばまち）では、華やかな行列や地元の伝統芸能「あんば囃子」が披露され、地域の人々に親しまれています。この祭りは、地域の文化遺産とコミュニティの絆を示す重要なイベントです。' where id = 'eEqVua95aZMTTBkwOGEkm';
update content_bodies set title = 'Oosugi Shrine and Oosugi Festival in Ibaraki, Japan', description = 'Oosugi Shrine, located in Inashiki City, Ibaraki Prefecture, has been a site of worship for the local community for centuries, known as ''Anba-sama.'' It is recognized as the only ''Yume Musubi Daimyojin'' in Japan, associated with miraculous tales and traditions. The Oosugi Festival, also known as ''Anbamachi,'' is celebrated in autumn, featuring vibrant parades and traditional performances like ''Anba Bayashi,'' enjoyed by the local residents. This festival showcases the rich cultural heritage and community spirit of the area.' where id = '0cu8vv_fjRJOJb6-OVU0a';
update content_bodies set title = '【4K空撮】KAMIFURANO LIGHTING-UP & FIREWORKS ONLINE 2020', description = 'この動画は、2020年7月22日にライブ配信されたKAMIFURANOの点灯イベントと花火を4K解像度で再編集したものです。なお、日の出ラベンダー園での無許可のドローン撮影は禁止されています。' where id = '-omWYOVZJOZRQvVA856jg';
update content_bodies set title = 'KAMIFURANO LIGHTING-UP & FIREWORKS ONLINE 2020 (4K Aerial Footage)', description = 'This video is a re-edited version of the live stream that took place on July 22, 2020, showcasing the KAMIFURANO lighting-up event and fireworks in stunning 4K resolution. Please note that unauthorized drone filming at the Hinode Lavender Park is prohibited.' where id = 'YFVaUQkTDxb2djxZy_7F2';
update content_bodies set title = '【4K空撮】KAMIFURANO LIGHTING-UP & FIREWORKS ONLINE 2020 リハ', description = '2020年7月22日に上富良野町の日の出ラベンダー園で無観客のライブショーが行われました。短期間での準備にもかかわらず、Nene&Wakaのリハーサルには関わったすべての人の思いが詰まっています。開催までシェアしていただいた皆様に感謝申し上げます。なお、会場使用やドローン撮影については関係機関との調整が済んでいますのでご安心ください。ただし、日の出ラベンダー園での無許可のドローン撮影は禁止されていますのでご注意ください。' where id = 'ZUfA2m9LYHbxMOyp479jg';
update content_bodies set title = '4K Aerial Footage: KAMIFURANO LIGHTING-UP & FIREWORKS ONLINE 2020 Rehearsal', description = 'On July 22, 2020, a live show without an audience was held at the Hinode Lavender Park in Kamifurano. Despite the short preparation time, the rehearsal by Nene & Waka encapsulated the efforts and thoughts of everyone involved. We express our gratitude to all who shared in the lead-up to the event. Note: Coordination with relevant organizations for venue use and drone filming has been completed. Please be aware that unauthorized drone filming at Hinode Lavender Park is prohibited.' where id = 'IlwwEU82RKMKHwhMtnjMV';
update content_bodies set title = '【4K空撮】十勝連峰 三段山 吹上温泉コース登山口情報', description = '2019年8月5日、地元の有志が登山道整備のために資材を運搬しました。三段山は標高1748mで、十勝連峰の中では特に高くはありませんが、その山頂からの景色は飽きることがなく、高揚感を与えてくれます。山頂からは主峰の十勝岳、上ホロメカトク山、上富良野岳、三峰山、富良野岳といった山々の大パノラマを楽しむことができます。' where id = 'cFHMTh6wha7IwYktTJmtb';
update content_bodies set title = '4K Aerial Footage: Tokachi Mountain Range, Sandan Mountain, and Fukiage Onsen Trailhead Information', description = 'On August 5, 2019, local volunteers transported materials for trail maintenance. Sandan Mountain, standing at 1,748 meters, is not particularly high among the Tokachi Mountain Range, but the view from its summit offers an exhilarating experience that never gets old. From the peak, one can enjoy a grand panorama of the main peak Tokachidake, Kamihoro Mekatoku Mountain, Kamifurano Mountain, Sanpō Mountain, and Furano Mountain.' where id = 'MCoRERV9PRA5Jf8FkQhpx';
update content_bodies set title = '2019 深山峠さくら園', description = 'この動画は2019年の深山峠さくら園について紹介しています。深山峠さくら園は、美しい桜の景色を楽しむことができる場所で、訪れる人々にとって特別な体験を提供しています。桜の花が咲く季節には、多くの観光客が訪れ、自然の美しさを堪能します。' where id = 'P2XdC8lPohqb9BkM00Ekh';
update content_bodies set title = '2019 Miyama Pass Cherry Blossom Garden', description = 'This video introduces the Miyama Pass Cherry Blossom Garden from 2019.' where id = 'WJR7tQqgTNWPqxn_gd_xi';
update content_bodies set title = 'タウシュベツ橋梁と2019年話題になったアイスバブル', description = '国鉄士幌線旧線の糠平ダム建設によって水没したタウシュベツ橋梁と、2019年に話題になったアイスバブルを観に行きました。冬の寒い時期に、糠平湖の底から発生したメタンガスの気泡が凍ったアイスバブルの上を歩きながら、タウシュベツ橋梁まで向かいました。' where id = 'humbHNCW4lmzDxWoQ7s8I';
update content_bodies set title = 'Taushubetsu Bridge and the 2019 Ice Bubbles', description = 'I visited the Taushubetsu Bridge, which was submerged due to the construction of the Nukabira Dam on the former Japan National Railways Shihoro Line, and the Ice Bubbles that became popular in 2019. During the cold winter months, I walked on the frozen Ice Bubbles formed by methane gas bubbles rising from the bottom of Lake Nukabira, making my way to the Taushubetsu Bridge.' where id = 'S-psEmQcPCMJ3qan2VWi8';
update content_bodies set title = '2017年TOUR OF KAMUI', description = 'この動画は2017年TOUR OF KAMUIについて紹介しています。' where id = 'Rhb_4HBLv-NtKD7i9jpn-';
update content_bodies set title = '2017 TOUR OF KAMUI', description = 'This video introduces the 2017 TOUR OF KAMUI.' where id = 'nLD0LbNjVorfwh-an4cwp';
update content_bodies set title = 'KAMIFURANO LIGHTING-UP & FIREWORKS ONLINE 2020', description = '上富良野町のラベンダー畑は現在見ごろを迎えており、例年多くの観光客が訪れます。しかし、今年はコロナ禍の影響で多くの人が北海道に来られません。そこで、ラベンダーの美しさを共有するために、ライブ配信イベントが開催されます。無数のランタンキャンドルで彩られたラベンダー畑と花火がYouTubeで放送されます。特別ゲストには牧野由依さんが登場し、ダンス＆ボーカルグループのNene＆Wakaによるライブパフォーマンスも行われます。イベントは2020年7月22日19:30から開始され、会場は一般公開されないため、自宅から視聴することが推奨されます。悪天候の場合は中止となる可能性があり、その判断は当日の17時に行われます。' where id = 'G5LksQicTLHoYwYJPmkBC';
update content_bodies set title = 'KAMIFURANO LIGHTING-UP & FIREWORKS ONLINE 2020', description = 'The Kamifurano Lavender Fields are currently in full bloom, attracting many tourists each year. However, due to the COVID-19 pandemic, many are unable to visit Hokkaido. To share the beauty of the lavender, a live stream event will be held, showcasing the stunning lavender fields illuminated by countless lanterns and featuring fireworks, all broadcasted on YouTube. The event will include a special guest appearance by Yui Makino and a live performance by the dance and vocal group Nene & Waka. The live stream will start on July 22, 2020, at 7:30 PM, and viewers are encouraged to watch from home as the venue will be closed to the public. The event may be canceled due to inclement weather, with a decision made by 5 PM on the day of the event.' where id = 'xqpKHqF3c2JS7MNwSQF3O';
update content_bodies set title = '上富良野神社例大祭　神輿保存会「徳神会」', description = '上富良野神社の例大祭は、2018年8月1日に開催されました。この祭りは、神輿保存会「徳神会」によって運営され、地域の文化遺産や伝統を祝う重要なイベントです。地元の人々にとって、神社との結びつきを深める機会となっています。' where id = 'vLFxIe-Tyv-S3308dmgpG';
update content_bodies set title = 'Kamifurano Shrine Grand Festival - Mikoshi Preservation Society ''Toku Shinkai''', description = 'The Kamifurano Shrine Grand Festival, organized by the Mikoshi Preservation Society known as ''Toku Shinkai'', took place on August 1, 2018. This event is significant for the local community, celebrating cultural heritage and traditions associated with the shrine.' where id = 'nti-kiEsHxGS5nQ5cUTCY';
update content_bodies set title = '【絶景茨城】ポピー／キンセンカ［4K］茨城県下妻市', description = '2015年5月21日に撮影されたこの映像は、茨城県下妻市にある小貝川ふれあい公園の美しい風景を紹介しています。5月には、公園内のフラワーゾーンが壮大な筑波山を背景に、色とりどりのシャーレポピーとキンセンカで埋め尽くされます。' where id = '0M1o1WlkC4vTBVXWx5BYM';
update content_bodies set title = 'Stunning Ibaraki: Poppies and Marigolds [4K] in Shimotsuma City, Ibaraki Prefecture', description = 'On May 21, 2015, the video showcases the stunning scenery at Kobai River Fureai Park in Shimotsuma City, Ibaraki Prefecture. In May, the flower zone within the park is filled with vibrant Shale Poppies and Marigolds, set against the majestic backdrop of Mount Tsukuba.' where id = '5LdN5AbVAVI7tbLHxP18K';
update content_bodies set title = '十勝岳ラベンダーロード2018', description = '十勝岳ラベンダーロードは、一度は訪れたい美しいラベンダー畑のスポットです。上富良野から十勝岳温泉郷に向かう道道291号吹上・上富良野線沿いに約7kmにわたってラベンダーが植えられており、遊歩道が続いています。延々と続く紫の花々は、雄大な十勝岳連峰と相まって、素晴らしい自然の景観を演出しています。' where id = 'LBCJaLEvXwN7pHhtK3Cb_';
update content_bodies set title = 'Tokachidake Lavender Road 2018', description = 'The Tokachidake Lavender Road is a must-visit destination for those who want to experience the beauty of lavender fields. Stretching approximately 7 kilometers along the Dōbō 291 road from Kamifurano to the Tokachidake Onsen area, this walking path is lined with lavender plants. The endless line of purple flowers creates a stunning contrast against the majestic Tokachidake mountain range, showcasing the breathtaking natural scenery.' where id = 'R31i2ppd3IKbNDPZFygr8';
update content_bodies set title = '上富良野ふれあい昼食会に参加', description = '2018年4月19日、社会福祉協議会が主催するふれあい昼食会に、よさいこい有頂天のメンバーが参加しました。参加したお年寄りの中には、生らべとんを見たことがない方もおり、大変喜んでいただきました。' where id = '8n-lGbrDwasx-fIrTFbU1';
update content_bodies set title = 'Participation in Kamifurano Interaction Lunch Meeting', description = 'On April 19, 2018, members of the Yosai Koi Uchatten participated in an interaction lunch meeting organized by the Social Welfare Council. Many elderly attendees had never seen a live rabaton, and they were very pleased to experience it.' where id = 'Wtf48FUsN8c7moygG2WbH';
update content_bodies set title = '十勝岳温泉✖パンフレット撮影メイキング動画', description = '2018年3月27日、快晴の十勝岳温泉郷で観光パンフレットの温泉紹介を印刷会社とモデルさんに協力をして撮影しました。まだまだ、雪見温泉が楽しめる十勝岳温泉郷でなごり雪を楽しみませんか？' where id = 'X4rek51bEUg9WZJvrbyHO';
update content_bodies set title = 'Tokachidake Onsen x Pamphlet Shooting Making Video', description = 'On March 27, 2018, a sunny day at Tokachidake Onsen, a promotional pamphlet featuring the hot springs was filmed with the cooperation of a printing company and models. Enjoy the lingering snow while experiencing the snow-viewing hot springs at Tokachidake Onsen.' where id = 'bBt4a5PLDc2O5fWqatsW_';
update content_bodies set title = '三重県津市駅前ストリートまつり', description = '2017年4月9日、姉妹提携都市である三重県津市で開催された駅前ストリートまつりに、らべとんが参加しました。このイベントは地域の活性化を目的としており、多くの人々が集まり、様々な催し物が行われました。らべとんの参加は、地域の文化交流を促進する一環として重要な役割を果たしました。' where id = '7BYTMgWgdfmDJWaZD7ivH';
update content_bodies set title = 'Tsu City Station Front Street Festival', description = 'On April 9, 2017, Rabeton participated in the Tsu City Station Front Street Festival, which is held in the sister city of Mie Prefecture.' where id = 'scX5SRwj0_GOi_DtOlgGF';
update content_bodies set title = '続・冬の閑散期に観光客を呼び込むために！', description = '2018年3月22日、冬の閑散期に観光客を呼び込むためのプログラム作りとして、十勝岳温泉周辺をスノーシューで散策しました。自然に吹き溜まった雪の中に雪洞を掘り、その中で越冬ジャガイモを蒸かして食べ、ラベンダーティーを頂く体験をしました。' where id = 'grk3ZNVfjDng24ONpG5D5';
update content_bodies set title = 'Continuing Efforts to Attract Tourists During the Winter Off-Season!', description = 'On March 22, 2018, a program was developed to attract tourists during the winter off-season by exploring the Tokachidake Onsen area with snowshoes. Participants dug snow caves in the naturally accumulated snow, where they steamed winter potatoes and enjoyed lavender tea.' where id = 'EmHNk0rKPkt9ff9S49m9y';
update content_bodies set title = '北海道上富良野町の夜明け', description = '2018年3月21日朝5時、日が昇る前に撮影されたこの写真は、上富良野町の街並みを映し出しています。街の風景から千望峠、かんのファームまでの眺めが広がっています。' where id = 'lntzvUSNXU7oFCWY-4gGv';
update content_bodies set title = 'Dawn in Kamifurano, Hokkaido', description = 'Captured before sunrise on March 21, 2018, at 5 AM, this photograph showcases the town of Kamifurano. The view extends from the streets of the town to Chippu Pass and Kanno Farm.' where id = 'YE5Jo33hHPqSxfWj24D8E';
update content_bodies set title = '第５４回かみふらの雪まつり', description = 'この動画は第５４回かみふらの雪まつりについて紹介しています。' where id = '0PdZuDY2nxaKByEp0e_bk';
update content_bodies set title = '54th Kamifurano Snow Festival', description = 'This video introduces the 54th Kamifurano Snow Festival.' where id = 'VavqccxQOMWQD75ufdYUU';
update content_bodies set title = '冬の閑散期に観光客を呼び込むために', description = '2017年3月10日、北海道ネイチャーセンターの石川氏、洞爺湖ガイドセンターの小川氏、上富良野町のヤマイチの斎藤氏によるガイドで、冬の上富良野町の魅力を探るイベントが行われました。冬の季節におけるこの地域の独自の魅力を紹介することが目的でした。' where id = 'qomXMRWbgXSSAXf5jJpnr';
update content_bodies set title = 'Attracting Tourists During the Winter Off-Season', description = 'On March 10, 2017, a guided exploration of the winter attractions in Kamifurano Town was conducted by Ishikawa from the Hokkaido Nature Center, Ogawa from the Lake Toya Guide Center, and Saito from Yamaiti in Kamifurano. The focus was on showcasing the unique charm of the area during the winter season.' where id = 'ZVRCburukFShy10FsnmR6';
