update content_bodies set title = 'FHD0001', description = 'This video introduces FHD0001.' where id = 'uclWeDy95_7cdM3u_p8Qx';
update content_bodies set title = '説明開花情報　「深山峠さくら園」5/4', description = 'これは、5月4日現在の深山峠さくら園の開花情報です。' where id = 'eF0Sip7l77ZoqQGc59o-k';
update content_bodies set title = 'Blooming Information at Miyama Pass Sakura Garden on May 4', description = 'This is the blooming information for the Miyama Pass Sakura Garden as of May 4.' where id = 'VTqTMIZmmcxLieSlOoMeY';
update content_bodies set title = '上富良野サイクリング　VR360', description = 'この動画は上富良野でのサイクリングを紹介しています。上富良野は美しい自然に囲まれた地域で、サイクリングを楽しむには最適な場所です。動画では、サイクリングの魅力やコースの特徴、周辺の景観などが紹介されており、視聴者に上富良野でのサイクリング体験を伝えています。' where id = 'Ym62i4pnN-4dytG9wrdUW';
update content_bodies set title = 'Kamifurano Cycling VR360', description = 'This video introduces cycling in Kamifurano.' where id = 'MZUy2UwDBlwWZlLokxEyP';
update content_bodies set title = '上富良野サイクリング　VR360', description = 'この動画は上富良野でのサイクリングを紹介しています。上富良野は美しい自然に囲まれた地域で、サイクリングを楽しむには最適な場所です。動画では、サイクリングのルートや風景、地域の魅力について詳しく説明されています。特に、四季折々の風景や地元の特産品など、観光客にとって魅力的な情報が盛り込まれています。上富良野のサイクリングを通じて、自然の美しさや地域の文化を体験できることが強調されています。' where id = '6M7UJd-zyAt5-P_-4iLQp';
update content_bodies set title = 'Kamifurano Cycling VR360', description = 'This video introduces cycling in Kamifurano.' where id = '5iPfB8EgdB-2YV0NInmKK';
update content_bodies set title = '自分で打ったお蕎麦、食べたことある?', description = '北広島町の豊平どんぐり村では、そば打ち体験ができる「そば道場」があります。そば粉や水、道具一式が用意されており、手ぶらで参加できるのが魅力です。そば打ち職人の古田さんの指導のもと、参加者は自分の手でそばをこね、のし、切る体験ができます。この体験は家族や友人、恋人同士で楽しむことができ、特別な思い出を作るのに最適です。また、個人や最大30名の団体でも参加可能で、子供会などのレクリエーションにも利用できます。自分で打ったお蕎麦は格別で、近くの「そば処どんぐり庵」で味わうこともできます。道場は10:30から14:30まで営業しており、詳細は直接お問い合わせください。' where id = 'HXPvUJQCsg4mGneMEgktl';
update content_bodies set title = 'Have You Ever Made Your Own Soba?', description = 'In Kitahiroshima Town, you can have a unique experience at the Toyohira Donguri Village, where the local soba-making dojo offers hands-on soba-making classes. All necessary materials, including buckwheat flour, water, tools, and aprons, are provided, allowing participants to join without any prior preparation. Under the guidance of soba master Furuta, participants can enjoy the tactile experience of kneading the dough by hand, rolling it out, and cutting it into noodles. This activity is perfect for families, friends, or couples looking for a memorable experience. It can also accommodate individuals and groups of up to 30 people, making it suitable for various recreational activities. After making your own soba, you can enjoy it at the nearby soba restaurant, Donguri-an, which serves authentic hand-made soba. The dojo operates from 10:30 AM to 2:30 PM, with specific days for classes. For more details, contact them directly.' where id = 'H4QXzkCnAaKkMJBoE5Mzc';
update content_bodies set title = '11/13に放送されたひろしま満点ママ『地元っこに聞いてみた！』の取材の様子をお届けします', description = '11月13日に放送されたひろしま満点ママの『地元っこに聞いてみた！』の取材が行われました。取材場所は千代田インターから車で約5分の「古保利薬師」で、平安時代に弘法大師が開いたとされる歴史ある場所です。樹齢1000年を超える大ひのきが圧巻で、神秘的な佇まいの古保利薬師は鮮やかな紅葉に囲まれています。取材日は紅葉の見頃には少し早かったものの、訪れたお客さんたちは紅葉を楽しんでいました。取材にはボールボーイの佐竹さんと高田萌子さんが参加し、和やかな雰囲気で進行しました。ぜひ、また北広島町に遊びに来てほしいとのことです。' where id = 'lEsZ4HZTy24SOAcK0UoTH';
update content_bodies set title = 'Coverage of the Interview on Hiroshima Manten Mama aired on 11/13: ''We Asked the Locals!''', description = 'On November 13, the Hiroshima Manten Mama program featured an interview segment titled ''We Asked the Locals!'' The location was ''Kobori Yakushi,'' a historical site believed to have been established by Kobo Daishi during the Heian period, located about five minutes by car from Chiyoda Interchange. The site boasts a stunning 1,000-year-old giant hinoki tree. The ancient temple, Kobori Yakushi (Kobori-san Fukko-ji), is surrounded by vibrant autumn leaves. Although the interview took place before the peak of the fall colors, many visitors were already enjoying the scenery. The filming team included Ball Boy Satake and Moeko Takada, who provided support and humor during the shoot. They also introduced other local spots over two weeks. The hosts'' chemistry was evident, and the experience left a positive impression. Viewers are encouraged to visit Kitahiroshima Town again.' where id = 'xRbuPwFYVha2gzZJJBqyd';
update content_bodies set title = 'いざ、韓国へレッツら モー‼️', description = '2023年9月30日から10月2日まで、韓国の金堤市で「キムマンギョンウェエミットル歌保存会」との文化交流を行うため、視察と市長への表敬訪問を実施しました。今年6月には北広島町の「壬生の花田植」で同会の演舞が行われ、観客の関心を集めました。団員たちの鮮やかな衣装と楽しそうな表情が印象的でした。今回の訪問には、壬生と川東の田楽団員、北広島町議会議長、観光協会役員が参加し、韓国での「壬生の花田植」上演を目指しました。金堤市は歴史ある農地が広がり、温かい人々が迎えてくれました。パク会長は親切に対応し、様々な手配をしてくれました。言葉は異なりますが、伝統芸能を守る思いは共通です。今後も両市町の素晴らしい伝統芸能の交流を進めていきます。視察に参加した皆様、お疲れ様でした！通訳のパク先生、ありがとうございました！' where id = '21jMdFmivE0_7CAF2QJqn';
update content_bodies set title = 'Let''s Go to Korea!', description = 'From September 30 to October 2, 2023, a delegation visited Korea to engage in cultural exchange with the Kim Mangyeongwe Emittul Song Preservation Society in Gimje City, a center of agricultural culture in South Korea, and to observe the venue for the ''Jiheung Festival.'' The visit included meetings with the festival''s executive committee and a courtesy visit to the mayor of Gimje City. In June, the Kim Mangyeongwe Emittul Song Preservation Society performed at the ''Mibu Hanada Ue'' event in Kitahiroshima Town, captivating the audience with their vibrant costumes and unique sounds. The delegation, including members from the Mibu and Kawahigashi dance groups, as well as local officials, aimed to showcase their own traditional performance in Korea. Gimje City, with its rich agricultural history, shares a warm atmosphere similar to Kitahiroshima. The president of the preservation society warmly welcomed the delegation and facilitated various arrangements. Despite language differences, both communities share a passion for preserving their proud traditional arts. The delegation looks forward to further exchanges in the future.' where id = 'XQsfNUFgLbUkqdA-TOlgC';
update content_bodies set title = '【絶景茨城／祝！ラムサール条約登録】涸沼［4K］茨城県茨城町｜VISIT IBARAKI, JAPAN', description = '2015年5月11日に撮影された涸沼は、海水と淡水が混じり合う日本でも希少な汽水湖です。茨城県のほぼ中央に位置し、茨城町、鉾田市、大洗町にまたがっています。この流域には多様な動植物が生息しており、貴重な生態系を形成しています。この生態系は地元の水産業にも大きな恩恵をもたらしています。' where id = 'hSPWjpSuYlFVOWSqwDgD5';
update content_bodies set title = 'Stunning Ibaraki / Congratulations! Ramsar Convention Registration - Lake Hirakuma [4K] Ibaraki Prefecture, Ibaraki Town | VISIT IBARAKI, JAPAN', description = 'Filmed on May 11, 2015, Lake Hirakuma is a rare brackish lake in Japan where seawater and freshwater mix. It is located in the central part of Ibaraki Prefecture, spanning Ibaraki Town, Hokota City, and Oarai Town. The watershed is home to a rich ecosystem with a variety of flora and fauna, which supports the local fishing industry.' where id = '_XgWl6wlfa6z-BRnnjEdD';
update content_bodies set title = '👹10/4(土)第77回芸石神楽競演大会👹 #北広島町', description = '第77回芸石神楽競演大会が、令和7年10月4日(土)に北広島町のKumahira Parkで開催されます。開場は10:30、開演は11:30です。指定席のチケットは9月7日から道の駅舞ロードIC千代田管理棟で販売開始され、自由席は8月10日から販売中です。各駐車場から会場までの無料送迎バスも運行されます。プログラムには複数の神楽団の演目が含まれ、休憩も設けられています。チケットの価格は座席の種類によって異なり、会場内でのビデオ撮影は禁止されています。詳細については、北広島町観光協会にお問い合わせください。' where id = 'UWe57CEepUwYvRA4gSxoH';
update content_bodies set title = '77th Geiseki Kagura Performance Competition on October 4th', description = 'The 77th Geiseki Kagura Performance Competition, a prestigious traditional event in the region, will take place on October 4, 2025, at Kumahira Park in Kitahiroshima. Doors open at 10:30 AM, and the performance starts at 11:30 AM. Tickets for designated seating will be available from September 7 at the Michi-no-Eki Mai Road IC Chiyoda management building, with free seating tickets already on sale since August 10. Free shuttle buses will operate from various parking areas to the venue. The schedule includes performances by several Kagura groups, with breaks in between. Ticket prices vary based on seating type, and video recording is prohibited inside the venue. For inquiries, contact the Kitahiroshima Tourism Association.' where id = 'XU_J1zSmQO-UDaY_z_i_G';
update content_bodies set title = '農家さんがつくった『お米と野菜のパスタ』', description = '観光協会の職員が、豊平にある中原ファームを訪れ、農家が作った『お米と野菜のパスタ』について学びました。このファームでは、エグみのないほうれん草が栽培されており、子どもでも食べやすいとのこと。中原ファームの代表、多川さん一家が案内してくれ、次男の陽翔くんがパスタの特徴を説明しました。このカラフルなパスタは、子どもたちに野菜をたくさん食べてもらいたいという思いから開発され、野菜の粉末と米粉を使ってもちもちの食感に仕上げられています。お米の甘みもあり、子どもから大人まで楽しめる味わいです。ショートパスタとして、スープやサラダ、グラタンなど様々な料理にアレンジ可能です。価格は648円（税込）で、道の駅舞ロードIC千代田や産直さんさん市、ECサイトで販売中です。' where id = '4iYPymZviCiINW5YK0Uv_';
update content_bodies set title = 'Pasta Made from Rice and Vegetables by Local Farmers', description = 'A staff member from the tourism association visited Nakahara Farm in Toyohira after hearing about their unique ''rice and vegetable pasta.'' The farm features a large area of spinach that is mild and easy for even picky eaters to enjoy. The farm''s representative, Mr. Takagawa, and his family provided a tour, with his son, Haruto, explaining the pasta. This colorful pasta was developed with the intention of encouraging children to eat more vegetables. Made from a blend of vegetable powder and rice flour, it has a chewy texture and a hint of sweetness from the rice, making it appealing to both children and adults. The short pasta can be used in various dishes, including soups, salads, and gratins. The pasta is available for 648 yen (tax included) at locations such as the Michi no Eki Mai Road IC Chiyoda and the San San Market, as well as on their e-commerce site.' where id = 'ca2KVHw6jBYMvjYY5GUq3';
update content_bodies set title = 'いなべ市にオープン！Nordisk Hygge Cirles UGAKEIをご紹介', description = '2023年4月、いなべ市に「Nordisk Hygge Circles UGAKEI（ノルディスク ヒュゲ サークルズ ウガケイ）」がオープンしました。この施設では、宇賀渓の豊かな自然の中で、世界的なアウトドアブランド・ノルディスクの世界観を体験しながら、グランピングやキャンプを楽しむことができます。観光三重では、UGAKEIの魅力を詳しく紹介しています。' where id = 'COLfBuZxqwVnuQkSmGO2k';
update content_bodies set title = 'Nordisk Hygge Circles UGAKEI Opens in Inabe City!', description = 'In April 2023, Nordisk Hygge Circles UGAKEI opened in Inabe City. Visitors can enjoy glamping and camping amidst the rich nature of Ugakei while immersing themselves in the world of the globally recognized outdoor brand, Nordisk. The site offers a unique experience that combines outdoor activities with the brand''s philosophy of coziness and comfort.' where id = 'XP_O0EmUyClOR__oVZRQf';
update content_bodies set title = '木津呂【ドローン撮影】(熊野市)｜観光三重｜三重県の観光・旅行情報', description = '木津呂は「日本の秘境」や「奥熊野のパワースポット」として知られ、ドローン撮影が行われました。和歌山県から熊野市へ流れる北山川の河口付近に位置し、川の大蛇行によって独特の形状をしています。風水では「瀧穴」と呼ばれ、気がみなぎる特別な場所とされています。近年、テレビ番組でも取り上げられ、注目を集めています。' where id = 'N6emnc7kfgNRYCApTsWpa';
update content_bodies set title = 'Kizuro [Drone Photography] (Kumano City) | Tourism Mie | Mie Prefecture Travel Information', description = 'Kizuro, known as a ''hidden gem of Japan'' and a ''power spot in the Okukumano region,'' has been captured through drone photography. Located near the mouth of the Kitayama River flowing from Wakayama Prefecture to Kumano City, it features a unique shape due to the river''s meandering. In feng shui, it is referred to as a ''waterfall cave'' and is considered a special place filled with energy. Recently, it has gained attention, being featured in various television programs.' where id = 'W5-53xaDBGTZmxcVANGgj';
update content_bodies set title = '七里御浜【ドローン撮影】(熊野市)｜観光三重｜三重県の観光・旅行情報', description = '七里御浜は、世界遺産熊野古道の「浜街道」として知られ、ドローンで空撮されました。熊野市から紀宝町にかけて約22km続く日本一長い砂礫海岸であり、「日本の渚百選」や「21世紀に残したい自然百選」にも選ばれています。荒々しい黒潮を受け入れるこの浜には、熊野灘の荒波に磨かれた丸い小石が美しく敷き詰められています。' where id = '5B_t-K7RIlb0CKoJxtfA5';
update content_bodies set title = 'Shichiri Mihama [Drone Photography] (Kumano City) | Tourism Mie | Mie Prefecture Travel Information', description = 'Shichiri Mihama, also known as the ''Hama Kaido'' of the World Heritage Kumano Kodo, has been captured through drone photography. This beautiful pebble beach stretches approximately 22 km from Kumano City to Kiho Town, making it the longest shingle beach in Japan. It has been selected as one of Japan''s ''100 Best Beaches'' and ''100 Natural Sites to Preserve for the 21st Century,'' alongside other scenic spots nationwide. The beach, which gracefully embraces the rough waves of the Kuroshio Current, is adorned with smooth, round pebbles polished by the turbulent waters of Kumano Bay.' where id = 'PO8zSln85JX3aXaeuTxWR';
update content_bodies set title = '「お試しステイ」詳細は概要欄から！ #北広島町', description = '「北広島町お試しステイ」は、北広島町に移住を考える人々に向けた制度です。対象施設に宿泊し、1人1泊あたり2,000円（最大10泊まで）の宿泊クーポンが支給され、滞在費用を支援します。この制度を利用することで、短期間ではわからない北広島町での生活を体験できます。特に、BlueArtGuesthouseは、モロッコのシャウエンからインスピレーションを受けた青を基調としたゲストハウスで、アートが飾られた空間や広々とした畳ルームが魅力です。井上さんご夫婦の温かいおもてなしの中で、地域の人々との交流も楽しめます。北広島町での「お試しで」の暮らしを体験してみませんか？' where id = 'XEmIKZ9yPg7KC5uMN6tbv';
update content_bodies set title = 'Trial Stay Details Available! #KitaHiroshimaTown', description = 'The ''Trial Stay'' program in Kita Hiroshima Town offers a unique opportunity for those considering moving to the area. Participants can stay at designated facilities and receive a lodging coupon of 2,000 yen per night (up to 10 nights) to help cover accommodation costs while experiencing life in Kita Hiroshima Town. This initiative allows potential residents to understand the local lifestyle better. One of the featured accommodations is BlueArtGuesthouse, inspired by the owner''s travels in Morocco. The guesthouse features a calming blue theme, art by the family, and a spacious tatami room. Guests can also engage in activities like painting and plastering if desired. The friendly hosts, the Inoue couple, provide a welcoming atmosphere, fostering connections with the local community. Explore the possibility of living in Kita Hiroshima Town through the ''Trial Stay'' program!' where id = 'jwFZFB-noTk7SmSZS1Gaz';
update content_bodies set title = '木こりが営む「木こり体験の宿」へ観光協会職員がレッツらモー‼️', description = '広島県北広島町にある「太田屋」は、薪を使った昭和レトロな体験ができる宿です。宿泊プランは多様で、山や林業について学ぶ体験やチェーンソーの見学、安全講習が含まれています。宿泊者は自ら薪を使ってお湯を沸かし、田舎暮らしの懐かしさを体感できます。観光協会職員が初めて薪割りとチェーンソーを体験し、薪割りの成功に拍手が起こりました。五右衛門風呂や手間をかけたご飯は、心に染みる美味しさです。宿主の大内さんと新中さんは、林業の現状を伝えたいという熱い思いを持っています。「太田屋」は、森や木の恵みに感謝し、人の原点に帰れる宿です。ぜひ訪れてみてください。' where id = 'cZbBVLcZfgPJNWiScyBuE';
update content_bodies set title = 'Experience the Lumberjack''s Lodge in Kitahiroshima Town', description = 'The ''Lumberjack Experience Lodge'' in Kitahiroshima Town, Hiroshima Prefecture, offers a unique retro experience using firewood. The lodge, ''Ohtaya,'' provides various accommodation plans, including hands-on learning about forestry and chainsaw demonstrations. Guests can enjoy cooking and bathing with firewood, allowing them to appreciate the simplicity and value of traditional living. A staff member from the tourism association experienced wood splitting and chainsaw use for the first time, feeling proud of their skills. The lodge offers a nostalgic rural lifestyle, with a beautiful starry sky and delicious meals cooked over a fire. The hosts, Mr. Ouchi and Mr. Niinaka, passionately share their knowledge about forestry and the importance of nature. ''Ohtaya'' is a place to return to the roots of humanity, offering both learning and relaxation. Visit ''Ohtaya Kicori'' online for more information.' where id = 'CftplqBHkDutvqASXy87i';
update content_bodies set title = '北広島町の夏の風物詩『八重管絃祭』が7/26(土)に開催されました🎉', description = '北広島町の夏の風物詩『八重管絃祭』が7月26日に開催されました。有田、十日市、新地の各会場は賑わい、屋台が並び、浴衣姿の子供たちが楽しんでいました。観光協会の職員は新地会場の司会を担当し、他の会場には行けませんでしたが、皆の楽しそうな様子が伝わってきました。ステージでは歌やダンス、バンド、落語が披露され、特に子供たちが緊張しながらも楽しそうにステージに向かう姿が印象的でした。歌う介護士の森光雅志さん、脇田直弥さん、愛里さんのパフォーマンスも素晴らしく、会場を盛り上げました。八重管弦祭の目玉である「陸船」は、その迫力と美しさに感動を覚えます。北広島町の夏の一大イベントをぜひ来年は直接体験してみてください！' where id = 'lB9nAGai6hMZ2XVS4RcZE';
update content_bodies set title = 'The Summer Tradition of Kitahiroshima Town: The Yaegakugen Festival Held on July 26th 🎉', description = 'The Yaegakugen Festival, a summer tradition in Kitahiroshima Town, took place on July 26th. The event was bustling at all venues, including Arita, Tokkaichi, and Shinchi, with numerous food stalls and children in yukatas enjoying the festivities. Although the tourism association staff member was the MC at the Shinchi venue and couldn''t visit the other locations, the lively atmosphere and joyful smiles were palpable. Performers showcased their talents through singing, dancing, bands, and even rakugo. The sight of children nervously yet excitedly heading to the stage was a special privilege for the MC. Notable performances included those by singer caregivers Mori Mitsukazu, Waki Ta Naoya, and Ai Ri, whose captivating voices filled all three venues. The highlight of the festival, the ''Okabune'' (land boat), was impressive and vibrant, moving gracefully on the waves. This major summer event in Kitahiroshima Town is a must-see, and those interested should definitely attend next year!' where id = 'iXxyEv8DzJLxffeyVduwy';
update content_bodies set title = '東京ディズニーランド ハロウィンフードツアー 2024！', description = '2024年の東京ディズニーランドでのハロウィンフードとドリンクを試食するツアーに参加しましょう！Great American Waffle Co.のハロウィンミッキーワッフルや、La Taverne de Gastonの特製ベリードリンク、Grandma Sara’s Kitchenのオムライスとミートボールなど、さまざまなハロウィンテーマの料理を楽しみます。また、Rackety’s Raccoon Saloonのハロウィンパンプキンサンデーや、Refreshment Cornerのスイートチリホットドッグも味わいます。さらに、アップルティーソーダで一息入れ、Eastside Cafeのグリルビーフスペシャルセットも堪能します。最後には、新しいナイトタイムキャッスルプロジェクションショー「Reach for the Stars」を観賞します。この動画は、東京ディズニーランドのハロウィンイベントを楽しみたい方に最適です。' where id = 'm5qkrxATEdBQ3La1wQf32';
update content_bodies set title = 'Tokyo Disneyland Halloween Food Tour 2024!', description = 'Join me on a culinary adventure at Tokyo Disneyland as I sample all the Halloween-themed food and drinks for 2024. The tour includes a variety of festive treats, such as the Halloween Mickey Waffle from Great American Waffle Co., a special berry drink from La Taverne de Gaston, and an omelet over rice with meatballs from Grandma Sara’s Kitchen. I also indulge in a Halloween Pumpkin Sundae at Rackety’s Raccoon Saloon and a sweet chili hot dog at Refreshment Corner. Additionally, I take a break with an apple tea soda and enjoy a grilled beef special set at Eastside Cafe. The experience culminates with a visit to the new night-time castle projection show, ''Reach for the Stars.'' This video is perfect for anyone looking to explore the Halloween festivities at Tokyo Disneyland.' where id = 'Z1rSWws-2QKN5bEOKOp57';
update content_bodies set title = '広島・瀬戸内・世界の未来をつなぐ共創拠点『miobyDoTS』', description = '『miobyDoTS（ミオバイドッツ）』は、広島市南区のミナモア西棟3Fに位置する共創拠点で、「贈ろう、瀬戸内」をテーマにした常設ショップです。地域の特産品や雑貨を販売し、講座やワークショップ、イベントも開催しています。レストランでは瀬戸内の食材を使った料理が楽しめ、カフェでは「サゴタニ牧場」の牛乳を使った濃厚ジェラートが人気です。北広島町観光協会は、地域の伝統芸能「神楽」のお面やキャラクターのぬいぐるみを展示し、QRコードでSNSも紹介しています。この棚は地域の特産品やおすすめ店、祭りなどを知ることができる情報の場で、他の市町の魅力的な展示もあります。『miobyDoTS』で北広島町の魅力をぜひ探してみてください。' where id = 'zZPpXyORofuNpjrqCeDnj';
update content_bodies set title = 'Connecting the Future of Hiroshima, Setouchi, and the World at ''miobyDoTS''', description = '''miobyDoTS'' is a co-creation hub located on the 3rd floor of Minamoa West Building, themed ''Let''s Gift Setouchi''. It features a permanent shop selling local specialties and various goods, alongside a range of courses, workshops, and events. The hub also includes a casual bistro offering diverse dishes made from rich Setouchi ingredients and a cozy café famous for its rich gelato made from ''Sagotani Farm'' milk. The North Hiroshima Town Tourism Association has set up a display showcasing local traditional arts, including ''Kagura'' masks and plush toys of the character Hanada Maitaro, complete with QR codes linking to their social media. This display serves as a vibrant information hub about local specialties, recommended shops, key figures, and festivals, making it a great opportunity for promoting North Hiroshima Town. Visitors are encouraged to explore the unique offerings of ''miobyDoTS''.' where id = 'EB4EQxj0eW_0KLj21V9u-';
update content_bodies set title = '初心者さんにもおすすめ！大自然を満喫できる釣り堀🎣【大暮養魚場】', description = '大暮養魚場は、北広島町に位置し、自然豊かな環境で釣りを楽しむことができる場所です。アマゴ、ヤマメ、ニジマスを育てる清らかな水が流れています。利用プランは、1時間4,000円で釣り放題の時間制限プランと、釣った魚を量り売りで購入するプランがあります。また、掴み取りやBBQなどのアクティビティも充実しています。釣りを楽しんだ後は、焼き魚や唐揚げを味わうことができ、特に外で食べるのが格別です。釣り堀のシーズンは3月中旬から積雪が始まるまでです。詳しくは大暮養魚場のHPやInstagramをご覧ください。' where id = 'VpAFgk3fWBjdB9w51T18F';
update content_bodies set title = 'Recommended for Beginners! Enjoy Nature at Ogure Fish Farm 🎣', description = 'Ogure Fish Farm, located in Kitahiroshima Town, offers a unique fishing experience in a beautiful natural setting. The farm raises amago, yamame, and rainbow trout in the clear waters flowing from the surrounding mountains. There are two fishing plans available: a time-limited all-you-can-fish plan for 4,000 yen per hour, which includes one rod and bait, and a pay-per-weight plan where you can buy the fish you catch. The farm also offers fun activities like fish catching and BBQ. Visitors can enjoy the thrill of fishing and the delicious taste of grilled or fried fish after a day of fun. The fishing season runs from mid-March until the first snowfall. For more details, visit Ogure Fish Farm''s website or Instagram.' where id = 'O5YOyBR3bgcFix-4IJhtG';
update content_bodies set title = '新商品ができたと聞いて大朝にある漬物屋「西漬」さんに観光協会職員がレッツらもー‼️', description = '大朝にある漬物屋「西漬」は1950年に創業し、広島で3代続く伝統的な漬物屋です。約30年前に新しい工場地と美味しい水を求めて大朝に移転しました。「地域と共に栄える」をミッションに掲げ、地元食材を活用した新商品「北の舞漬」を開発しました。この漬物は、1年以上の古漬け技法を用い、牡蠣エキスで甘さを引き出し、誰でも食べやすい味に仕上げています。シャキシャキとした食感と酸味のコク、ほんのり甘い味わいが特徴で、広島菜の香りが楽しめます。代表の西村さんは、日本の漬物文化を守り、未来へと受け継いでいきたいと語っています。「北の舞漬」は、時間と作り手の想いが込められた一品です。現在、道の駅舞ロードIC千代田と大朝のわさ〜る産直館で購入可能で、2025年にはお歳暮商品として販売予定です。' where id = 'FlaVfB7B9knm0VU9khSmC';
update content_bodies set title = 'New Product Launch at Nishizuke Pickles in Oasa', description = 'Nishizuke, a pickles shop established in 1950 in Oasa, Hiroshima, has launched a new product. The shop, which has been run by three generations, moved to Oasa about 30 years ago in search of a new factory site and delicious water. Their mission is to thrive with the community by developing products using local ingredients. The new product, ''Kita no Mai-zuke,'' is made using a unique method with Hiroshima vegetables, employing a year-long pickling technique that incorporates oyster extract for sweetness, making it easy to eat and perfect with rice or as a snack with alcohol. The pickles have a crunchy texture, rich acidity, and a hint of sweetness, with a fragrant aroma of Hiroshima vegetables. Nishizuke''s representative, Mr. Nishimura, expressed his desire to preserve and enhance the cultural value of Japanese pickles for future generations. The ''Kita no Mai-zuke'' reflects the time and care of its makers. It can currently be purchased at the Michi-no-Eki Mai Road IC Chiyoda and the Oasa Wasaru Direct Sales Center, with plans for seasonal sales in 2025.' where id = 'IoAiNupo2mFDgm0u2nySc';
update content_bodies set title = '高田本山 新宝物館「燈炬殿」がオープン！360度に映し出される大迫力VRシアターは必見', description = '2023年5月、三重県津市にある高田本山専修寺に新宝物館「燈炬殿」がオープンしました。この博物館では貴重な宝物の展示に加え、360度のVRシアターで迫力ある映像を楽しむことができます。見所が多く、観光スポットとして注目されています。アクセス情報には、博物館の住所、連絡先、営業時間が含まれており、入館料は一般1,000円、中高生500円、小学生以下は無料です。伊勢自動車道津ICから約15分、JR一身田駅から徒歩5分の便利な立地です。' where id = 'jfe9WJwarupMBS_l8Tr_E';
update content_bodies set title = 'Takada Honsan New Treasure Museum ''Tōkoden'' Opens! A Must-See 360-Degree VR Theater', description = 'In May 2023, the new treasure museum ''Tōkoden'' opened at the Senjuji Temple in Tsu City, Mie Prefecture. The museum features valuable exhibits and a stunning 360-degree VR theater that offers an immersive viewing experience. Visitors can enjoy a variety of attractions, making it a noteworthy destination. Access information includes the museum''s address, contact number, and operating hours, with admission fees set at 1,000 yen for adults, 500 yen for middle and high school students, and free for elementary school children. The museum is conveniently located about 15 minutes from the Ise Expressway Tsu IC and a 5-minute walk from JR Ichinada Station.' where id = 'HY0ClSu9cK0jEUQwfzSsT';
update content_bodies set title = '伊賀の里モクモク手づくりファーム　いちご摘み体験教室', description = '三重県伊賀市に位置する伊賀の里モクモク手づくりファームでは、4月30日までいちご摘み体験が楽しめます。この時期ならではの体験として、いちご大福づくり教室やいちごを使ったお菓子づくり教室も開催されています。大阪や京都から近い人気の農業公園で、ランチバイキングや乳搾り、ウィンナー作りなど多彩なアクティビティも体験できます。' where id = '9cEeUybdR3intK1QBl1qt';
update content_bodies set title = 'Iga no Sato Mokumoku Handmade Farm Strawberry Picking Experience', description = 'At the Iga no Sato Mokumoku Handmade Farm in Iga City, Mie Prefecture, visitors can enjoy strawberry picking until April 30. Additionally, there are seasonal experiences such as making strawberry daifuku and other sweets using strawberries. The farm is a popular agricultural park close to Osaka and Kyoto, offering various activities including lunch buffets, milking cows, and sausage making.' where id = 'aZQG0pCAvReuLlZA_1X2w';
update content_bodies set title = '【絶景茨城】つつじ［4K］茨城県笠間市｜VISIT IBARAKI, JAPAN', description = '2015年4月27日、笠間つつじ公園では約8500株のつつじが咲き誇り、青い空、緑の山、赤いつつじが織りなす春の絶景が広がります。「笠間つつじまつり」では、野点茶会やお囃子の演奏などのイベントが行われ、多くの観光客で賑わいます。' where id = '5E7IO0RCxTzLqIiz7etfM';
update content_bodies set title = 'Stunning Ibaraki: Tsutsuji [4K] Kasama City, Ibaraki Prefecture | VISIT IBARAKI, JAPAN', description = 'On April 27, 2015, approximately 8,500 azaleas bloom in Kasama Tsutsuji Park, creating a breathtaking spring landscape with the blue sky, green mountains, and red azaleas. The ''Kasama Tsutsuji Festival'' features events such as outdoor tea ceremonies and traditional music performances, attracting many tourists.' where id = 'GMsHqdTV6Ui4Cw9hPb2NS';
update content_bodies set title = '【絶景茨城】桜［4K］茨城県日立市｜VISIT IBARAKI, JAPAN', description = '2015年4月6日に撮影されたこの映像は、茨城県日立市のかみね公園と日立駅前の平和通りに咲く桜を紹介しています。これらの場所は日本のさくら名所百選にも選ばれています。海と山の間を吹き抜ける風に揺れる美しい桜は、地元の人々の生活に彩りを添え、茨城県内外からの観光客を惹きつけて街を賑やかにします。毎年春には日立さくらまつりが開催され、ユネスコ無形文化遺産に登録された「日立風流物」が桜の景色に迫力を与えます。' where id = 'WGB23h2ZQG35JVIBktyXM';
update content_bodies set title = 'Stunning Ibaraki: Cherry Blossoms [4K] Hitachi City, Ibaraki Prefecture | VISIT IBARAKI, JAPAN', description = 'Filmed on April 6, 2015, this video showcases the cherry blossoms at Kamine Park and Heiwa Street in front of Hitachi Station, both of which are selected as one of Japan''s top 100 cherry blossom spots. The beautiful cherry blossoms sway in the breeze between the sea and mountains, adding color to the lives of the local residents and attracting tourists from both within and outside Ibaraki Prefecture, enlivening the city. Every spring, the Hitachi Cherry Blossom Festival is held, featuring the ''Hitachi Furyumono,'' a UNESCO Intangible Cultural Heritage, which adds a dramatic touch to the cherry blossom scenery.' where id = 'EFqNaWCuGv484ZHQ7vfUF';
update content_bodies set title = '大朝の方々の温かさが生んだ「エコマーケット」に観光協会職員がレッツら モー‼️', description = 'エコマーケットは、北広島町の大朝地域で地域おこしをしている有志グループ「100プロ」の活動の一環です。「100プロ」は、地域の子どもが減少することに危機感を抱き、2018年に活動を開始しました。10年後に児童数を100人にすることを目指し、様々なプロジェクトに取り組んでいます。エコマーケットは、女子会プロジェクトの一部であり、地元の人々や移住者が交流する場を提供しています。住職の上原さんは「人と人との繋がり」の重要性を語り、イベントは賑やかに進行しました。次回のエコマーケットは12月6日・7日、フリー女子会は9月7日に開催されます。地域のつながりを作るきっかけとして、ぜひ参加してください。' where id = 'gcXckrk16hDqSODB48XP1';
update content_bodies set title = 'The Warmth of the People of Oasa Creates the ''Eco Market'' with the Help of Tourism Association Staff!', description = 'The Eco Market is one of the initiatives by the volunteer group ''100 Pro'' aimed at revitalizing the Oasa region in Kitahiroshima Town. Established in 2018, ''100 Pro'' was formed in response to the declining number of children in the area, with a goal of increasing the number of children to 100 in ten years through various projects. The Eco Market, along with the upcoming Free Women''s Meeting in September, is part of the ''Women''s Group Project'' aimed at fostering connections among locals and newcomers. The event emphasizes the importance of community ties, as highlighted by the temple''s priest, Uehara. Initially focused on children''s items, the Eco Market has grown significantly, featuring a variety of goods, including beer taps and cute clothing. The next Eco Market is scheduled for December 6-7, and the Free Women''s Meeting will be on September 7. Everyone is encouraged to participate and help build community connections.' where id = 'anC6kPRmP3DgY6aYrV9O4';
update content_bodies set title = '知る人ぞ知るハーブの楽園✨️北広島町大朝にある「天意の里ハーブガーデン」', description = '天意の里ハーブガーデンは、大朝ICから車で約10分の場所にあり、約4万㎡の敷地に100種類以上のハーブが植えられています。ハーブ園、自然食レストラン、カフェ、クラフト教室があり、まるでジブリの世界に迷い込んだような雰囲気です。5月下旬から6月下旬にはジャーマンカモミールの摘み取りが楽しめ、心地良い風に吹かれながらその香りを堪能できます。可愛らしい花々に囲まれたハーブランチは絶品で、自家製のハーブ塩が天ぷらにぴったりです。看板犬のリュウくんも可愛らしく、訪れる人々を和ませます。多くの人が写真を撮り、ドレスを着た犬もポーズを決めています。非日常的なハーブガーデンで、ぜひ癒やされに来てください。' where id = 'dTFacI4wXPese_DgUtVoa';
update content_bodies set title = 'A Hidden Herb Paradise: Aino Sato Herb Garden in Kitahiroshima Town', description = 'The Aino Sato Herb Garden, located about 10 minutes by car from the Oasa IC in Kitahiroshima Town, spans approximately 40,000 square meters and features over 100 varieties of herbs. The garden includes a herb shop, a natural food restaurant, a café, and craft workshops, creating an enchanting atmosphere reminiscent of a Studio Ghibli film. From late May to late June, visitors can enjoy picking German chamomile while savoring its delightful fragrance in the gentle breeze. The herb lunch, surrounded by beautiful flowers and herbs, is exceptional, especially with homemade herb salt that pairs perfectly with tempura. Visitors can also enjoy herbal tea and continue picking herbs. The garden is home to a friendly dog named Ryu, who loves to roll around, adding to the charm of the place. Many guests take photos, including dogs dressed in costumes. The garden offers a unique escape, inviting everyone to come and relax.' where id = 'QEYPNW1J8khdjF59DAzq0';
update content_bodies set title = '壬生の花田植に向けた練習風景', description = '6月1日(日)に行われる壬生の花田植に向けて、壬生田楽団と川東田楽団のメンバーが日々練習を重ねています。この時期、カエルの合唱が響く中、笛の音が聞こえてきます。田楽団は週に2回、夜に集まって練習を行っています。壬生田楽団は45名の登録団員がいて、当日は41名が出演予定です。川東田楽団は30名の団員がいて、23名が参加します。新しい団員への指導も熱心に行われており、「田植歌を覚えるのは大変ですが、皆さん優しくて頑張れます！」と笑顔で話していました。北広島町の誇る「花田植」に向けて、今夜も心地よい田囃子が千代田の夜に響いています。' where id = 'Qzm-_ASiVBWwknPsceU0c';
update content_bodies set title = 'Rehearsal for the Mibu Flower Rice Planting Festival', description = 'On June 1st, the Mibu Flower Rice Planting Festival will take place, and members of the Mibu and Kawahigashi Dancer Troupes are practicing daily in preparation. During this time of year, the chorus of frogs fills the air, accompanied by the sound of flutes. The troupes gather twice a week in the evenings for their rehearsals. The Mibu Dancer Troupe has 45 registered members, with 41 expected to perform on the day of the event. The Kawahigashi Dancer Troupe consists of 30 members, with 23 set to participate. There is a strong focus on training new members, who expressed their challenges in learning the rice planting songs but are motivated by the support of their peers. As the festival approaches, the pleasant sounds of traditional music resonate through the night in Chiyoda, showcasing the pride of Kitahiroshima Town.' where id = 'sN4HRDTM4tT9J_eNzkOC_';
update content_bodies set title = '【絶景茨城】桜［4K］茨城県つくばみらい市｜VISIT IBARAKI, JAPAN', description = '2015年4月2日、つくばみらい市には関東三大堰の一つ「福岡堰」があり、桜の名所として知られています。毎年開催される「福岡堰さくらまつり」では、約600本の桜が1.8kmの遊歩道沿いに咲き誇り、桜のトンネルを楽しむことができます。また、市民の憩いの場であるきらくやまふれあいの丘では、春になると施設入口前の桜並木が美しい姿を見せます。茨城の観光地についてもっと知りたい方は、http://www.ibakira.tv/archive/visitibaraki/をご覧ください。' where id = 'fVLcMb6UhXyq6yQL2oe17';
update content_bodies set title = 'Stunning Ibaraki: Cherry Blossoms [4K] Tsukuba Mirai City | VISIT IBARAKI, JAPAN', description = 'On April 2, 2015, Tsukuba Mirai City is home to one of the Kanto region''s three major weirs, the Fukuoka Weir, which is famous for its cherry blossoms. The annual ''Fukuoka Weir Cherry Blossom Festival'' is held here, showcasing approximately 600 cherry trees along a 1.8 km promenade, creating a beautiful cherry blossom tunnel. Additionally, Kirakuyama Fureai Hill, a popular relaxation spot for locals, features a stunning cherry blossom corridor at the entrance during spring. For more information on Ibaraki''s tourist attractions, visit http://www.ibakira.tv/archive/visitibaraki/' where id = 'q9n0K_9CGEzQqzvam3ZkD';
update content_bodies set title = '職員が早乙女に挑戦！国の重要無形民族文化財「新庄のはやし田」', description = '5月11日、国の重要無形民族文化財である「新庄のはやし田」イベントが新庄郷土芸術保存会によって開催されました。力強い南条おどりや介護士の森光雅志さんのライブが行われ、参加者は盛り上がりました。観光協会の職員も早乙女として田植えに挑戦し、小学生の女の子たちからの応援を受けながら、田んぼに足を踏み入れました。苗を植える中で、地域の伝統の大切さを再認識し、休憩中には「朴葉むすび」を皆で楽しみました。この貴重な体験を通じて、地域の伝統が受け継がれることの重要性を感じました。来年もぜひ参加して、伝統を繋ぎましょう！' where id = 'd_gezkbZrj6NAcVaebtyJ';
update content_bodies set title = 'Staff Challenges to Become Rice Planters at the Important Intangible Folk Cultural Asset ''Shinjō''s Hayashida''', description = 'On May 11, the ''Shinjō''s Hayashida'' event, recognized as an Important Intangible Folk Cultural Asset, was held by the Shinjō Local Arts Preservation Society. The event featured a powerful performance of the Nanjō dance and a live singing performance by caregiver Masashi Morimitsu. Staff from the tourism association participated as rice planters, excitedly preparing in the dressing room. Young girls encouraged them, creating a supportive atmosphere. As they entered the rice field, they experienced the challenges of planting while receiving advice from experienced planters. During a break, they enjoyed ''bamboo leaf rice balls'' together. The event highlighted the importance of preserving local traditions and the joy of community participation. The organizers invite everyone to join next year, emphasizing the need for prior registration.' where id = 'iT0NQJRLPMnmffwv-Mawe';
update content_bodies set title = 'タイムスリップ！？【日本でここだけ】戦国時代の蒸し風呂体験♨が出来る「万徳院跡歴史公園」に観光協会職員が行ってきました✨️', description = '北広島町にある「万徳院跡歴史公園」では、戦国時代の蒸し風呂体験ができます。この公園は、毛利元就の孫・吉川元長が建立した寺院の跡地に位置し、歴史的な背景を持っています。職員は、戦国の庭歴史館の佐々木さんに案内され、薪を割って火を起こす体験をしました。蒸し風呂は大人4人が入れる広さで、温度は45度。ひのきの香りとともに、心地よい蒸気が漂います。職員は「ゆかたびら」という白装束を着用し、450年前の元長も同様に蒸し風呂を楽しんでいたのではないかと想像しながら体験しました。公園内にはガイダンスホールもあり、展示や休憩スペースがあります。蒸し風呂体験は、3月から11月の第3日曜日に無料で行われており、歴史好きにはぜひ訪れてほしいスポットです。' where id = '-wBvwFuzspBCrtFmgJCCo';
update content_bodies set title = 'Time Slip!? Experience a Sengoku Era Steam Bath at ''Mantokuin Ruins Historical Park'' in Japan', description = 'In Kitahiroshima Town, known for its historical significance during the medieval period, the ''Mantokuin Ruins Historical Park'' offers a unique steam bath experience reminiscent of the Sengoku era. The park, established on the site of a temple built by Yoshikawa Motonaga, a grandson of Mouri Motonari, allows visitors to engage in traditional steam bathing. Guided by Sasaki from the Sengoku Garden History Museum, participants start by splitting wood and lighting a fire, an experience that feels cinematic. The steam bath accommodates four adults and reaches a temperature of 45 degrees Celsius, filled with mild steam and the scent of hinoki wood. Visitors can wear traditional white garments called ''yukata-bira'' or their own clothes. The experience evokes thoughts of how Motonaga might have enjoyed similar baths 450 years ago. The park also features a guidance hall that replicates the main hall''s size, providing exhibits and rest areas. The steam bath experience is available for free on the third Sunday of each month from March to November, making it a must-try for history enthusiasts.' where id = '4cqggJGvWO6z72zjqNSRO';
update content_bodies set title = '【絶景茨城】常陸秋そば ［4K］茨城県常陸太田市', description = '「常陸秋そば」は、茨城県が誇るブランド品種で、香りと味わいに優れ、通をも唸らせる逸品です。1978年に旧・金砂郷町（現在の常陸太田市）の在来種から高品質な品種が選抜され、育成されました。その後、県内各地で栽培されるようになり、常陸太田市、常陸大宮市、稲敷市、土浦市、筑西市、結城市、下妻市などが主な産地となっています。また、各地で「そばまつり」も開催され、常陸秋そばは秋の茨城の風物詩となっています。' where id = 'MVD_Icozc1qrqaTjl2JwE';
update content_bodies set title = 'Spectacular Ibaraki: Hitachi Aki Soba [4K] | Hitachiota City, Ibaraki Prefecture', description = 'Hitachi Aki Soba is a prestigious brand variety from Ibaraki, renowned for its exceptional aroma and flavor that impress even connoisseurs. It was developed in 1978 from local strains in the former Kinasagō Town (now Hitachiota City) by selecting high-quality varieties. Since then, it has been cultivated in various regions of the prefecture, with major production areas including Hitachiota City, Hitachiōmiya City, Inashiki City, Tsuchiura City, Chikusei City, Yūki City, and Shimotsuma City. Additionally, soba festivals are held in various locations, making Hitachi Aki Soba a seasonal highlight of autumn in Ibaraki.' where id = 'PCI3ejbl_H4kFvXaHbztR';
update content_bodies set title = 'コキアの絶景', description = '国営ひたち海浜公園の「みはらしの丘」にあるコキアは、夏から秋にかけて色を変えます。この映像では、その変化を様々な角度から捉え、じっくりと楽しむことができます。自然の美しさを長尺映像で堪能してください。' where id = 'nz7v8n8Us4rTYQy-1jBdM';
update content_bodies set title = 'Kochia Colors at Hitachi Seaside Park', description = 'The kochia at Hitachi Seaside Park''s ''Miharashi Hill'' transforms its colors from summer to autumn. This video captures the changing scenery from various angles, allowing viewers to appreciate the beauty of this natural phenomenon in a long-format presentation.' where id = 'ytSkOahiVi_bWs5yr_BDE';
update content_bodies set title = '魚飛渓【ドローン撮影】(紀北町)｜観光三重｜三重県の観光・旅行情報', description = '魚飛渓は、数々の巨岩や奇岩が織りなす美しい渓谷で、多くの魚が飛び交う光景が楽しめます。「銚子川ブルー」と称される澄んだ流れの中で、魚が泳ぐ姿や川の底までくっきりと見える様子は圧巻です。この銚子川は「天然の水族館」や「奇跡の清流」とも呼ばれ、国内有数の透明度を誇り、アユやアマゴ、テナガエビなどの豊富な生物が生息しています。' where id = '5BXnn6fNeifVRbsqepXF3';
update content_bodies set title = 'Hiryu Valley [Drone Photography] (Kihoku Town) | Tourism Mie | Mie Prefecture Travel Information', description = 'Hiryu Valley is a stunning gorge characterized by numerous giant and bizarre rocks, where many fish can be seen leaping through the air. The clear waters known as ''Choshi River Blue'' allow for a view of the fish swimming, with the riverbed visible below. Often referred to as a ''natural aquarium'' and a ''miraculous clear stream,'' the Choshi River boasts one of the highest levels of transparency in Japan, making it a treasure trove for Ayu, Amago, and freshwater shrimp.' where id = 'f5UupYnxuDvCrVoSiOhow';
update content_bodies set title = '全身で大自然を体感！奥伊勢アウトドア旅【大台町】', description = 'この動画では、奥伊勢でのアウトドア旅を紹介しており、全身で大自然を体感できる様子が描かれています。大台町の美しい自然環境の中で、様々なアクティビティを楽しむことができる内容となっています。' where id = 'FvFd2nuu21w1YMlE_F6g3';
update content_bodies set title = 'Experience Nature Fully! Outdoor Trip in Oku-Ise, Odaichō', description = 'This video introduces an outdoor trip in Oku-Ise where you can fully experience the great outdoors.' where id = '2pjcqtvqMEisuzuBF4Pxa';
update content_bodies set title = '【絶景茨城】茨城の紅葉｜VISIT IBARAKI,JAPAN', description = '茨城県の紅葉の名所を空撮を交えて紹介します。筑波山は1000種以上の珍しい植物が群生し、登山やハイキングが楽しめる自然の宝庫です。花貫渓谷では、汐見滝吊り橋からの眺めが素晴らしく、清流や紅葉を楽しめます。花園渓谷は花園神社の近くにあり、秋には色づいた紅葉が花園川に舞い落ち、美しい風景を作ります。竜神大吊橋は高さ100m、長さ375mの国内最大級の歩行者専用橋で、四季折々のパノラマが広がります。袋田の滝は日本三名瀑の一つで、四段に落下し、四季ごとに訪れることでその美しさがわかる「四度の滝」とも呼ばれています。' where id = 'bG2p3IKrNGvItsqm2aU3B';
update content_bodies set title = 'Stunning Ibaraki: Autumn Foliage in Ibaraki | VISIT IBARAKI, JAPAN', description = 'This article introduces the famous autumn foliage spots in Ibaraki Prefecture, featuring aerial shots. Mount Tsukuba is a treasure trove of over 1,000 rare plant species, offering year-round opportunities for hiking and enjoying nature. The Hanakuni Valley provides breathtaking views from the Shioimi Falls suspension bridge, where visitors can enjoy the clear stream and vibrant autumn leaves along the river. The Hanazono Valley, designated as part of the Hanazono Hanakuni Prefectural Natural Park, showcases beautiful fall colors as leaves fall into the Hanazono River. The Ryujin Big Suspension Bridge, standing 100 meters above the Ryujin Dam lake, is one of the longest pedestrian bridges in Japan at 375 meters, offering panoramic views throughout the seasons. Fukuroda Falls, one of Japan''s three famous waterfalls, is known for its four-tiered drop and is best appreciated by visiting each season, earning it the nickname ''Four Times Falls.''' where id = 'vKIIRgwPjHK85bZR_lklR';
update content_bodies set title = '【絶景茨城】袋田の滝（紅葉）｜VISIT IBARAKI,JAPAN', description = '袋田の滝は久慈川の支流である滝川にかかる滝で、日本三大名瀑の一つに数えられています。高さ120メートル、幅73メートルの大きさを誇り、その壮大な景観は訪れる人々を魅了します。この動画では「渓流散策コース」が紹介されており、コースの詳細は現地で入手できるパンフレットで確認できます。' where id = 'xEspW_P_2i-6wO_YEVjz8';
update content_bodies set title = 'Fukuroda Falls (Autumn Foliage) | VISIT IBARAKI, JAPAN', description = 'Fukuroda Falls, located on the Takigawa River, a tributary of the Kuji River, is one of Japan''s three great waterfalls. It boasts a height of 120 meters and a width of 73 meters. The video introduces a ''stream walking course,'' and detailed information about the course can be found in brochures available on-site.' where id = 'LImcE1XpPvBY6_DcMsWU8';
update content_bodies set title = '長崎ばーどアイ　火張山公園の桜　前編', description = '島原市に位置する火張山公園は、花の名所として知られています。かつて火砕流の被災地であったこの場所には、復興の象徴とも言える一本の桜があり、菜の花との共演が美しい景観を作り出しています。' where id = 'ElG2bb88qGlTDoY23IyXA';
update content_bodies set title = 'Nagasaki Bird Eye: Cherry Blossoms at Hibariyama Park - Part 1', description = 'Hibariyama Park, located in Shimabara City, is a renowned flower spot. It was once an area affected by volcanic pyroclastic flows. The park features a single cherry blossom tree that stands as a symbol of recovery, beautifully complemented by fields of rapeseed flowers.' where id = 'kWXXWc6nsYO5HIL6OYQmc';
update content_bodies set title = '花田舞太郎くんの誕生日フェア開催！！', description = '北広島町のイメージキャラクター、花田舞太郎くんの誕生日フェアが2月2日に道の駅舞ロードで開催されました。前日に雪が降り、ホワイトバースデーフェアとなりました。レストラン響では誕生日限定のケーキが並び、抽選会や誕生日セレモニーも行われました。参加者は「ハッピーバースデー」を歌い、千代田高校の生徒がクラッカーを鳴らしました。セレモニーの最後にはみんなでダンスを楽しみました。グルメには、キッチンカーTSURUYAの「どぶろくバーガー」や「やきにくライスバーガー」、ゆず庵の「どぶろく鍋」の無料試食会があり、生徒たちは美味しそうに食べていました。また、観光大使の月山翔雲さんもお祝いに駆けつけ、会場を盛り上げました。花田舞太郎くん、お誕生日おめでとう！北広島町の魅力を発信し続けてください。道の駅舞ロードIC千代田にもぜひ遊びに来てください。' where id = '4eeUNzFU6C_7KpFYzCFKw';
update content_bodies set title = 'Birthday Fair for Hanada Maitaro-kun!', description = 'The birthday fair for Hanada Maitaro-kun, the mascot of Kitahiroshima Town, was held on February 2nd at the Mair Road Station. The event took place amidst a snowy backdrop, creating a festive White Birthday Fair atmosphere. The restaurant Hibiki featured a special birthday cake, and there were fun lottery draws and a birthday ceremony where attendees sang ''Happy Birthday'' and celebrated with crackers provided by students from Chiyoda High School. The ceremony concluded with a dance that included guests. Gourmet offerings included ''Doburoku Burgers'' and ''Yakiniku Rice Burgers'' from the TSURUYA food truck, as well as a free tasting of ''Doburoku Nabe'' by Yuzuan. The students enjoyed the delicious food, and the atmosphere was warm and cheerful. Additionally, the town''s tourism ambassador, Gassan Shoun, attended to add to the celebration. Happy birthday to Hanada Maitaro-kun, who is loved for his round shape and lively dance! Visitors are encouraged to come to Mair Road Station for shopping and dining.' where id = '0HGg3gXGvOZXMkLMA_sYc';
update content_bodies set title = '伊勢志摩リゾートステイ', description = '伊勢志摩は、複雑に入り組んだ半島が作り出すリアス海岸の美しさや、大小の島々、豊富な海の幸に恵まれています。宿でゆったりと過ごすのも良し、カヤックやBBQなどのアクティブな楽しみ方もでき、その時の気分に合わせた多様な過ごし方が可能です。特別な“伊勢志摩時間”を過ごしてみませんか？' where id = 'RFwfemCraRnGhhMBYz8Fu';
update content_bodies set title = 'Ise-Shima Resort Stay', description = 'Ise-Shima is blessed with the beautiful ria coastline formed by its intricately shaped peninsula and numerous islands, as well as an abundance of seafood. Visitors can choose to relax at their accommodations or engage in more active pursuits like kayaking and BBQs, allowing for a variety of experiences that suit their mood. Why not spend your own special ''Ise-Shima time'' here? Explore options like ''Ise-Shima Hokans'' and ''Ise-Shima Glamping'' for unique stays.' where id = '5QCYyG_Q3Knpt7vXRivb1';
update content_bodies set title = '長崎ばーどアイ　島原市火張山の桜　後編', description = '島原市に位置する火張山公園は、かつて火砕流によって被災した場所です。この公園には復興の象徴とも言える一本の桜があり、菜の花との共演が見られます。桜と菜の花の美しい景色は、訪れる人々に感動を与えています。' where id = 'ckdYEqkRczXB9vfYg7MUL';
update content_bodies set title = 'Nagasaki Bird Eye: Cherry Blossoms at Mount Hibari in Shimabara City - Part 2', description = 'Hibariyama Park in Shimabara City is a floral spot that was once a site of volcanic devastation. The park features a single cherry blossom tree that stands as a symbol of recovery, beautifully complemented by fields of rapeseed flowers.' where id = 'iZcUIZHGSERiUaza3jkdO';
update content_bodies set title = '長崎ばーどアイ４K　福江島西端　三井楽の海岸線', description = 'この映像は、長崎の福江島の西端に位置する三井楽の美しい海岸線をドローン技術を用いて捉えたものです。自然の美しさや独特の風景が強調されており、視聴者にこの絵のように美しい地域の鳥瞰図を提供しています。' where id = 'QfGaayLIKqhe-YSIANkCv';
update content_bodies set title = 'Nagasaki Bird Eye 4K: The Coastline of Mitsuura at the Western End of Fukue Island', description = 'This video showcases the stunning coastline of Mitsuura located at the western end of Fukue Island in Nagasaki, captured using drone technology. The footage highlights the natural beauty and unique landscapes of the area, providing viewers with a bird''s-eye view of this picturesque region.' where id = 'G2ixkyHB1HoEDpsgSgTBO';
update content_bodies set title = '広島でいちご狩りするならここ！！🍓🍓 #北広島町 #アウトドア #旅行#いちご', description = 'いちご好きの皆さん、北広島町の豊平どんぐり農園に行ってきました！広島県観光アシスタントの宮内さんと共に、いちご狩りを楽しみました。農園では、育てられたいちごの9品種が5月下旬まで楽しめ、30分の食べ放題が可能です。練乳やチョコソース、ホイップクリームなどのトッピングも持ち込み可能で、甘くて大きないちごを堪能しました。広々とした園内はベビーカーや車椅子でも快適に過ごせます。この時期のいちごは特におすすめとのこと。予約や問い合わせは豊平どんぐり農園のHPやSNSをご覧ください。' where id = 'YQkVCQP6p48MPF2zT-lfT';
update content_bodies set title = 'Strawberry Picking in Hiroshima!! 🍓🍓 #Kitahiroshima #Outdoor #Travel #Strawberry', description = 'For all strawberry lovers! 🍓🍓 We visited Toyohira Donguri Farm in Kitahiroshima Town with the staff of the Kitahiroshima Town Tourism Association and Hiroshima''s first tourism assistant, Mr. Miyauchi. Mr. Miyauchi is dedicated to promoting tourism and events in Hiroshima and has a fondness for Kitahiroshima. We were guided by Mr. Yahagihara, who showed us the farm''s nine varieties of strawberries, available until late May. It''s about an hour''s drive from Hiroshima City, and you can enjoy all-you-can-eat strawberries for 30 minutes, with toppings like condensed milk, chocolate sauce, and whipped cream allowed. The strawberries are so large and sweet that we couldn''t talk while enjoying them. The spacious farm is accessible for strollers and wheelchairs. Mr. Yahagihara recommends this time of year for the best strawberries. For reservations and inquiries, check the Toyohira Donguri Farm''s website or social media!' where id = 'kNGA3VLGxZV-Y9Uec6k46';
update content_bodies set title = '長崎ばーどアイ４K日島石塔群', description = 'このコンテンツは、ドローン技術を用いて撮影された長崎の日島石塔群の4K空撮映像を特集しています。この歴史的な場所の美しさと重要性を強調し、地域の独特な建築や風景を紹介しています。このプロジェクトは長崎放送に関連しており、地域の文化遺産を強調しています。' where id = 'AglDf4YF-fkUPg9IByk3-';
update content_bodies set title = 'Nagasaki Bird Eye 4K Nishi Island Stone Pagoda Group', description = 'This content features a 4K aerial view of the Nishi Island Stone Pagoda Group in Nagasaki, captured using drone technology. It highlights the beauty and significance of this historical site, showcasing the unique architecture and landscape of the area. The project is associated with Nagasaki Broadcasting, emphasizing the region''s cultural heritage.' where id = 'UNVBzXWwC8q2bTQ6NUZy-';
update content_bodies set title = '長崎ばーどアイ４K　三十路苑の紅葉', description = 'このコンテンツは、長崎の三十路苑における美しい紅葉を4Kドローン映像で紹介しています。鮮やかな色合いの葉や自然の美しさを強調し、風景の素晴らしさを映し出しています。' where id = '3IanDMKSpkSzZY_Yac_Q4';
update content_bodies set title = 'Nagasaki Bird Eye 4K: Autumn Leaves at Sanjuro-en', description = 'This content features a 4K drone footage of the beautiful autumn leaves at Sanjuro-en in Nagasaki. It showcases the stunning scenery and vibrant colors of the foliage, highlighting the natural beauty of the area.' where id = 'sRxD__nA8JbGc2_jt1fYB';
update content_bodies set title = '長崎ばーどアイ４Ｋ　針尾無線塔', description = 'このコンテンツは、長崎ばーどアイ４Ｋを特集し、針尾無線塔を紹介しています。ドローンを使用して長崎の美しい空撮映像を捉え、長崎放送によって提供されています。' where id = 'NEqtovw9_RtuP6ol53K3P';
update content_bodies set title = 'Nagasaki Bird Eye 4K: Hario Wireless Tower', description = 'This content features the Nagasaki Bird Eye 4K, showcasing the Hario Wireless Tower. It highlights the use of drones in capturing stunning aerial views of Nagasaki, presented by Nagasaki Broadcasting.' where id = 'i-Z5Agu3mnxM4MMch521E';
update content_bodies set title = '長崎ばーどアイ４Ｋ　志々伎山', description = '長崎ばーどアイは、長崎放送によるドローンプロジェクトで、志々伎山の美しい風景を4K解像度で紹介しています。' where id = 'j-ruQ9yGChL9pIsV8clYi';
update content_bodies set title = 'Nagasaki Bird Eye 4K - Shishikiyama', description = 'Nagasaki Bird Eye is a drone project by Nagasaki Broadcasting, showcasing the scenic views of Shishikiyama in 4K resolution.' where id = 'C9u-CMTZrtgmYXNZ_Cj4c';
update content_bodies set title = '長崎ばーどアイ４Ｋ　川内峠の夏（平戸市）', description = 'このコンテンツは、長崎県平戸市の川内峠を夏にドローンで撮影した４Ｋ映像を紹介しています。自然の美しさや風景の魅力を強調し、ドローン技術が提供する独自の視点を示しています。' where id = 'US_qjJ_4YSIMGzsK_hEjP';
update content_bodies set title = 'Nagasaki Bird Eye 4K: Kawauchi Pass in Summer (Hirado City)', description = 'This content features a 4K drone view of Kawauchi Pass during the summer season in Hirado City, Nagasaki. It highlights the natural beauty and scenic landscapes of the area, showcasing the unique perspective that drone technology can provide.' where id = 'jmhR5Wu0a7bg243CxKbC5';
update content_bodies set title = '長崎ばーどアイ４Ｋ　九十九島のサンセットクルーズ', description = 'このコンテンツは、長崎の九十九島エリアをドローンで撮影した美しい4K映像を特集しています。クルーズ中のサンセットの美しさを捉え、穏やかな風景と夕日の鮮やかな色合いを提供し、この絵のように美しい場所のユニークな視点を提供します。' where id = 'DbHuw8BPsJz1h4cpcJA14';
update content_bodies set title = 'Nagasaki Bird Eye 4K: Kujukushima Sunset Cruise', description = 'This content features a stunning 4K drone view of the Kujukushima area in Nagasaki, showcasing the beauty of the sunset during a cruise. The video captures the serene landscape and vibrant colors of the sunset, providing a unique perspective of this picturesque location.' where id = 'yFSlUEsAHOzpdHTdMfV3A';
update content_bodies set title = '長崎ばーどアイ４Ｋ　殿崎（対馬市）', description = '長崎ばーどアイは、ドローンを使用して美しい空撮映像を捉えるプロジェクトです。このセグメントでは、対馬市の殿崎に焦点を当て、独自の視点からこの地域の美しさを紹介しています。このプロジェクトは長崎放送と関連しており、地域の自然景観や文化的重要性を強調しています。' where id = '7Dk5r0i1GmV812JczT2D2';
update content_bodies set title = 'Nagasaki Bird Eye 4K - Tonozaki (Tsushima City)', description = 'Nagasaki Bird Eye is a project that utilizes drones to capture stunning aerial footage. This particular segment focuses on Tonozaki in Tsushima City, showcasing the beauty of the area from a unique perspective. The project is associated with Nagasaki Broadcasting, highlighting the region''s natural landscapes and cultural significance.' where id = 'JBVy0f_GnKH6k0VSZBa3P';
update content_bodies set title = '神楽トラック完成👹👹 #北広島町　#神楽', description = '北広島町の「琴庄神楽団」がトラックに目を引くラッピングを施しました。このトラックは広島だけでなく他県でも目立ち、広島神楽の注目度を高めることでしょう。掲載されている写真は、観光協会が制作した「ロゲットカード」の素材写真で、神々を捕らえる蜘蛛の糸の瞬間を捉えた迫力ある場面です。神楽ファンにはたまらないシーンでしょう。このトラックを見かけた方は、ぜひコメントで教えてください！' where id = 'PcFqNXr233cvqkv67pOdt';
update content_bodies set title = 'Kagura Truck Completed 👹👹 #KitaHiroshima #Kagura', description = 'The ''Koto Sho Kagura Group'' from Kita Hiroshima has wrapped their truck in a striking design. This eye-catching truck is sure to stand out not only in Hiroshima but also in other prefectures, significantly raising the profile of Hiroshima Kagura. The photo featured is from a promotional material for the ''Roget Card,'' created by the tourism association, capturing a dramatic moment where spider threads ensnare the gods, a scene that Kagura enthusiasts will surely appreciate. If you''ve seen the truck, please let us know in the comments!' where id = 'OWafOdViiEjp68TxFAZDL';
update content_bodies set title = '長崎ばーどアイ４Ｋ　海神神社（川棚町）', description = 'このコンテンツは、長崎県川棚町にある海神神社の4K空撮映像をドローンで撮影したものです。長崎放送に関連しています。' where id = '_pU0GazIZk0KGbzXKxSxp';
update content_bodies set title = 'Nagasaki Bird Eye 4K: Umikami Shrine (Kawatana Town)', description = 'This content features a 4K aerial view of Umikami Shrine located in Kawatana Town, Nagasaki, captured using a drone. It is associated with Nagasaki Broadcasting.' where id = 'WVibErGQelGfcg4pZKKKq';
update content_bodies set title = '古民家で癒しの時間に浸る。', description = '大朝にある1棟貸し古民家「hitaru石橋邸」は、築200年の刀鍛冶職人の邸宅をリノベーションしたもので、温かみのある光に包まれています。シックな黒を基調とした空間は、キッチンを中心とした食のゲストハウスとして、旬の食材を楽しむことや厳選されたシェフの料理を味わうことができます。大きな丸いテーブルは、福光酒造の酒樽の蓋をリメイクしたものです。家具やインテリアにはこだわりがあり、BALMUDAの電化製品が揃っています。庭では焚き火やBBQを楽しむことができ、真っ暗な夜空には満天の星が広がります。日が昇ると「大朝富士」と呼ばれる寒曳山が目の前に現れ、鳥のさえずりが心を癒します。最大12名まで宿泊可能で、広島市内から車で1時間の距離にあり、都会では味わえない贅沢な時間を提供しています。' where id = 'yc6gWYvAGJF9zB3JVhRy1';
update content_bodies set title = 'Experience Healing Time in a Traditional House', description = 'The hitaru Ishibashi residence, a one-house rental traditional home located in Oasa, has been renovated by Fumu Co., Ltd. This 200-year-old former residence of a swordsmith offers a warm atmosphere as you ascend to its elevated location. Inside, the chic black-themed space features a kitchen-centered guesthouse concept, allowing guests to enjoy seasonal ingredients or exquisite dishes prepared by selected chefs. The large round table, made from a repurposed sake barrel lid from Fukumitsu Sake Brewery, enhances the dining experience. The residence is designed for guests to immerse themselves in the extraordinary, with carefully chosen furniture and BALMUDA appliances. Outdoor activities include enjoying a bonfire or BBQ, with a stunning starry sky visible in the absence of city lights. The breathtaking view of Mt. Kanbiki, known as Oasa Fuji, greets guests at sunrise, accompanied by the soothing sounds of birds. With two bedrooms accommodating up to 12 guests, this unique getaway is just an hour''s drive from Hiroshima City, offering a luxurious experience of ''eating, sleeping, and soaking'' that is hard to find in urban settings.' where id = 'mMy1Ne15SjFYbMSLpBFuj';
update content_bodies set title = '米フェス＆全日本お米グランプリin北広島町🌾が開催されました✨', description = '北広島町のまちづくりセンターの芝生広場で、米フェスと全日本お米グランプリが開催されました。「おこめの''わわわ''」コーナーでは、試食や購入ができ、多くの来場者で賑わいました。強風の中、美味しい香りが漂い、早々に完売するブースもありました。地元のお米で作ったおむすびは大きくて具だくさんで絶品でした。ステージでは神楽や観光PR、お笑い芸人の「メンバー」さんが会場を盛り上げ、観客の笑い声が絶えませんでした。観光PRではお米に関するクイズ大会も行われ、子どもたちが楽しんで参加していました。北広島町は「世界一おいしく楽しくお米が食べられる町」を目指し、今後も「おこめの''わわわ''プロジェクト」を進めていきます。' where id = 'HgHVBsxqN-wNaslkX07L4';
update content_bodies set title = 'Rice Festival & All Japan Rice Grand Prix Held in Kitahiroshima Town 🌾', description = 'The Rice Festival and All Japan Rice Grand Prix took place in Kitahiroshima Town, featuring a lively atmosphere at the community center''s lawn. The ''Okome no ''Wawawa'' corner offered tastings and sales of various rice products, attracting many visitors despite the strong winds. The delicious aroma of food filled the air, and some booths sold out quickly, indicating the event''s success. The rice balls made with local rice were large, filled with ingredients, and exceptionally tasty. The stage featured performances including Kagura and a quiz contest related to rice, which engaged the audience, especially children. The event aimed to promote Kitahiroshima''s rice and enhance its reputation as a town where delicious and enjoyable rice can be experienced. The ''Okome no ''Wawawa'' project will continue to develop and promote the town''s rice products.' where id = '4L_yUuh5Ktvx4MQfy33s_';
update content_bodies set title = '北広島町のスキー場が盛り上がっているらしい⛄⛄ #旅行 #北広島町 #広島 #雪 #スキー #グルメ', description = '冬が到来し、北広島町のスキー場がオープンしました！観光協会の職員が新しくオープンしたスキー場を訪れ、太陽に反射する美しい雪の様子を紹介しています。北広島町は雪が積もる地域で、訪れたお客様が楽しそうに滑る姿が印象的でした。町内には3つのスキー場があり、芸北高原 大佐スキー場は初心者向けの広いコースと絶景が魅力。ユートピアサイオトは家族向けの施設が充実し、西日本最大級のスノーパークもあります。やわたハイランド191リゾートは、地域で最も雪が積もるスキー場で、全世代が楽しめる施設が整っています。遠方からの訪問者には宿泊施設も多く、ゆっくりと冬を楽しむことができます。2025年1月11日には「北広島町スキーの日」として、先着100台の無料駐車サービスや初心者レッスンが行われます。' where id = 'Ka7tL5--SheEj7XDbfpFJ';
update content_bodies set title = 'Excitement at Ski Resorts in Kitahiroshima Town⛄⛄ #Travel #Kitahiroshima #Hiroshima #Snow #Ski #Gourmet', description = 'Winter is here, and so is skiing in Kitahiroshima Town! The local tourism association staff visited the newly opened ski resorts, showcasing the beauty of the sparkling snow under the sun. Kitahiroshima Town is known for its snow, and the excitement of visitors enjoying the slopes was palpable. There are three ski resorts in the area: Geihoku Kogen Osa Ski Resort, known for its beginner-friendly wide courses and stunning views; Utopia Saioto, featuring a snow park and family-friendly amenities; andYawata Highland 191 Resort, which boasts the most snow in the region and offers a variety of facilities for all ages. Visitors can enjoy delicious meals and ample rental options. For those coming from afar, there are many accommodations nearby. On January 11, 2025, Kitahiroshima Town will celebrate Ski Day with free parking and beginner lessons at all three resorts.' where id = '3G5tmp9e5He1nm53CpNJS';
update content_bodies set title = '長崎ばーどアイ４Ｋ　県道雲仙千々石線', description = 'このコンテンツは、ドローン技術を使用して撮影された長崎の県道雲仙千々石線の4K空撮映像を特集しています。地域の風景や魅力を強調し、この道路沿いに見られる独特の景観や観光名所を紹介しています。このプロジェクトは長崎放送に関連しており、地域の自然の美しさを強調し、地元の観光を促進しています。' where id = 'GWYtupQu9YFI4VQ2yMYxj';
update content_bodies set title = 'Nagasaki Bird Eye 4K: Prefectural Road Unzen Chijiwa Line', description = 'This content features a 4K aerial view of the Unzen Chijiwa Line in Nagasaki, captured using drone technology. It showcases the scenic beauty of the area, highlighting the unique landscapes and attractions that can be found along this road. The project is associated with Nagasaki Broadcasting, emphasizing the region''s natural charm and promoting local tourism.' where id = '0CX2v36ypX_n06VvJKbKY';
update content_bodies set title = '長崎ばーどアイ４Ｋ　島鉄南島原駅', description = '長崎ばーどアイは、ドローンを使用して長崎の美しさを紹介するプロジェクトです。このセグメントでは、島鉄南島原駅に焦点を当て、その周辺や地域の独特な風景を強調しています。このプロジェクトは長崎放送と関連しており、高品質なドローン映像を通じて地域の自然や文化遺産を伝えています。' where id = '6QQMU8rz9RRT-qNMo8VPj';
update content_bodies set title = 'Nagasaki Bird Eye 4K - Shimatetsu Minamishimabara Station', description = 'Nagasaki Bird Eye is a drone project that showcases the beauty of Nagasaki, featuring stunning aerial views. This particular segment focuses on Shimatetsu Minamishimabara Station, highlighting its surroundings and the unique landscape of the area. The project is associated with Nagasaki Broadcasting, emphasizing the region''s natural and cultural heritage through high-quality drone footage.' where id = '2cQKfwVGjCB0ohd-pYJSw';
update content_bodies set title = '長崎ばーどアイ４Ｋ　松浦鉄道の風景', description = 'このコンテンツでは、ドローン技術を用いて撮影された長崎の松浦鉄道の美しい空撮映像が紹介されています。地域の魅力を引き立てる風景や独特の景観が映し出され、鉄道とその周辺の魅力が際立っています。' where id = 'lXyFuUWSx2WYfaqrbNV_p';
update content_bodies set title = 'Nagasaki Bird Eye 4K: Scenery of Matsura Railway', description = 'This content features stunning aerial views of the Matsura Railway in Nagasaki, captured using drone technology. The visuals showcase the beautiful landscapes and unique scenery of the region, highlighting the charm of the railway and its surroundings.' where id = 'CdFRjV_sa2xJVxaHkBKLL';
update content_bodies set title = '長崎ばーどアイ４K　ヒトツバタゴ群生地（対馬市）', description = '長崎ばーどアイは、対馬市にあるヒトツバタゴ群生地の美しい4Kドローン映像を紹介しています。このプロジェクトは長崎放送と関連しています。' where id = 'qeXINbjIParGdeVG7pEEi';
update content_bodies set title = 'Nagasaki Bird Eye 4K - Hitotsubata-go Grove (Tsushima City)', description = 'Nagasaki Bird Eye showcases stunning 4K drone footage of the Hitotsubata-go grove located in Tsushima City. This project is associated with Nagasaki Broadcasting.' where id = 'dy01Vap7qvwliCuPX2Z_3';
update content_bodies set title = '長崎ばーどアイ４K　日見峠明治新道（長崎市）', description = '#長崎ばーどアイ #ドローン #長崎放送' where id = 'PtWFdifkKOVbtzjRCQqhD';
update content_bodies set title = 'Nagasaki Bird Eye 4K: Himi Pass Meiji New Road (Nagasaki City)', description = '#NagasakiBirdEye #Drone #NagasakiBroadcast' where id = 'IEXFloI2cgkgul4WLjXgf';
update content_bodies set title = '第37回そばまつり2024が豊平で開催されました', description = '11月16〜17日の2日間、豊平で「第37回そばまつり2024」が開催され、約1万8千人が来場しました。神楽やダンス、吹奏楽など多彩なステージがあり、来場者は地元の美味しい料理や屋台グルメを楽しみながら、手拍子や歌で盛り上がりました。シンガー・タレントの月山翔雲さんの「ひろしま牡蠣のうた」も披露され、観客のテンションが上がりました。お祭りのメインは「新そば」で、早朝から蕎麦を打つ準備が行われ、出汁の香りが漂う中、打ち立ての蕎麦を楽しむことができました。豊平そばは道の駅豊平どんぐり村で一年中味わえ、温泉やお土産も揃っています。来年のそばまつりも楽しみです！' where id = '06rfG-6EZnBKTgFlKXniZ';
update content_bodies set title = 'The 37th Soba Festival 2024 Held in Toyohira on November 16-17', description = 'The 37th Soba Festival took place in Toyohira over two days, attracting around 18,000 visitors. The event featured a variety of performances, including Kagura, dance, and brass band music, creating a lively atmosphere. Attendees enjoyed local delicacies and street food while participating in clapping and singing along. A highlight was singer and talent Shoun Tsukiyama''s performance, where he sang the beloved ''Hiroshima Oyster Song.'' The festival''s main attraction was the ''new soba,'' with fresh noodles being made early in the morning. The aroma of dashi filled the tents, providing a comforting experience. Visitors can enjoy Toyohira soba year-round at the Toyohira Donguri Village, which also offers hot springs and souvenirs. The anticipation for next year''s festival is already building!' where id = 'txImiXIsWzkaa7b6ZsQec';
update content_bodies set title = '長崎ばーどアイ４K　万関瀬戸（対馬市）', description = '長崎ばーどアイは、対馬市の万関瀬戸をドローンで撮影した美しい空撮映像を紹介するプロジェクトです。このプロジェクトは長崎放送と関連しており、4Kの高品質な映像を通じて地域の魅力を伝えています。' where id = 'UBJwqfuYW4mRRaVHGZ6m6';
update content_bodies set title = 'Nagasaki Bird Eye 4K - Mankai Seto (Tsushima City)', description = 'Nagasaki Bird Eye is a drone project that showcases stunning aerial views of Mankai Seto in Tsushima City. The project is associated with Nagasaki Broadcasting, highlighting the beauty of the region through high-quality 4K footage.' where id = '9nYK4HXy5GYUGAWhQG6br';
update content_bodies set title = '長崎ばーどアイ４K　東彼杵町の茶摘みの風景', description = 'このコンテンツは、ドローン技術を用いて撮影された長崎県東彼杵町の茶摘みの風景を4Kで紹介しています。美しい風景と伝統的な茶の収穫の様子が映し出されており、この地域の農業の遺産を強調しています。' where id = 'Ygz8LSny8X-MTnFsKrjgB';
update content_bodies set title = 'Nagasaki Bird Eye 4K: Tea Picking Scenery in Higashisonogi Town', description = 'This content features a 4K aerial view of tea picking in Higashisonogi Town, Nagasaki, captured using drone technology. The video showcases the beautiful landscape and the traditional practice of tea harvesting, highlighting the region''s agricultural heritage.' where id = 'skrRwf7vYJ7Z_WIzIvfA-';
update content_bodies set title = '松山城天守閣に行ってきました！', description = '愛媛県松山市にある松山城では、加藤嘉明の鎧や当時の武器が展示されています。訪問者は武装服を試着できるほか、松山城小天守の復興に関するビデオを視聴することも可能です。また、天守閣からは360°のパノラマビューを楽しむことができます。RyoFさんが松山城入口までの景色を撮影した動画も公開されています。' where id = 'ZyLPc86565TPrRt0rGI_v';
update content_bodies set title = 'Visit to Matsuyama Castle Keep!', description = 'Matsuyama Castle, located in Matsuyama City, Ehime Prefecture, features exhibits of armor worn by Kato Yoshiaki and weapons used during that era. Visitors can also try on samurai armor and watch a video about the restoration of the Matsuyama Castle''s small keep. Additionally, the castle keep offers a 360° panoramic view. RyoF has captured the scenery leading to the entrance of Matsuyama Castle, which can be viewed at this link: https://youtu.be/T1l3eHh-TaQ' where id = 'TxFWoGahanKa6ofC1PuvN';
update content_bodies set title = '今治城に行ってきました！(天守閣編)', description = 'ここは愛媛県今治市にある今治城です。今回は天守閣の撮影に焦点を当てました。詳しい情報は、こちらのリンクをご覧ください！→ http://museum.city.imabari.ehime.jp/imabarijo/ 本丸跡編については、こちらのリンクをご覧ください→ https://youtu.be/7DIJ32CeSvI' where id = '4lxZTzF_heuKHujk66owv';
update content_bodies set title = 'I Visited Imabari Castle! (Main Keep Edition)', description = 'This is Imabari Castle located in Imabari City, Ehime Prefecture! This time, I focused on photographing the main keep. For more detailed information, visit here! → http://museum.city.imabari.ehime.jp/imabarijo/ For the main bailey edition, check out this link → https://youtu.be/7DIJ32CeSvI' where id = 'Rc-5O-mtas7HnZYhXxdfq';
update content_bodies set title = 'おおあさ わさのわスタンプラリーに観光協会職員が参加してきました🍂 #北広島町#広島県', description = '観光協会の職員が、おおあさ わさのわスタンプラリーに参加しました。まずQRコードを読み取り、スタンプラリーサイトにログインします。スポットを確認し、目的地に着くとスタンプを獲得できます。スタンプの獲得方法はQRコードスキャンやGPS、クイズ回答など多様です。スタンプがたまると特典に応募でき、今回は8ヶ所集めてお米3合をゲットしました。お米30kgが当たるチャンスもあります！他にも木こり体験やサイクリングツアーなどの特典があります。地元の知られざるスポットを巡るのは冒険気分で、紅葉巡りやドライブにぴったりです。スタンプラリーは12月9日まで開催中で、特典もまだまだ用意されています。併設のフォトコンテストでもお米30kgが当たるチャンスがあります。大朝の魅力を再発見するスタンプラリーとフォトコンテストにぜひご参加ください！' where id = 'mMVMpcUGnNzzBPI7GrnuC';
update content_bodies set title = 'Participation of Tourism Association Staff in the Oasa Wasanowa Stamp Rally 🍂 #KitahiroshimaTown #HiroshimaPrefecture', description = 'The staff of the tourism association participated in the Oasa Wasanowa Stamp Rally. Participants start by scanning a QR code to log into the stamp rally site. They can check various spots and earn stamps by reaching those locations, scanning QR codes, using GPS, or answering quizzes. Accumulated stamps can be used to enter for prizes. This time, the staff collected stamps from eight locations and received 3 go of rice. There’s also a chance to win 30 kg of rice! Other rewards include experiences like lumberjack activities and cycling tours, as well as meal vouchers. Exploring local spots, even those unknown to locals, feels adventurous. The rally runs until December 9, with many rewards still available. Additionally, a photo contest is being held, offering another chance to win 30 kg of rice. Join the stamp rally and photo contest to rediscover the charm of Oasa!' where id = '42kFYl3Gaai9yZ2i82SEg';
update content_bodies set title = '高知城に行ってきました！', description = '高知県高知市丸ノ内１丁目２−２−１に位置する高知城についての情報を紹介しています。詳細は公式サイトをご覧ください。動画の最後には、高知市の日曜市の様子も撮影しています。日曜市についての詳しい情報は、こちらのリンクから確認できます。' where id = 'aP5XTw8AlAgHKMslmk4xs';
update content_bodies set title = 'I Visited Kochi Castle!', description = 'This is Kochi Castle located at 1-2-2-1 Marunouchi, Kochi City, Kochi Prefecture. For more detailed information, visit here! → http://kochipark.jp/kochijyo/ At the end of this video, I have also filmed the Sunday Market in Kochi City. For more details about the Sunday Market, click here! → http://www.city.kochi.kochi.jp/soshiki/39/nichiyouichi.html' where id = 'fvQMsMJw_ivWbn8JYDwBb';
update content_bodies set title = '大洲城に行ってきました！', description = '大洲城は愛媛県大洲市大洲903に位置しています。2004年に復元された天守をはじめ、国指定重要文化財に選定された4棟の櫓があります。この動画の最後には、愛媛県松山市を流れる宮前川にいたコガモの映像が収められています。' where id = 'UgazhgtL0BqFmXqwD2l_G';
update content_bodies set title = 'I Visited Ozu Castle!', description = 'Ozu Castle is located at 903 Ozu, Ozu City, Ehime Prefecture. The castle features a restored main keep, which was completed in 2004, and includes four towers designated as Important Cultural Properties by the national government. At the end of the video, there is footage of a female teal spotted in the Miyamae River flowing through Matsuyama City, Ehime Prefecture.' where id = 'dZE2A0AHXnTS0M5tWJveI';
update content_bodies set title = '丸亀城鉄砲隊の演武を見てきました！', description = 'このイベントは、愛媛県松山市の堀之内で行われた「第５回 全国城サミットin松山」の丸亀城鉄砲隊の演武です。演武では、安土桃山時代に使用されていた火縄銃の迫力を体感することができ、当時の雰囲気を味わうことができます。安土桃山時代の迫力を実際に感じてみてください！名古屋おもてなし武将隊の演武もこちらでご覧いただけます！→https://youtu.be/nSs7-jqvqVQ' where id = 'ckrN_EDTxReXvrHgUkZuQ';
update content_bodies set title = 'I Attended the Demonstration of the Marugame Castle Gun Corps!', description = 'This event featured the demonstration of the Marugame Castle Gun Corps at the ''5th National Castle Summit in Matsuyama,'' held in Horinouchi, Matsuyama City, Ehime Prefecture. The demonstration showcased the power of the matchlock guns used during the Azuchi-Momoyama period. Experience the intensity of the Azuchi-Momoyama era firsthand! You can also watch the performance of the Nagoya Hospitality Samurai Team here! → https://youtu.be/nSs7-jqvqVQ' where id = 'uFAbY7tBvy4iEfIMo-uor';
update content_bodies set title = '宇和島城に行ってきました！(登城編)', description = '宇和島城は愛媛県宇和島市に位置する平山城で、標高80mの丘の上に築かれています。伊達氏の2代目宗利によって大規模な改修が行われ、現在の形になりました。天守閣は国指定の重要文化財に指定されています。' where id = '2yUZ8Znqxo-z9LiAHAuGg';
update content_bodies set title = 'I Visited Uwajima Castle! (Castle Climbing Edition)', description = 'Uwajima Castle is located in Uwajima City, Ehime Prefecture, Japan. This flat mountain castle was built on a hill at an elevation of 80 meters. It was significantly renovated by the second generation of the Date clan, Muneyoshi, which led to its current form. The main keep of the castle is designated as an Important Cultural Property by the national government.' where id = '9xi_CqT8e4MEZ_6TPox4j';
update content_bodies set title = '伊賀忍者フェスタ2018', description = '三重県伊賀市で、忍者の里の名物イベント「伊賀忍者フェスタ2018」が4月7日（土）から5月6日（火）まで開催されます。この春、桜が彩る城下町を忍者になって散策してみませんか。イベントでは、伊賀流忍者博物館の取材レポートもあり、本物の忍術を体感できる機会や躍動感あふれる忍者たちに会えるチャンスがあります。三重県の観光、旅行、イベント、宿泊予約については、公式サイト「観光三重」をご覧ください。' where id = 'NHP1KWW4-sefZLYhS0whJ';
update content_bodies set title = 'Iga Ninja Festival 2018', description = 'The Iga Ninja Festival 2018 will be held in Iga City, Mie Prefecture, from April 7 (Saturday) to May 6 (Tuesday). This spring, why not become a ninja and stroll through the castle town adorned with cherry blossoms? The festival features various activities, including a report on the Iga-ryu Ninja Museum, where visitors can experience authentic ninjutsu and meet dynamic ninjas. For more information on tourism in Mie Prefecture, including travel, events, and accommodation, visit the official site ''Kankou Mie''.' where id = '7cKiXxXpFjV0ATxSZjK1i';
update content_bodies set title = '愛媛県四国中央市「川之江城」に行ってみた！', description = '川之江城は愛媛県四国中央市に位置しています。この城は昭和61年（1986年）に天守閣や涼櫓、櫓門、空塀などが整備され、瀬戸内の島々の美しい眺望を楽しむことができます。また、桜の名所としても知られ、多くの観光客が訪れる人気のスポットです。ぜひ訪れてみてください。' where id = 'wnHtG1iFi79QOAEaydnQz';
update content_bodies set title = 'Visit to Kawanoe Castle in Shikokuchuo City, Ehime Prefecture!', description = 'Kawanoe Castle is located in Shikokuchuo City, Ehime Prefecture. The castle was renovated in 1986, featuring a main keep, a cool tower, turret gates, and stone walls. It offers stunning views of the islands in the Seto Inland Sea and is renowned as a cherry blossom viewing spot, attracting many tourists. Be sure to visit!' where id = 'WE1_jQeZcHqpAUvmpTx5a';
update content_bodies set title = '四季乃家彩蔵さんのとっておき秋メニューを食べに観光協会職員が行ってきました', description = '観光協会の職員が四季乃家彩蔵を訪れ、特別な秋メニューを楽しみました。夜の彩蔵は昼とは異なり、石灯籠の優しい灯りが心を和ませます。秋メニューのイチオシは「米粉シチューのあつあつ」で、濃厚で甘いかぼちゃのシチューにうまみたっぷりのハンバーグが入っています。肌寒い季節には「じゅ～じゅ～」「グツグツ」の音が心を惹きつけます。どの料理も美しさがあり、旬の食材が大将の技でさらに美味しくなっています。松茸をふんだんに使ったきのこご飯は香り豊かで、秋の恵みを贅沢に楽しめる一品です。大将の自信に満ちた笑顔が美味しさを伝えています。20周年の動画で人気が高まり、今回も新たなファンが増えそうです。ぜひこの特別な秋メニューを味わいに来てください。' where id = 'ywH5mbKzqK2HLRQZxCvq4';
update content_bodies set title = 'Autumn Menu at Shikinoya Ayakura: A Visit by the Tourism Association Staff', description = 'The staff of the tourism association visited Shikinoya Ayakura to enjoy their special autumn menu. The evening ambiance at Ayakura is different from the daytime, with the gentle light of stone lanterns creating a soothing atmosphere. The highlight of the autumn menu is the ''Hot Rice Flour Stew,'' featuring a rich and sweet pumpkin stew with a flavorful hamburger inside. The sounds of sizzling and bubbling are particularly inviting in this chilly season. Each dish is visually appealing, showcasing seasonal ingredients enhanced by the chef''s skills. The mushroom rice, generously mixed with matsutake mushrooms, offers a fragrant taste of autumn. The chef''s confident smile conveys the deliciousness of the dishes. Following the popularity from the 20th-anniversary video, the chef''s charm is likely to attract even more fans. Don''t miss out on this special autumn menu!' where id = '5d7cH8wcGMZRdfR9ysWn9';
update content_bodies set title = 'ぐつぐつ…ぐつぐつ…彩蔵さんこだわりの「秋メニュー」の登場です', description = '広島県北広島町にある「四季乃家 彩蔵」では、秋メニューが登場しました。メニューには、胡麻豆ふと自家製いくら醤油漬、天然魚の蒸し物、旬の魚のお造り、天然鯛の葛打ち、焼八寸、手打ち蕎麦、米粉シチュー、きのこご飯、そして自家製米味噌仕立ての留椀が含まれています。デザートにはブルーベリーアイスが用意されています。テイクアウトは1ヶ月前から2日前までに予約が必要で、営業時間は11時半から15時、18時から22時まで。水・木曜日は定休日です。彩蔵のInstagramもチェックしてみてください。' where id = '9cQQIuVjMmdQW1_ffM6GA';
update content_bodies set title = 'Introducing Ayakura''s Autumn Menu', description = 'Ayakura, located in Kitahiroshima Town, Hiroshima, has launched its special autumn menu. The restaurant offers a variety of dishes, including sesame tofu with homemade soy sauce marinated ikura, steamed natural fish with shiso cream, seasonal sashimi, and a soup featuring natural sea bream. The menu also includes grilled dishes, hand-made soba, hot rice dishes with mushrooms, and a homemade rice miso soup. For dessert, there is blueberry ice cream. Reservations for takeout are required one month to two days in advance. The restaurant operates from 11:30 AM to 3 PM and 6 PM to 10 PM, closed on Wednesdays and Thursdays. Follow Ayakura on Instagram for updates.' where id = 'jwmq37hnJUiGDKojDT0fK';
update content_bodies set title = '東海道関宿～伝統を受け継ぐ～(亀山市)｜観光三重｜三重県の観光・旅行情報', description = '東海道五十三次の47番目の宿場町である関宿は、今も昔の雰囲気を残しています。江戸時代後期から明治時代にかけて建てられた200棟以上の町家が現存し、国の重要伝統的建造物群保存地区や日本の道百選に選ばれています。伝統を受け継いできた人々を通じて、関宿の魅力が紹介されています。' where id = 'qskvD5KHGg7UIDvGSp7ED';
update content_bodies set title = 'Tokaido Sekijuku - Inheriting Tradition - (Kameyama City) | Tourism Mie | Mie Prefecture Travel Information', description = 'Sekijuku, the 47th post town of the Tokaido Fifty-Three Stations, retains the atmosphere of its historical past. Over 200 townhouses built from the late Edo period to the Meiji era still exist here, and the area has been designated as an Important Traditional Building Preservation District and selected as one of Japan''s Top 100 Roads. The charm of Sekijuku is introduced through the people who have inherited its traditional ways.' where id = '3XHnWBYX0Tje7Ufx_lids';
update content_bodies set title = '月山翔雲さんと花田舞太郎くんのコラボステージ！！ #北広島町', description = '10月12日（土）・13日（日）の2日間、道の駅舞ロードIC千代田で「秋の大感謝祭」が開催されました。子ども神楽や千代田中学校の吹奏楽、観光大使の月山翔雲さんのステージライブなど、盛りだくさんの内容でした。オープニングを飾った吹奏楽部は金賞を受賞し、子ども神楽は楽しそうに準備を進めていました。月山さんの歌に合わせて多くの子どもたちが踊り、観客も手拍子で盛り上がりました。「ひろしま牡蠣のうた」を生で聞けたことに感動しました。最後には「おいでよ！キタひろ」を月山さんと花田くんが踊り、会場全体が一体となって楽しむ姿が印象的でした。イベントの締めくくりには景品付きの餅まきも行われ、参加者はたくさんの「福」を持ち帰りました。道の駅舞ロードIC千代田は、秋のドライブや観光にぜひ立ち寄りたいスポットです。' where id = 'vUTA0ileTzxu2plfx-Hho';
update content_bodies set title = 'Collaboration Stage of Shoun Gassan and Maitaro Hanada!! #Kitahiroshima Town', description = 'On October 12th and 13th, the ''Autumn Grand Thanksgiving Festival'' was held at the Michi no Eki Mai Road IC Chiyoda. The event featured a variety of performances, including children''s Kagura, a concert by Chiyoda Junior High School''s brass band, and a live stage by the tourism ambassador Shoun Gassan. The brass band, which opened the event, won a gold award at the Hiroshima Prefecture Brass Band Competition for junior high school small ensembles. The children''s Kagura was filled with excitement, showcasing the joy of performing for an audience. Many children danced along to Gassan''s songs, creating a lively atmosphere. A personal highlight was hearing ''Hiroshima Oyster Song'' live, which is a catchy and danceable tune. The event concluded with a performance of ''Oideyo! Kita Hiro'' featuring Gassan and Maitaro Hanada, where Gassan flawlessly danced while singing. The audience, both adults and children, joined in a fun dance, making it a memorable stage. The festival also included a traditional mochi throwing event, allowing attendees to take home good fortune. The Michi no Eki Mai Road IC Chiyoda is a beloved spot, conveniently located right off Chiyoda IC, perfect for autumn drives and sightseeing.' where id = 'u05W03RXpjJiuDDyaAGvT';
update content_bodies set title = '豊平地域の蕎麦の花が咲き始めました✨', description = '豊平地域の蕎麦の花が咲き始めました。白くて小さな花が一面に広がり、毎年9月中旬ごろに見頃を迎えます。品種は豊平産の「とよむすめ」で、道の駅豊平どんぐり村の出入り口や県道40号線沿いにたくさん咲いています。11月16・17日には「そばまつり」が開催され、新そばが振舞われるので、ぜひ食べに来てください。道の駅豊平どんぐり村では、お買い物やお食事、温泉、そば打ち体験も楽しめます。また、道の駅で食べるソフトクリームは特別に美味しいです。' where id = '_qe_EOKNH6Z80Azl22C3W';
update content_bodies set title = 'Buckwheat Flowers Begin to Bloom in Toyohira Region✨', description = 'The buckwheat flowers in the Toyohira region have started to bloom. These small white flowers typically reach their peak around mid-September. The variety is ''Toyomusume,'' which is grown in the Toyohira area. You can see many of these flowers blooming near the entrance of the Toyohira Donguri Village roadside station and along Route 40. A ''Soba Festival'' will be held on November 16-17, where fresh soba will be served, so be sure to come and enjoy it! At the Toyohira Donguri Village roadside station, you can also enjoy shopping, dining, hot springs, and soba-making experiences. There''s something special about the soft-serve ice cream sold at roadside stations!' where id = 'WgzCwIbNKS7e6j8LraTnl';
update content_bodies set title = '八幡高原の赤そばの里が見頃を迎えています', description = '八幡高原の赤そばの里が見頃を迎えています。この場所は、色鮮やかな赤い花が広がる美しい風景が楽しめるスポットです。花の見頃は例年9月中旬から下旬頃で、9月4日の時点で既に花が咲き誇っていました。長野県で品種改良された「高嶺ルビー2011」は、長野県以外で育つのが珍しい赤そばです。車で5分の場所には「赤そば処かりお茶屋」があり、美味しいお蕎麦や天ぷらが楽しめます。毎年11月には新そばを味わうことができ、全国の蕎麦マニアが訪れます。蕎麦の花の美しさを知らなかった方も多いのではないでしょうか。この時期、ぜひ芸北地域の八幡を訪れてみてください。' where id = '39ydG4QSHsFWH3kD-SZKK';
update content_bodies set title = 'The Red Buckwheat Fields of Yahata Highland Are in Full Bloom', description = 'The Yahata Highland''s red buckwheat fields are currently at their peak bloom. This area, known as ''Yahata Highland Red Buckwheat Village,'' showcases a vibrant carpet of red flowers. The best time to see the flowers is typically from mid to late September. As of September 4th, the flowers were already blooming beautifully. The red buckwheat, known as ''Takane Ruby 2011,'' is a rare variety that has been cultivated outside of Nagano Prefecture. Nearby, just a five-minute drive away, is ''Akabosado Kario Chaya,'' where visitors can enjoy delicious soba and tempura. Every November, new buckwheat can be tasted, attracting soba enthusiasts from all over. Many may not realize how beautiful buckwheat flowers can be. This is a great time to visit Yahata in the Geihoku region.' where id = 'Ic7sqmqR146wrViAt6tZx';
update content_bodies set title = 'みえのイマココ旅　「歴史文化×アクティビティ」編', description = '「みえのイマココ旅」は、三重の「イマしかない」「ココしかない」体験を楽しむことを目的とした旅行プランです。「歴史文化」「自然」「食」「ナイト＆モーニング」「サスティナブル」をテーマにした46の体験プランが特設サイトで紹介されており、予約も可能です。「歴史文化」×「アクティビティ」では、復元された斎宮寮の貸切や平安装束の着付け、江戸時代の衣装を着て熊野古道を歩く体験など、三重県の歴史文化に触れる特別な体験が提供されています。' where id = 'iF98Bcp7H_bbTk822gOPv';
update content_bodies set title = 'Mie Imakoko Travel: ''Historical Experiences & Activities'' Edition', description = 'Mie Imakoko Travel invites visitors to experience unique moments in Mie, focusing on ''historical culture,'' ''nature,'' ''food,'' ''night & morning,'' and ''sustainability.'' The initiative offers a new form of travel with 46 experience plans available for reservation on its special website. The ''Historical Culture x Activity'' section features special experiences such as dressing in Heian-era clothing, walking the Kumano Kodo Iseji trail in Edo-period attire, and renting the restored Saiku-ryo building. Various activities are designed to immerse visitors in Mie''s rich historical culture.' where id = 'bffFN7AtcOvjVOf7Y9zh4';
update content_bodies set title = '「ほぼ1年中果物狩りが楽しめる！」豊平どんぐり農園でぶどう狩り', description = '豊平どんぐり農園でぶどう狩りを楽しんできました。8月上旬からなくなり次第終了のぶどう狩りは、40分間食べ放題で、完熟した甘いぶどうをお腹いっぱい食べることができます。約12種類のぶどうが栽培されており、特に職員の好物であるシャインマスカットは完熟により「ゴールデン」になり、非常に甘い味わいです。町内の道の駅にも出荷されており、購入も可能です。ぶどう狩りを希望される方は、豊平どんぐり農園のHPからお問い合わせ・予約をお願いします。営業時間は10時から16時で、果物によって異なる場合があります。' where id = 'NBZixe8x_eYihzfwAmkN8';
update content_bodies set title = 'Enjoy Grape Picking Almost All Year Round at Toyohira Donguri Farm!', description = 'I visited Toyohira Donguri Farm for grape picking, which is available from early August until supplies last. You can enjoy unlimited grapes for 40 minutes, indulging in sweet, ripe grapes to your heart''s content, with the option to take some home. The farm cultivates about 12 varieties of grapes, including Shine Muscat, Queen Nina, Takasumi, Black Beat, and others, creating a colorful experience. The staff''s favorite, Shine Muscat, turns ''golden'' when fully ripe, offering an incredibly sweet taste not found in markets. Grapes are also shipped to local stations like Mai Road IC Chiyoda and Toyohira Donguri Village. For those interested in grape picking, please check the farm''s website for inquiries and reservations. Toyohira Donguri Farm is located in Hiroshima Prefecture and operates from 10 AM to 4 PM, with varying hours depending on the fruit being harvested.' where id = 'OS1JJ27S70e_fCC0qQpJL';
update content_bodies set title = 'あの大人気の「ふりかけ」の原材料！紫色に広がる赤しそ畑に花田舞太郎と観光協会職員とが行ってきました', description = '8月初旬、早朝にも関わらず日差しが照り付ける中、赤しそは太陽の光を受け輝いていました。訪れたのは「三島食品株式会社　北広島町農園事業『紫の里』」。ここでは高品質原料の研究開発や契約産地との栽培加工技術交流が行われており、2020年からは赤しその水耕栽培も始まりました。赤しその刈り取りは6月から9月上旬まで行われ、新鮮な「わき芽」だけが収穫されます。刈り取ったわき芽の香りは爽やかで、これが「ゆかり🄬ふりかけ」になるのです。畑からはふりかけの資料館「楠苑」が見え、全国のふりかけメーカーの商品や製造工程を学ぶことができます。赤しそ畑の見学後は工場へ向かいますので、次回の工場編もお楽しみに！' where id = 'DmNklg3OkqfBG27Pr9ClY';
update content_bodies set title = 'The Ingredients of the Popular Furikake! A Visit to the Purple Shiso Fields', description = 'In early August, despite the scorching sun, the red shiso plants were shining brightly in the fields. The visit was to ''Mishima Foods Co., Ltd. North Hiroshima Town Agricultural Project ''Purple Village''. They focus on research and development of high-quality ingredients and have started hydroponic cultivation of red shiso since 2020. The harvesting of red shiso occurs from June to early September, where only the fresh ''young shoots'' are collected. The sound and vibration of the harvesting machine were quite surprising. The aroma of the freshly cut shoots was refreshing, which is the key ingredient for ''Yukari'' furikake. Nearby, the ''Kusunoki-en'' museum showcases various furikake products from across the country, allowing visitors to learn about the origins and manufacturing processes of furikake. After exploring the fields, the next stop is the factory, so stay tuned for the factory edition!' where id = 'U3oCURCwEnjzu07YvcCqY';
update content_bodies set title = '観光マナー映像「The Etiquette Guide to Fukuoka」（英語版）を制作', description = '福岡市が制作したこの映像は、福岡の観光地を巡りながら日本の文化やマナーを紹介しています。映像は無償で提供されており、必要な方はプロモーション推進課（E-mail：promotion.EPB@city.fukuoka.lg.jp）までご連絡ください。また、福岡市の公式Youtubeチャンネルへの登録もお願いします。' where id = 'rHuRfnK0wet0J9TlhS1LG';
update content_bodies set title = 'The Etiquette Guide to Fukuoka (English Version) Production', description = 'Fukuoka City has produced a video that introduces Japanese culture and manners while touring various tourist spots in Fukuoka. The video is available for free. For those interested, please contact the Promotion Division at promotion.EPB@city.fukuoka.lg.jp. Don''t forget to subscribe to Fukuoka City''s official YouTube channel at https://www.youtube.com/user/Fukuokachannel.' where id = 'wMh_xvloqqulOhTNtwqT0';
update content_bodies set title = 'みえのイマココ旅　「歴史文化×食」編', description = '「みえのイマココ旅」は、三重県の「イマしかない」「ココしかない」体験を楽しむことを目的とした旅行プランです。「歴史文化」「自然」「食」「ナイト＆モーニング」「サスティナブル」をテーマにした46の体験プランが特設サイトで紹介されており、予約も可能です。「歴史文化」×「食」では、国宝の高田本山専修寺での和会席や、松阪の豪商の邸宅での茶事など、三重県の誇る特別な体験が楽しめます。動画では、志摩のプライベートビーチでの食体験や、鳥羽でのリアル海女漁体験、松阪でのプレミアム茶事体験など、さまざまなスポットが紹介されています。' where id = '_7rkkHVJrrAtY5gN7Vqy2';
update content_bodies set title = 'Mie''s Imakoko Travel: ''Cultural History x Food'' Edition', description = 'Mie''s Imakoko Travel invites visitors to experience unique aspects of Mie Prefecture, focusing on ''Cultural History'', ''Nature'', ''Food'', ''Night & Morning'', and ''Sustainability''. The special site features 46 experiential plans that can be reserved, showcasing a new form of travel. The ''Cultural History x Food'' section highlights special experiences such as enjoying a traditional Japanese kaiseki meal at the National Treasure, Takada Honzan Senshu-ji, and participating in a tea ceremony at the former residence of Matsusaka merchants, Iwa Bunko. The video introduces various spots, including a private beach dining experience in Shima, a real ama fishing experience in Toba, and a premium tea ceremony in Matsusaka, among others.' where id = 'gwy5F3ypQOk-eat0kUz3o';
update content_bodies set title = '「限定10食」こだわりの蕎麦をご堪能下さい。', description = '広島県山県郡北広島町蔵迫258-1にある四季乃家 彩蔵では、特別な蕎麦を楽しむことができます。電話番号は0826-72-6361です。定休日は水曜日と木曜日で、冬季は不定休となります。テイクアウトは1ヶ月前から2日前までに予約が必要です。営業時間は11時半から15時（13時までに入店）と、18時から22時（20時までに入店）です。蕎麦ランチの開催日は彩蔵のSNSをチェックしてください。8月の開催日は26日、27日、28日です。ぜひ、限定10食のこだわりのお蕎麦をご堪能ください。' where id = 'fXcxBi9mlsRPDOY66Lfpx';
update content_bodies set title = 'Enjoy Limited 10 Servings of Special Soba', description = 'Shikinoya Ayakura offers a unique soba experience in Hiroshima Prefecture. Located at 258-1 Kurazako, Kitahiroshima Town, you can reach them at 0826-72-6361. The restaurant is closed on Wednesdays and Thursdays, with irregular closures in winter. Takeout orders must be made between one month and two days in advance. Operating hours are from 11:30 AM to 3:00 PM (last entry by 1:00 PM) and from 6:00 PM to 10:00 PM (last entry by 8:00 PM). For the dates of the soba lunch events, please check Ayakura''s social media. In August, the event will be held on the 26th, 27th, and 28th. Don''t miss the chance to enjoy their limited 10 servings of carefully crafted soba!' where id = 'XJLRiOXIoQLXR2kroug_K';
update content_bodies set title = '観光マナー映像「후쿠오카　～즐거운　여행을　위한　에티켓～」（韓国語版）', description = 'この映像は福岡市の公式YouTubeチャンネルで、日本の文化やマナーを紹介しながら福岡の観光地を巡る内容です。映像は無償で提供されており、必要な方はプロモーション推進課（E-mail：promotion.EPB@city.fukuoka.lg.jp）までご連絡ください。' where id = 'HbN25TxMdIdXFieC23cuh';
update content_bodies set title = 'Tourism Etiquette Video ''Fukuoka - Enjoyable Travel Etiquette'' (Korean Version)', description = 'This video, available on Fukuoka City''s official YouTube channel, introduces Japanese culture and manners while showcasing various tourist attractions in Fukuoka. The video is provided free of charge, and those interested can contact the Promotion Division via email at promotion.EPB@city.fukuoka.lg.jp for more information.' where id = '0kETANpP3gecCEI1xYBSl';
update content_bodies set title = '【ふるさとCM大賞NARA2025】天川村「心の深呼吸」', description = '修験道の聖地である天川村で、静寂の中で「心の深呼吸」をするような登山体験を描いた動画を制作しました。山を一歩一歩登るごとに心が洗われ、山頂からの絶景に心が解き放たれる瞬間を表現しています。日常の喧騒を離れ、自分自身と向き合い、心の奥底からリフレッシュできる特別な時間を天川村で見つけてみませんか？' where id = 'sTheQYHEFUnS45SAFvGW2';
update content_bodies set title = 'Furusato CM Award NARA 2025: Amano Village ''Deep Breathing of the Heart''', description = 'This video invites viewers to experience a serene mountain climbing journey in Amano Village, a sacred site of Shugendo. It captures the feeling of cleansing the heart with each step taken up the mountain, culminating in the moment of liberation as one reaches the summit and is greeted by breathtaking views. The video encourages viewers to escape the noise of daily life, confront themselves, and discover a special time for refreshing their spirits deep within in Amano Village.' where id = 'wKikY2aL3z5RymrTAnloj';
update content_bodies set title = '「株式会社広島電鉄」×「三島食品株式会社」コラボ✨「ひろし®」ふりかけのラッピングバスを花田舞太郎と観光協会職員が取材に行ってきました‼', description = '「株式会社広島電鉄」と「三島食品株式会社」のコラボにより、「ひろし®」ふりかけのラッピングバスが登場しました。この人気商品は、広島の名産「広島菜」を使用した混ぜごはんの素で、三島食品の創業者は北広島町出身です。北広島町にはふりかけの資料館「楠苑」や農園があり、夏には赤しそ畑が広がります。このラッピングバスは市内を運行し、地元の食材を広め、地域企業を応援するための熱い想いが込められています。動画には広島電鉄の石田さんと西本さん、三島食品の新宅さんが出演し、猛暑の中で協力してくれました。' where id = 'c9G9ET-ri6jEoiBl8S6m1';
update content_bodies set title = 'Collaboration between Hiroshima Electric Railway and Mishima Foods: Interview on the ''Hiroshi®'' Furikake Wrapped Bus', description = 'A collaboration between Hiroshima Electric Railway and Mishima Foods has resulted in a wrapped bus featuring ''Hiroshi®'' furikake. The bus was covered in a design that highlights this popular product, which is made from high-quality ingredients, including Hiroshima''s famous ''Hiroshima-nama'' pickled greens. The founder of Mishima Foods hails from Kitahiroshima Town, where the ''Kusuen'' furikake museum and agricultural facilities are located. The vibrant red shiso fields flourish in the summer sun, showcasing the deep connection between the company and the region. The bus is now operating in the city, promoting local ingredients and supporting local businesses. The video features staff from both companies, who contributed despite the summer heat.' where id = 'jmp08IjNeM5zGFQX-LeRg';
update content_bodies set title = 'お正月神楽【天の岩戸／山王神楽団】', description = 'お正月の特別企画として、神楽の演目『天の岩戸』を公開します。この演目は、山王神楽団が山末神社の神楽殿で特別に舞ったものです。雪が降った寒い時期にも関わらず、協力していただき感謝しています。動画はお正月にふさわしい参拝シーンから始まります。最後にはプレゼント企画も用意していますので、ぜひ最後までお楽しみください。

配信は2023年12月31日（日）PM12：00から開始します。撮影日は2023年12月中旬で、制作・企画は北広島町商工観光課と北広島町観光協会です。プレゼント企画についてのお問い合わせは0826-72-6908まで。

『天の岩戸』の物語では、須佐之男命の乱行に天照大御神が怒り、天の岩戸に閉じ込められたことで高天原は暗闇に包まれました。八百万の神々が神楽を奏で、天照大御神が岩戸を少し開けた際、手力男命が岩戸を押し開き、光と平和が戻ったという内容です。

山王神楽団は、明治中期に地元の神社祭りのために発足し、昭和25年に現在の名称に改名されました。近年では、ロシアのサンクトペテルブルク建都300周年や日韓芸能交流公演に参加し、演技の向上と伝承に努めています。' where id = 'yccEZtLf6kPjzVbCf59o1';
update content_bodies set title = 'New Year Kagura: Amano Iwato / Sanno Kagura Group', description = 'As a special project for the New Year, we are presenting a Kagura performance. The featured play is ''Amano Iwato,'' perfect for the New Year. The Sanno Kagura Group performed this specifically for the filming at the Kagura Hall of Yamazume Shrine. Despite the cold weather after snowfall, we appreciate their cooperation. The video begins with a scene of worship, fitting for the New Year. There is also a gift project at the end, so please enjoy it until the very end.

★ Streaming starts on December 31, 2023, at 12:00 PM
《Filming Date》Mid-December 2023
《Production and Planning》Kita Hiroshima Town Commerce and Tourism Division, Kita Hiroshima Town Tourism Association
《For inquiries about the gift project》0826-72-6908

《Amano Iwato》
In Takamagahara, Amaterasu Omikami became angry with Susanoo no Mikoto''s repeated misdeeds and shut herself in the Amano Iwato, plunging Takamagahara into darkness. As evil gods spread chaos, the eight million gods played Kagura in front of the rock door. When Amaterasu slightly opened the door, Tajikarao no Mikoto pushed it open, welcoming her back and restoring light and peace to the world.

《Sanno Kagura Group》
Founded in the mid-Meiji period to dedicate Kagura to the local Yamazume Shrine, the group was originally called ''Shimohonji Kagura Group.'' In 1950, it was renamed ''Sanno Kagura Group'' after the deity enshrined at the shrine. Recently, they participated in the 300th anniversary of St. Petersburg and performed at the National Theatre in collaboration with Korean artists. They continue to strive for excellence in their performances and the preservation of their art.' where id = 'hxnQaHCegCbKwQcDm7fM7';
update content_bodies set title = '北広島町の風景～稲刈り～', description = '9月初旬から稲刈りシーズンが始まります。北広島町では、地域ごとに標高が異なるため、稲刈りの時期も異なります。今回の動画は旧千代田町の本地地区を紹介しています。稲刈りが終わると、各地域で秋の実りに感謝する「奉納神楽」が行われます。' where id = '8JWVTSp6917t8zEApieBK';
update content_bodies set title = 'Scenery of Kitahiroshima Town - Rice Harvesting', description = 'The rice harvesting season begins in early September. In Kitahiroshima Town, the timing of the harvest varies by region due to differences in elevation. This video features the Honchi area of the former Chiyoda Town. After the rice is harvested, local communities hold ''Hounou Kagura'' to express gratitude for the autumn harvest.' where id = 'IpthttXEKUfbOYwPSEAF0';
update content_bodies set title = '※5月11日まで延長！　第3回阿蘇ちょうちん祭始まる～阿蘇門前町ちょうちん散歩～', description = '好評により、阿蘇ちょうちん祭が5月11日まで延長されました。2025年4月12日から20日まで、熊本県阿蘇市の阿蘇神社近くの阿蘇門前町商店街で開催されます。約2,000個のちょうちんが淡い明かりで夜道を照らします。点灯時間は午後6時から午後10時までです。詳細は阿蘇門前町商店街の地図や、ちょうちん祭の公式サイトをご覧ください。会場では、協賛者の名前が入ったちょうちんも飾られます。' where id = 'WtuBJfyz9eoRaXnQ-YKYt';
update content_bodies set title = 'Extension until May 11! The 3rd Aso Lantern Festival Begins - Aso Monzen Town Lantern Walk', description = 'Due to popular demand, the event has been extended until May 11! The 3rd Aso Lantern Festival is taking place from April 12 to April 20, 2025, in Aso City, Kumamoto Prefecture, around the Aso Monzen Town shopping district near Aso Shrine. Approximately 2,000 lanterns illuminate the night paths with their soft glow. Lighting hours are from 6 PM to 10 PM. For more information, visit the Aso Monzen Town shopping district map and the Aso Lantern Festival website, where sponsored lanterns with names will be displayed at the venue.' where id = 'SLgqM0aLFneIBo10hV2P-';
update content_bodies set title = 'グリスロヴィレッヂ　グリーンスローモビリティーカー', description = '阿蘇の草原を小型電動車「グリーンスローモビリティ（グリスロ）」で駆け抜ける体験型ガイドツアーです。' where id = 'VMH-Vc574kV2krQYuPgM1';
update content_bodies set title = 'Greslo Village Green Slow Mobility Car', description = 'Experience a guided tour through the Aso grasslands in a small electric vehicle known as ''Green Slow Mobility (Greslo)''.' where id = 'Hi1vIAMMRFcMefaxjUf8I';
update content_bodies set title = '熊本県阿蘇の絶景ポイント「大観峰」に行った気になれる動画！', description = '阿蘇随一のビュースポット「大観峰」では、360度の大パノラマが楽しめます。この動画では、駐車場から「大観峰展望所」までの歩行の様子が収められています。展望所では「パラグライダー体験」も行われており、動画でも美しい景色が楽しめますが、ぜひ実際に訪れてこの絶景を体験していただきたいと思います。' where id = '4DHLVUTE0oDcyYWRfEgbs';
update content_bodies set title = 'Aso''s Scenic Spot: Experience ''Daikanbo'' Through Video!', description = 'Daikanbo is a premier viewpoint in Aso, Kumamoto, offering a stunning 360-degree panorama. The video showcases a walk from the parking area to the Daikanbo observation deck. At the observation deck, paragliding experiences were also available. While the video captures the beautiful scenery, visiting in person is highly recommended to fully enjoy this breathtaking view.' where id = 'Zp1ApJux-gF95YCwDgxhP';
update content_bodies set title = '2023.5.14「新庄のはやし田」大花田植', description = '2023年5月14日（日）に「新庄のはやし田」大花田植が開催されます。会場は北広島町大朝5111付近で、大朝鳴滝渓谷の入口に位置しています。イベントは正午から午後3時頃まで行われます。詳細については観光情報サイト「ぐるっと、きたひろしま」をご覧ください。' where id = 'wap5D7Z98lctf13000SsK';
update content_bodies set title = '2023.5.14 ''Shinjo no Hayashida'' Grand Rice Planting', description = 'On May 14, 2023 (Sunday), the ''Shinjo no Hayashida'' Grand Rice Planting event will be held. The venue is located near 5111 Oasa, Kitahiroshima Town, at the entrance of the Oasa Narutaki Valley. The event will take place from noon until around 3 PM. For more details, visit the tourism information site ''Gurutto, Kitahiroshima''.' where id = 'NpRO6NMJI49dzmKvbX8YG';
update content_bodies set title = 'この町は、冬の楽しみ方を知っている。', description = '北広島町の映像制作会社うえひろやスタジオと観光協会が協力し、「冬の北広島町」をPRする動画を制作しました。テーマは「冬の北広島町には、描きたくなる景色がある。」で、短編と長編の2種類があります。短編（short01～short03）は気軽に楽しめるポップな内容で、長編にはないシーンも多く含まれています。長編はドラマ風の構成で、スランプに陥った女性画家が冬の北広島町を訪れ、冬ならではのアクティビティや絶景に触れながら心の変化を描いています。彼女は再び絵を描けるようになるのでしょうか。爽快な音楽と共に、彼女の心境と美しい冬の景観に注目してください。制作期間は2022年12月から2023年3月までです。' where id = 'srQrE0T6f73CGyFa6wd39';
update content_bodies set title = 'This Town Knows How to Enjoy Winter', description = 'A video project promoting ''Winter in Kitahiroshima Town'' has been created by the local video production company Uehiroya Studio and the tourism association. The theme highlights the picturesque winter scenery that inspires creativity. The project includes both short and long videos. The short videos (short01 to short03) are designed to be light-hearted and easy to watch, featuring scenes not included in the long version. The long video presents a dramatic narrative showcasing the unique winter charm of Kitahiroshima Town. It follows a female painter experiencing a creative slump who finds inspiration during her visit to the town, engaging in winter activities and witnessing breathtaking landscapes. The video captures her emotional journey alongside beautiful winter scenery, accompanied by uplifting music. The project was developed from December 2022 to March 2023.' where id = 'f_pxCgWiKTVzLbu9nme10';
update content_bodies set title = '冬の北広島町には、描きたくなる景色がある。', description = '北広島町の映像制作会社うえひろやスタジオと観光協会が共同で「冬の北広島町」をPRする動画を制作しました。長編は、冬の北広島町の魅力をドラマ仕立てで表現しています。物語は、スランプに陥った女性画家がLINEのメッセージを受け取り、冬の北広島町を訪れるところから始まります。彼女は不安を抱えつつも、冬ならではのアクティビティや美しい景色に心を動かされ、再び絵を描けるようになるのかが描かれています。短編は、より軽快でポップなテイストで、長編にはないシーンも多く含まれています。制作は2022年12月から2023年3月にかけて行われ、スキー場や温泉、伝統芸能など、地域の魅力を紹介しています。' where id = 'o-C-n8_TNLQIpN3rIEg2u';
update content_bodies set title = 'Winter in Kitahiroshima Town Offers Inspiring Scenery', description = 'A video project promoting ''Winter in Kitahiroshima Town'' has been created by the local video production company Uehiroya Studio in collaboration with the tourism association. The long version features a dramatic narrative showcasing the unique winter charm of Kitahiroshima. The story follows a female painter experiencing a creative slump who receives a message prompting her to visit Kitahiroshima in winter. Despite her initial anxiety, she becomes captivated by winter activities and breathtaking landscapes, leading her to rediscover her artistic inspiration. The short version is designed to be light-hearted and engaging, featuring scenes not included in the long version. The project was produced between December 2022 and March 2023, highlighting various local attractions, including ski resorts, hot springs, and traditional cultural performances.' where id = 'SiQrwo2RdmBhWJwq6wjwM';
update content_bodies set title = '【北広島町】龍頭山～車で９合目まで行く予定だったのに、雪で通れなかったので歩いて登りました～', description = '2023年1月31日、龍頭山の9合目まで車で行く予定でしたが、雪のため通行できず、登山道を歩いて登りました。この時期にしか見ることのできない美しい景色が広がっていました。龍頭山は広島県北広島町に位置し、山頂からは360度の大展望が楽しめ、中国地方の山々や遠くの瀬戸内海まで見渡せます。9合目までは車道があり、元々修験者が登る山として知られています。途中の駒ヶ滝は特に圧巻です。' where id = 'nQYX_9ZcMn9QBVzoBt-DI';
update content_bodies set title = 'Ryutozan Mountain in Kitahiroshima Town: Planned to Drive to the 9th Station but Hiked Due to Snow', description = 'On January 31, 2023, I intended to drive to the 9th station of Ryutozan Mountain, but the road was blocked by snow, so I hiked instead. The scenery visible only during this season was breathtaking. Ryutozan Mountain, located in Kitahiroshima Town, Hiroshima Prefecture, offers a panoramic view from its summit, allowing one to see the mountains of the Chugoku region and even the Seto Inland Sea in the distance. There is a road leading to the 9th station, and the mountain has historical significance as a place for ascetic practitioners. The Koma Waterfall along the way is particularly impressive.' where id = 'RgSBEWMDhkuK5Ri5adl08';
update content_bodies set title = '2023年ミヤマキリシマ 仙酔峡', description = '今年も仙酔峡のミヤマキリシマが美しく咲きました。撮影当日は雲海が発生し、眼下に広がる雲が印象的でした。また、仙酔峡からは「中岳」や「高岳」への登山も可能で、仙酔尾根ルートを利用できます。ミヤマキリシマの見頃は5月中旬から5月下旬頃です。仙酔峡の住所は熊本県阿蘇市一の宮町宮地（〒869-2612）で、JR阿蘇駅から車で15分の距離にあります。' where id = 'xmbiwzXwMzigL4-H-tyU8';
update content_bodies set title = 'Miyama Kirishima at Sensuikyo in 2023', description = 'The Miyama Kirishima flowers have bloomed beautifully at Sensuikyo this year. On the day of the shoot, a sea of clouds was present, creating a stunning view below. Additionally, visitors can hike to Nakadake and Takadake from Sensuikyo via the Sensui Ridge route. The blooming season for Miyama Kirishima typically occurs from mid-May to late May. Sensuikyo is located at 869-2612, Kumamoto Prefecture, Aso City, Ichinomiya Town, Miyaji, just a 15-minute drive from JR Aso Station.' where id = 'Yzii-CKFMKvD0yfP4a-ux';
update content_bodies set title = '【高画質】阿蘇山観音まつり', description = '令和5年4月13日、阿蘇市黒川の西巌殿寺で「阿蘇山観音まつり」が行われ、多くの参拝者が山伏姿の行者らによる荒行「火渡り」と「湯立て」に参加しました。ヒノキの葉で作られた護摩壇に火が入ると、行者たちはお経を唱え、願いごとを書いた護摩木を火に投げ入れ、無病息災を祈願しました。その後、一般の参拝者は火が弱まった後、行者に続いて灰の上を裸足で歩き、最後に煮えたぎった湯しぶきを浴びる「湯立て」に参加し、無病息災を祈りました。この祭りは、西南戦争で殉職した住職、厨亮俊僧の命日である4月13日に毎年行われています。' where id = 'gCwXiVbx7z4gl5a0d-Xst';
update content_bodies set title = 'Aso Mountain Kannon Festival', description = 'On April 13, 2023, the Aso Mountain Kannon Festival was held at the Seiganji Temple in Kurokawa, Aso City. Many worshippers gathered to participate in the rigorous rituals performed by Yamabushi practitioners, including ''fire walking'' and ''yudate'' (boiling water ritual). The ceremony began with the lighting of a goma altar made from cypress leaves, where Yamabushi chanted sutras and threw wooden sticks inscribed with wishes into the flames, praying for health and safety. After the fire had diminished, participants walked barefoot over the ashes, following the Yamabushi, and concluded with the ''yudate'' ritual, where they were splashed with boiling water, praying for a year free from illness. This festival is held annually on April 13 to commemorate the deceased priest of Seiganji Temple, Churi Ryoshun, who died in the Satsuma Rebellion.' where id = 'POkwsvX0kjPtXhcTHk5e4';
update content_bodies set title = '奉納神楽：太鼓や笛の音が響きわたる季節到来です', description = '秋になると各地域で奉納神楽が行われます。コロナ禍で中止された地域もありましたが、地域行事は徐々に戻りつつあります。北広島町には約70団体の神楽団や保存会が存在します。神楽は秋の実りに感謝し、神話や伝説を取り入れた舞いで、島根県西部の石見地方から伝わった「旧舞」と、戦後に伝わった「新舞」が合流し、地域の民俗芸能として受け継がれています。特に山県郡や安芸高田市など芸北地域は神楽が盛んなことで知られています。小原神楽団は約280年前に設立され、昭和61年に無形文化財に指定され、現在も伝統を守り続けています。' where id = 'rEpLpsBP37g8puR3LHlR3';
update content_bodies set title = 'The Season of Offering Kagura with Drums and Flutes Has Arrived', description = 'As autumn arrives, various regions hold offering Kagura performances. Although some areas were unable to hold these events due to the COVID-19 pandemic, local festivities are gradually returning. In Kitahiroshima Town, there are about 70 Kagura groups and preservation societies. Kagura is a traditional performance that incorporates myths and legends to express gratitude for the autumn harvest. It has evolved from the ''old dance'' of the Iwami region in western Shimane Prefecture and the ''new dance'' that spread after World War II. The Obara Kagura group, which has been practicing for about 280 years, continues to uphold the tradition and was designated as an intangible cultural asset in 1986. They actively practice to preserve their local performing arts.' where id = 'PFpcECQVeeMnJj2-kiWqf';
update content_bodies set title = '新緑、大朝のテングシデ群落（2022/5/6）', description = '2022年5月6日現在、大朝のテングシデ群落が新緑の見頃を迎えています。この国の天然記念物の中で、自然に癒されてみませんか？また、近くの天意の里ハーブガーデンでのハーブランチもおすすめです。撮影日は2022年5月6日で、場所は北広島町田原の大朝のテングシデ群落です。音楽は甘茶の音楽工房によるものです。詳細は北広島町観光協会のウェブサイト「ぐるっと、きたひろしま」をご覧ください。' where id = 'L4lio0ujXbdaGsW3_U2xl';
update content_bodies set title = 'Fresh Greenery at the Tengu Shide Grove in Oasa (May 6, 2022)', description = 'As of May 6, the Tengu Shide Grove in Oasa is at its peak of fresh greenery. Why not relax among this national natural monument? Additionally, we recommend enjoying a herb lunch at the nearby Ten''i no Sato Herb Garden. 

Date of Photography: May 6, 2022
Location: Oasa Tengu Shide Grove, Kitahiroshima Town
BGM: Music from Amacha Music Studio

For more information, visit the Kitahiroshima Town Tourism Association website: ''Gurutto, Kitahiroshima'' http://kitahiro.jp/' where id = 'Z8uzrhwKy8F-dtJqK4Uhf';
update content_bodies set title = '京都・貴船、伝統と自然 - 水の神社と川床', description = '自然の音や水の流れに触発されたいなら、京都の貴船を訪れてみてはいかがでしょうか。ここは、伝統と自然の美しさが融合した静かな体験を提供する場所です。' where id = '2K3cxgAjFFHEk3brAqpPh';
update content_bodies set title = 'Kyoto Kibune, Tradition and Nature - The Sacred Shrine of Water and Kawadoko', description = 'Kibune in Kyoto offers a serene experience, inviting visitors to immerse themselves in the soothing sounds of nature and flowing water. It is a place where tradition meets the beauty of the natural environment.' where id = 'XmPx0FHrWZv20jJdx_rZG';
update content_bodies set title = '吉川氏ゆかりの地', description = '北広島町豊平地域には、戦国時代にこの地を支配した吉川氏に関連する史跡が数多く残っており、武将の足跡や民衆の息吹を感じることができます。吉川元春館跡歴史公園は、吉川元春の隠居所として築かれた館の跡で、多くの建物跡やトイレ、井戸、庭園が見つかっています。復元された台所建物では、カマドや炉を使った煮炊きが体験できます。また、戦国の庭歴史館は、吉川氏城館跡全体を案内する展示施設で、出土品や中世の生活に関する展示、甲冑の試着体験も行えます。' where id = 'I6RgM6q6X_Brs8chfF4MG';
update content_bodies set title = 'Sites Related to the Yoshikawa Clan', description = 'In the Toyohira region of Kitahiroshima Town, numerous historical sites related to the Yoshikawa clan, who ruled the area during the Sengoku period, remain. Visitors can feel the presence of the samurai and the local populace. The Yoshikawa Motoharu Residence Ruins Historical Park features the remains of a residence built for Yoshikawa Motoharu, including various building foundations, toilets, wells, and gardens. A restored kitchen building allows for cooking demonstrations using traditional stoves. The Sengoku Garden Historical Museum serves as an exhibition facility that guides visitors through the entire site of the Yoshikawa clan''s castle. It showcases artifacts unearthed from the site, displays about medieval life, and offers experiences such as trying on armor. For more information, visit the official website.' where id = 'yAs0dv8GG0kD6i7m4FhU0';
update content_bodies set title = '阿蘇の春', description = '阿蘇の春は、自然の美しさを際立たせる活気ある季節です。この地域では、高菜折や火振り神事、節分祭などの独特な文化イベントが行われ、春の活動の豊かなタペストリーを形成しています。これらの伝統は、地域社会と季節の移り変わりとのつながりを強調し、阿蘇を春の訪れを体験する特別な場所にしています。' where id = '7GnAlZ1lNPuPM_u8_CQfE';
update content_bodies set title = 'Spring in Aso', description = 'Spring in Aso is a vibrant season that showcases the beauty of nature. The region is known for its unique cultural events, such as the Takana folding, the Hi-furi Shinto ritual, and the Setsubun Festival, which all contribute to the rich tapestry of springtime activities. These traditions highlight the connection between the local community and the changing seasons, making Aso a special place to experience the arrival of spring.' where id = 'nqMF-WbezzaZUBDLXGS1y';
update content_bodies set title = 'きたひろスケッチ⑦ 「万徳院跡歴史公園」', description = '北広島町観光協会の職員2人が町内のスポットをスケッチする「きたひろスケッチ」企画は、新しい観光の形を提案しています。芸大出身で休日にはアート制作に励む島田さんと、絵を描くのが好きな日下さんが担当しています。今回は第7回目として「万徳院跡歴史公園」を描きます。この動画は地元ケーブルテレビ「きたひろネット」で放送されたもののアーカイブで、より多くの人に見てもらうためにYouTubeにアップされました。' where id = '6TKBGnYK5IeTavVvbvpgM';
update content_bodies set title = 'Kitahiro Sketch #7: Mantokuin Ruins Historical Park', description = 'The ''Kitahiro Sketch'' project, proposed by two staff members of the Kitahiroshima Town Tourism Association, involves sketching various local spots as a new form of tourism. The artists, Shimada, a graduate of an art university who engages in various art projects on weekends, and Kusaka, who enjoys drawing, are responsible for this initiative. In this seventh installment, they will sketch the Mantokuin Ruins Historical Park. This video is an archive of a broadcast from the local cable television ''Kitahiro Net'' and has been uploaded to YouTube to reach a wider audience.' where id = 'xYeqZpfaDmSm8U_fToo-c';
update content_bodies set title = '阿蘇の秋', description = '阿蘇の秋は、自然の美しさを際立たせる鮮やかな季節です。この地域は、象徴的なそらふねの桟橋を含む絵のような風景で知られています。訪れる人々は、地域の料理であるたかな飯を楽しむことができ、食の体験も充実しています。さらに、阿蘇にはリラックスできる温泉もあり、素晴らしい秋の風景の中でくつろぎたい人々にとって完璧な目的地となっています。' where id = '1XolE1fr5lvCtAP0yjGsO';
update content_bodies set title = 'Autumn in Aso', description = 'Aso''s autumn is a vibrant season that showcases the beauty of nature. The area is known for its picturesque landscapes, including the iconic Sorafune pier. Visitors can enjoy local delicacies such as Takana rice, which adds to the culinary experience of the region. Additionally, Aso offers relaxing hot springs, making it a perfect destination for those looking to unwind amidst the stunning autumn scenery.' where id = '1qIBh4lX7PDj-ysbUoUzY';
update content_bodies set title = 'きたひろスケッチ⑤ 「大朝 上ヶ原」', description = '「きたひろスケッチ」は、北広島町観光協会の職員2人が町内の観光スポットをスケッチする企画で、新しい観光の形を提案しています。担当するのは、芸大出身で休日にアート制作に励む島田さんと、絵を描くのが好きな日下さんです。今回は第5回目で、「大朝 上ヶ原」を描きます。この動画は地元ケーブルテレビ「きたひろネット」で放送されたもののアーカイブで、より多くの人に見てもらうためにYouTubeにアップされました。' where id = '1u2eZrNTlmgGMP_EKHY9g';
update content_bodies set title = 'Kitahiro Sketch #5: Oasa Kamigahara', description = 'The ''Kitahiro Sketch'' project, initiated by two staff members of the Kitahiroshima Town Tourism Association, involves sketching various local spots as a new form of tourism. The artists, Shimada, a graduate of an art university who engages in various art projects during his days off, and Kusaka, who enjoys painting, are responsible for this initiative. This is the fifth installment, focusing on ''Oasa Kamigahara.'' The video is an archive of a broadcast from the local cable television ''Kitahiro Net'' and has been uploaded to YouTube to reach a wider audience.' where id = 'krlXUe396luSWvJ6N3S6p';
update content_bodies set title = 'きたひろスケッチ④ 「古保利薬師 山門」', description = '「きたひろスケッチ」は、北広島町観光協会の職員2人が町内の観光スポットをスケッチする企画で、新しい観光の形を提案しています。担当するのは、芸大出身で休日にアート制作に励む島田さんと、絵を描くのが好きな日下さんです。今回は第4回目として「古保利薬師 山門」を描きます。この動画は地元のケーブルテレビ「きたひろネット」で放送されたもののアーカイブで、より多くの人に見てもらうためにYouTubeにアップされました。' where id = 'MH5PdOs1YpzUk_7Yh-BHw';
update content_bodies set title = 'Kitahiro Sketch ④ ''Kobori Yakushi Mountain Gate''', description = 'The ''Kitahiro Sketch'' project, initiated by two staff members of the Kitahiroshima Town Tourism Association, involves sketching various local spots as a new form of tourism. The artists, Shimada, a graduate of an art university who engages in various art projects during weekends, and Kusaka, who enjoys drawing, are responsible for this initiative. In this fourth installment, they will sketch the ''Kobori Yakushi Mountain Gate.'' This video is an archive of a broadcast from the local cable television ''Kitahiro Net,'' and has been uploaded to YouTube to reach a wider audience.' where id = '63X3D4v8T_gXxTI2KvrRL';
update content_bodies set title = 'きたひろスケッチ③ 「聖湖」', description = '「きたひろスケッチ」は、北広島町観光協会の職員2人が町内のスポットをスケッチする企画で、新しい観光の形を提案しています。担当するのは芸大出身の島田さんで、休日には様々なアート作りに励んでいます。今回は第3回目で、「聖湖」を描くことに焦点を当てています。この動画は地元ケーブルテレビ「きたひろネット」で放送されたもののアーカイブで、より多くの人に見てもらいたいという思いからYouTubeにアップされました。' where id = 'pSuQnUMMidGjYjKRrwhQ7';
update content_bodies set title = 'Kitahiro Sketch ③ ''Seiko''', description = 'The ''Kitahiro Sketch'' project, initiated by two staff members of the Kitahiroshima Town Tourism Association, involves sketching various local spots as a new form of tourism. This time, the artist is Shimada, a graduate of an art university who dedicates his weekends to creating various forms of art. This is the third installment of the series, focusing on ''Seiko.'' The video is an archive of a broadcast from the local cable television ''Kitahiro Net,'' and has been uploaded to YouTube to reach a wider audience.' where id = 'Rn89ypDJdGLcGChulfh2T';
update content_bodies set title = 'きたひろスケッチ② 「龍頭山 駒ヶ滝」', description = '「きたひろスケッチ」は、北広島町観光協会の職員2人が町内の観光スポットをスケッチする企画で、新しい観光の形を提案しています。芸大出身の島田さんと、絵を描くのが好きな日下さんが担当しています。今回は第2回目で、「龍頭山 駒ヶ滝」を描く様子が紹介されます。この動画は地元のケーブルテレビ「きたひろネット」で放送されたもののアーカイブで、より多くの人に見てもらうためにYouTubeにアップロードされました。' where id = 'oL1ui0SxPTsCiyqcTuXRg';
update content_bodies set title = 'Kitahiro Sketch ② ''Ryutozan Komagataki''', description = 'The ''Kitahiro Sketch'' project proposes a new form of tourism, where two staff members from the Kitahiroshima Town Tourism Association sketch various spots within the town. The artists involved are Shimada, a graduate of an art university who dedicates his weekends to various art projects, and Kusaka, who enjoys drawing. This is the second installment of the series, focusing on ''Ryutozan Komagataki.'' The video is an archive of a broadcast from the local cable television ''Kitahiro Net,'' and has been uploaded to YouTube to reach a wider audience.' where id = 'Y1bRyLACFWpy8IF0yz9jM';
update content_bodies set title = 'きたひろスケッチ①「大朝のテングシデ群落」', description = '「きたひろスケッチ」は、北広島町観光協会の職員2人が町内の観光スポットをスケッチする新しい観光の形を提案する企画です。担当するのは、芸大出身で休日にアート制作に励む島田さんと、絵を描くのが好きな日下さんです。今回は第1回目として「大朝のテングシデ群落」を描きます。この動画は地元ケーブルテレビ「きたひろネット」で放送されたもののアーカイブで、より多くの人に見てもらいたいとの思いからYouTubeにアップされました。' where id = 'yp3eHvr9zaLHlXr9jUZeW';
update content_bodies set title = 'Kitahiro Sketch #1: The Tengushide Grove in Oasa', description = 'The ''Kitahiro Sketch'' project is an initiative by two staff members of the Kitahiroshima Town Tourism Association, who sketch various local spots as a new form of tourism. The artists involved are Shimada, a graduate of an art university who dedicates his weekends to creating various artworks, and Kusaka, who enjoys painting. This is the first episode, where they will sketch the Tengushide grove in Oasa. The video is an archive of a broadcast from the local cable television ''Kitahiro Net'' and has been uploaded to YouTube to reach a wider audience.' where id = 'acyaoal-u5_rZDrGlmnj7';
update content_bodies set title = '【阿蘇デートに！】キャンドル制作体験（ハンドメイド雑貨KHO）', description = '阿蘇市内牧にある雑貨屋「ハンドメイド雑貨KHO」では、キャンドル制作体験が楽しめます。店内にはドライフラワーが飾られており、自分の好みに合わせて選び、キャンドルを飾り付けることができます。この体験は観光やデートにぴったりです。' where id = '7pt_9NYZloWy8ASiDJX6-';
update content_bodies set title = 'Candle Making Experience in Aso!', description = 'At the handmade goods store ''Handmade Goods KHO'' in Aso, you can enjoy a wonderful candle-making experience! You can choose from a variety of dried flowers displayed in the store to decorate your candle according to your preferences. This activity is perfect for sightseeing or a date!' where id = '_BwGyvTnfLn1eyBDnw1wV';
update content_bodies set title = '花田舞太郎誕生物語', description = '2015年2月に生まれた北広島町のイメージキャラクター「花田舞太郎」の誕生物語を紹介します。関係者の話を交えながら、彼が愛され続けてきた理由や誕生当時の貴重なエピソードを紐解いていきます。また、2021年2月10日から23日まで「花田舞太郎写真展～うし年＆お誕生日 記念～」が開催されます。一般公募で集まった写真や彼の活動を振り返る歴史が展示される予定です。会場はショッピングセンターサンクスの1階（北広島町有田1532）で、2月16日（火）は店休日となりますのでご注意ください。' where id = 'P1vsYDdKhfNi2quTBA5sN';
update content_bodies set title = 'The Birth Story of Maitaro Hanada', description = 'Maitaro Hanada, the image character of Kitahiroshima Town, was born in February 2015. This summary explores his birth story, featuring anecdotes from those involved and sharing precious tales from his early days. Additionally, a photo exhibition titled ''Maitaro Hanada Photo Exhibition - Year of the Ox & Birthday Commemoration'' will be held from February 10 to 23, 2021. The exhibition will showcase photos collected from the public and highlight his history and activities. The venue is located on the first floor of Shopping Center Thanks (1532 Arita, Kitahiroshima Town). Please note that the store will be closed on February 16 (Tuesday).' where id = 'ozRzfCKWNKY55wqUXuWyZ';
update content_bodies set title = '〈前編〉商業部会視察研修旅行～きたひろの酒と料理のマリアージュ💛ツアー～', description = '北広島町商工会が主催する商業部会視察研修旅行に参加しました。このツアーは、北広島町のお酒と地元料理のマリアージュをテーマにしており、町内の酒蔵を巡ります。地元の方でも知らないお酒やグルメを紹介する内容です。レポーターは商工観光課の中野愛さんで、カメラマンと編集は観光協会の職員が担当しています。詳細はYouTubeチャンネルでご覧いただけます。' where id = 'x9Z32lz-OWR8-J2xVFMSl';
update content_bodies set title = 'Commercial Department Study Tour Part 1: Kitahiroshima''s Sake and Cuisine Pairing Tour 💛', description = 'I participated in a study tour organized by the Kitahiroshima Town Chamber of Commerce, focusing on the pairing of local sake and cuisine. This first part of the tour explores various sake breweries in the town, introducing local drinks and gourmet dishes that even some residents may not be familiar with. The report is presented by the Commerce and Tourism Division (Aiko Nakano), with filming and editing by tourism association staff. For more details, visit the YouTube channel linked in the description.' where id = 'GXX_jzGNNkgJ9DYmi_K7N';
update content_bodies set title = '〈後編〉商業部会視察研修旅行～きたひろの酒と料理のマリアージュ💛ツアー～', description = '北広島町商工会が主催する商業部会視察研修旅行に参加し、地元の酒と料理の組み合わせをテーマに町内の酒蔵を巡りました。後編では、町内の方でも知らなかったお酒やグルメを紹介します。レポーターは商工観光課の中野愛さんで、カメラマンと編集は観光協会の職員が担当しています。詳細はYouTubeチャンネルや紹介された店舗のリンクを参照してください。' where id = 'JoA8jhN8SA4SvgI5v2YxG';
update content_bodies set title = 'Part 2: Commercial Association Study Tour - Kitahiroshima''s Sake and Cuisine Pairing Tour 💛', description = 'I participated in the Kitahiroshima Town Commercial Association''s study tour, which focused on the pairing of local sake and cuisine. This tour included visits to various sake breweries in the town. In this second part, we introduce some lesser-known sake and gourmet dishes that even locals may not be aware of. The report is presented by the Commerce and Tourism Division (Aiko Nakano), with filming and editing by tourism association staff. For more details, check out the YouTube channel and links to the featured establishments.' where id = 'BK7AYxlckt6QuiHcj5g-m';
update content_bodies set title = '【おすすめ観光コース第2弾！】バスで行くパワースポット巡りと内牧温泉街', description = '阿蘇はレンタカーがないと観光できないイメージがありますが、このルートを利用すればバスで観光が可能です。このガイドは阿蘇観光の参考になります。旅程には、JR阿蘇駅、阿蘇プラザホテル、ASO MILK FACTORY、福の神大黒天、内牧商店街の散策などが含まれています。さらに、昭和館チロリン村、Patisserid`Aso MIYUKI、いまきん食堂、めしのやまいち、内牧菅原神社を訪れ、最後に阿蘇内牧音泉湯楽で締めくくります。阿蘇ならではのユニークな体験と地元の味を楽しんでください。' where id = '2SyQii_8ivQMyN43G_bNz';
update content_bodies set title = 'Recommended Sightseeing Course Part 2! Power Spot Tour by Bus and Inner Makik Hot Spring Town', description = 'Aso is often thought to require a rental car for sightseeing, but this route allows you to explore by bus. This guide provides a great reference for your Aso sightseeing plans. The itinerary includes stops at various attractions such as JR Aso Station, Aso Plaza Hotel, Aso Milk Factory, Fukunokami Daikokuten, and a stroll through the Inner Makik shopping street. Other highlights include the Showa-kan Chirin Village, Patisserie d''Aso MIYUKI, Imakin Shokudo, and the Inner Makik Sugawara Shrine, concluding with a visit to Aso Inner Makik Onsen Yura. Enjoy the unique experiences and local flavors that Aso has to offer!' where id = 'P0hSkLFJP3jpJHCA6cCOL';
update content_bodies set title = '阿蘇キャンドルナイトin乙姫', description = '令和3年12月4日から、阿蘇市乙姫のコスギリゾートで「阿蘇キャンドル2021 in 乙姫」が開催されています。このイベントは、クリスマスシーズンに合わせて行われ、訪れる人々に特別な雰囲気を提供します。阿蘇の美しい自然の中で、キャンドルの灯りが幻想的な空間を演出し、デートや特別なひとときを過ごすのに最適な場所となっています。' where id = 'iwVGtqTrC0SI52rY8C7Gp';
update content_bodies set title = 'Aso Candle Night in Otohime', description = 'The Aso Candle 2021 event is being held at Kosugi Resort in Otohime, Aso City, starting from December 4, 2021.' where id = 'rQtgf4Zg9UzmVZ88EFOsO';
update content_bodies set title = '【北広島町】Ｅ-ＢＩＫＥガイドツアー', description = '大朝を中心に北広島町の町並みをE-BIKEで駆け巡るツアーです。有限会社大朝交通は観光バス事業と公共交通事業を主に行っており、サイクリング事業を新たな柱として大朝と北広島町を盛り上げることを目指しています。電動アシスト自転車を使用するため、坂道も楽に走行でき、初心者でも気軽に参加できます。サイクルステーションとバスの駅を複合した「大朝モビリティーステーション」（略称O.M.S）は、北広島町大朝2487に位置しています。詳細については0826-82-2233までお問い合わせください。Ｅ-ＢＩＫＥのレンタルも可能です。' where id = 'ymdqDyPeh15p7OqWZv7wi';
update content_bodies set title = 'E-BIKE Guided Tour in Kitahiroshima Town', description = 'Explore the scenic town of Kitahiroshima, centered around Oasa, on an E-BIKE! Oasa Transportation Co., Ltd., located in Oasa, Kitahiroshima Town, primarily operates sightseeing buses and public transportation. They aim to promote cycling as a new pillar of their business to invigorate Oasa and Kitahiroshima Town. The electric assist bicycles make it easy to ride uphill, allowing beginners to join comfortably. The Oasa Mobility Station (abbreviated as O.M.S) combines a cycle station with a bus station, located at 2487 Oasa, Kitahiroshima Town. For inquiries, please contact 0826-82-2233. E-BIKE rentals are also available. Visit their website at https://www.oasabus.com/.' where id = 'MJmc0oG23wUB82OOEmhyP';
update content_bodies set title = 'キャンプ初心者の女子大生が阿蘇でソロキャンプしてみた。【トマトの丸焼き編】', description = '動画をご視聴いただきありがとうございます。「Aso Camp」とは、九州の熊本県阿蘇でのキャンプを指します。この動画では、阿蘇でしか体験できない特別なキャンプの様子をお届けします。キャンプ料理に使用する食材にもこだわり、オンラインショップASOMOで購入した「王様トマト」を使用しています。キャンプ場は阿蘇市北坂梨にある「阿蘇ほっとかん」で、特別な雰囲気を楽しめる場所です。また、コーギー犬リト君と一緒に阿蘇を満喫する様子も紹介しています。関連動画もぜひご覧ください。' where id = 'bY9Mu6aEs7Ur4DS7Oi8hS';
update content_bodies set title = 'A Beginner Female College Student Tries Solo Camping in Aso: Roasted Tomato Edition', description = 'Thank you for watching the video. ''Aso Camp'' refers to camping in Aso, Kumamoto Prefecture, Kyushu. This video showcases a unique camping experience that can only be enjoyed in Aso, featuring delicious ingredients. The focus is on the quality of the ingredients used in camp cooking, including the ''King Tomato'' purchased from the online shop ASOMO, available from June to October. The camping site is ''Aso Hotkan,'' a special campsite in Kitazakanari, Aso City, where visitors can enjoy a different atmosphere. The video also features a corgi named Rito enjoying Aso. Don''t miss the related video on camp meals!' where id = 'JqP6OA_rYvD0AAGoBskYa';
update content_bodies set title = '【北広島町】国の天然記念物～大朝のテングシデ群落～', description = '標高640ｍ、広さ約57アールの谷間に、イヌシデの変種が約100本群生しています。これらの樹木は、枝や幹が曲がりくねった独特の形状を持ち、天狗の伝説に由来してテングシデと呼ばれ、地域の人々に大切にされています。国の天然記念物に指定されており、世界で唯一ここに自生しています。特に5月上旬の新緑は見逃せません。ただし、冬季は林道の除雪が行われないため、積雪時にはスノーシューなどの装備が必要です。この光景は非常に貴重です。' where id = 'IBSZK6Nrft3l_-U8J8wA7';
update content_bodies set title = 'National Natural Monument: Tengu Shide Grove in Kitahiroshima Town', description = 'Located at an elevation of 640 meters, the Tengu Shide Grove spans approximately 57 ares and is home to around 100 trees of a variant of the Japanese dogwood. These trees exhibit a unique, twisted shape, which has led to their association with the legend of Tengu, making them cherished by the local community. Designated as a national natural monument, this grove is the only one of its kind in the world. The fresh greenery in early May is a must-see. Note that during winter, the forest road is not cleared of snow, so visitors need snowshoes or similar equipment to access the area when it is snow-covered. This sight is extremely rare.' where id = 'NSRVgqMc3gMuXfWk8WZpj';
update content_bodies set title = 'レッドヒルヒーサーの森', description = '世界一のっぽの木「センベルセコイア」が植えられた里山を散策できます。ダイナミックな「森のエリア」と、魅力的なローズガーデンやスイレン池がある「花エリア」があり、自然の美しさを楽しむことができます。詳細は観光三重のホームページをご覧ください。' where id = 'MRqgsdESMBFMLkfq5eXdI';
update content_bodies set title = 'Red Hill Healer''s Forest', description = 'Take a stroll through a satoyama where the world''s tallest tree, the Sequoiadendron giganteum, is planted. The area features a dynamic ''Forest Area'' and a ''Flower Area'' that boasts a beautiful rose garden and a pond with water lilies.' where id = 'r-1SqEJdtST7vNGr0n6eU';
update content_bodies set title = '【北広島町】chalkart.Studio.Ape（チョークアート・スタジオ・アーペ）', description = 'チョークアートは、オーストラリア発祥の新しいアートで、専用のブラックボードに発色の良いオイルパステルを使って描かれます。色を混ぜたり、指を使って描くことで、全てフリーハンドで仕上げられ、温かみのある魅力的な作品が生まれます。260年の歴史を持つ専教寺の中に位置し、独特の雰囲気の中で創作が楽しめます。初心者でも安心して参加できるよう、優しく指導してもらえるので、気軽に体験できます。営業は予約制で、詳細は電話でのお問い合わせが必要です。' where id = 'PZzxRqeLCYumvR20KsCoZ';
update content_bodies set title = 'Chalk Art Studio Ape in Kitahiroshima Town', description = 'Chalk art, originating from Australia, is a new form of art created on special blackboards using vibrant oil pastels. Artists blend colors and use their fingers to create unique pieces entirely freehand, resulting in warm and unforgettable artwork. The studio is located in a 260-year-old temple, Senkyoji, providing a unique atmosphere for creativity. Beginners are welcome, and gentle guidance is offered to ensure a comfortable experience. The studio operates by reservation, and further details can be obtained by contacting the provided phone number.' where id = 'xv5k3snUh-9vB33_7_Qr8';
update content_bodies set title = '【バラ満開】秋の薔薇まつり in ASO MILK FACTORY', description = '阿蘇市小里に位置する観光施設「ASO MILK FACTORY」のローズガーデンでは、温室で育てられたバラが見頃を迎えています。秋のバラは春に比べて花の数は少ないものの、香りが強く、色味が深い艶やかな花が特徴です。開催期間は令和3年10月9日から11月7日までで、入場は無料です。期間中、売店ではバラの苗や肥料が販売され、カフェでは特別メニューの薔薇バウムソフトが提供されます。また、レストランでは食後に薔薇付きのジェラートが楽しめます。' where id = 'ti_elKH6P2cuDAFNl8EWS';
update content_bodies set title = 'Autumn Rose Festival at ASO MILK FACTORY', description = 'The Rose Garden at ASO MILK FACTORY in Koshi, Aso City, is currently showcasing roses grown in a greenhouse. Although the number of autumn roses is fewer compared to spring, they are characterized by their strong fragrance and deep, lustrous colors. The festival runs from October 9, 2021, to November 7, 2021, and admission is free. During this period, visitors can purchase rose seedlings and fertilizers at the shop. Additionally, a special rose Baumkuchen soft serve is available at the café, and the restaurant offers gelato with roses after meals.' where id = '2vu0A6jwTTpYCbGdrSPe5';
update content_bodies set title = '北広島町と安芸高田市の初のコラボ企画（ダンス編）', description = '2020年6月に全面オープンした「道の駅 三矢の里あきたかた」に、北広島町PR隊の愛ちゃんと花田舞太郎くんが突撃しました！これは北広島町と安芸高田市の初のコラボ企画（ダンス編）です。北広島町の「道の駅 舞ロードIC千代田」から車で約25分の距離にある2つの道の駅を巡ってみるのはいかがでしょうか？' where id = 'tgf_7ZdTlCjOj7Rn_N99M';
update content_bodies set title = 'First Collaboration Project between Kitahiroshima Town and Akitakata City (Dance Edition)', description = 'In June 2020, the ''Michi no Eki Mitsuya no Sato Akitakata'' fully opened, and the PR team from Kitahiroshima Town, Ai-chan and Maitaro Hanada, made a surprise visit! This marks the first collaboration project (dance edition) between Kitahiroshima Town and Akitakata City. The two roadside stations are about a 25-minute drive apart, so why not visit both?' where id = 'mAZz6OtluvXCG-s6rcbrq';
update content_bodies set title = '金運アップ！赤水 蛇石神社', description = '初詣におすすめの蛇石神社を紹介します。この神社では白蛇が祀られており、金運をアップさせるご利益が期待できます。' where id = '1Bnyx-6mlQb9Sn0Fmsc4w';
update content_bodies set title = 'Increase Your Financial Luck! Akamizu Snake Stone Shrine', description = 'We introduce the Snake Stone Shrine, which enshrines a white snake and is recommended for New Year''s visits!' where id = 'zWI1jYF02aJp_noHJFw4M';
update content_bodies set title = '舞太郎くんが「道の駅 三矢の里あきたかた（安芸高田市）」へ突撃っ！！', description = '2020年6月に全面オープンした「道の駅 三矢の里あきたかた（安芸高田市）」に、北広島町PR隊の愛ちゃんと花田舞太郎くんが突撃しました。この訪問は、北広島町と安芸高田市の初のコラボ企画となります。「道の駅 舞ロードIC千代田」から車で約25分の距離にあり、両方の道の駅を巡るのも良いでしょう。' where id = 'VjTrmesAagtQsR7s_t3Nl';
update content_bodies set title = 'Baitaro-kun''s Surprise Visit to ''Michi no Eki Mitsuya no Sato Akitakata''!', description = 'In June 2020, ''Michi no Eki Mitsuya no Sato Akitakata'' fully opened its doors. Baitaro-kun and Ai-chan from the PR team of Kitahiroshima Town made a surprise visit to this location, marking the first collaboration between Kitahiroshima Town and Akitakata City. The station is about a 25-minute drive from ''Michi no Eki Mai Road IC Chiyoda''. Why not explore both stations?' where id = 'QT7XeiUYC5kaAq7K2GVW1';
update content_bodies set title = '【花田舞太郎】ペーパークラフト発売！', description = '新商品として、僕のペーパークラフトが登場しました！これを作ることで、いつでも僕と一緒に遊ぶことができます。現在、道の駅舞ロード内の北広島町観光協会と産直市で販売中です。価格は税込500円です。' where id = 'CrvM-4a5my5BPiS3_kug4';
update content_bodies set title = 'New Paper Craft by Maitaro Hanada!', description = 'A new product, my paper craft is now available! You can create it and play with me anytime. It is currently on sale at the Mai Road roadside station, at the Kitahiroshima Town Tourism Association & Direct Sales Market for 500 yen (tax included).' where id = 'RrSUDB6mm1SoAINmkG0dD';
update content_bodies set title = '【花田舞太郎】カモミール畑でモウダッシュ！？【天意の里ハーブガーデン】', description = '北広島町大朝にある「天意の里ハーブガーデン」では、たくさんのカモミールが咲いていました。その美しさに思わずはしゃいでしまいました！' where id = '8aUN8GHf-fM39dFubpNqb';
update content_bodies set title = 'Chamomile Field Dash by Maitaro Hanada! 【Ten''i no Sato Herb Garden】', description = 'In the Ten''i no Sato Herb Garden located in Oasa, Kitahiroshima Town, a large number of chamomiles were in full bloom. I couldn''t help but get excited!' where id = 'zMfRIuLzc50KS-zCYEvfK';
update content_bodies set title = 'コロナに負けるな！茅の輪で疫病を退治！', description = '舞太郎から神楽ファンの皆様へメッセージです(^O^)／' where id = 'mRHbJy9dCQJ1FddMUfAl2';
update content_bodies set title = 'Don''t Let COVID-19 Win! Drive Away Epidemics with Chano-wa!', description = 'A message from Maitaro to all Kagura fans! (^O^)／' where id = 'ng8WFAKkPKY_8pMLgBhgH';
update content_bodies set title = 'ウォーキングバイシクルで内牧をお散歩', description = '新感覚の歩いてこぐ電動アシスト付き三輪自転車「ウォーキングバイシクル」を紹介します。リポーターの古田とわさんが阿蘇市内牧を散策しながら、このユニークな乗り物の魅力を伝えます。動画では、地元のお店への訪問や乗り方の説明、カフェや文化施設への寄り道などが含まれています。また、レンタル場所や料金についての情報も提供されています。ぜひご覧ください。' where id = 'lv3UHnQu8bbFMeWKwNabb';
update content_bodies set title = 'Walking Bicycle Stroll in Naimaki', description = 'Introducing the innovative electric assist tricycle, the ''Walking Bicycle.'' Reporter Towa Furuta explores the scenic Naimaki area in Aso City, sharing the charm of this unique mode of transportation. The video includes various segments such as a visit to a local shop, an explanation of how to ride the bicycle, and some delightful detours to local cafes and cultural spaces. Viewers can also find information about rental locations and pricing. Don''t miss this engaging exploration!' where id = '1SBtqjFN64S7WjiGgPKX7';
update content_bodies set title = '【花田舞太郎】おうちでストレッチ１', description = '今回は「どんぐり財団」の方に教わりながらストレッチを行います。愛ちゃんも一緒に参加しますので、ぜひおうちで一緒にやってみましょう。楽しく体を動かして、リラックスする時間を持ちましょう。' where id = 'upURe-FhN1OSdKofLsbrZ';
update content_bodies set title = 'Stretching at Home with Mai Taro Hanada', description = 'In this session, we will learn stretching techniques with the help of the Donguri Foundation. Ai-chan will join us as well. Let''s try it together at home!' where id = '03UKg8U-79GaFXIq2p9z6';
update content_bodies set title = '火の国ドッグラン・オートキャンプ場', description = '阿蘇市小里に新たにオープンしたドッグラン併設のオートキャンプ場についての情報です。ドッグランの営業時間は午前9時から午後4時までで、料金は1頭目が550円、2頭目以降は1頭あたり220円です。オートキャンプ場のチェックイン時間や料金、利用方法の詳細は「火の国ドッグラン・オートキャンプ場」のホームページをご覧ください。' where id = '0e2h5NsiI8jkV1BmpRfHY';
update content_bodies set title = 'Hinokuni Dog Run and Auto Campground', description = 'A new auto campground with a dog run has opened in Kozaki, Aso City. The dog run operates from 9 AM to 4 PM, with a fee of 550 yen for the first dog and 220 yen for each additional dog. For more details on check-in times, fees, and usage of the auto campground, please visit the ''Hinokuni Dog Run and Auto Campground'' website.' where id = 'uECYN9hRIXMo_bHsaLrk6';
update content_bodies set title = '【北広島町】豊平地域～田園風景～', description = 'この動画では、北広島町の豊平地域に焦点を当て、その美しい田園風景を紹介しています。' where id = 'tW41Q8Ma7NqE_LECYGcLW';
update content_bodies set title = 'Toyohira Region in Kitahiroshima Town - Rural Scenery', description = 'This video introduces the Toyohira region in Kitahiroshima Town, showcasing its beautiful rural landscapes.' where id = 'kIlCiTVsN_yOEwOIHmRni';
update content_bodies set title = '鶏卵産出額日本一！鶏のまち 鹿児島県出水市で味わえる鶏づくしメニュー「いずみ親子ステーキごはん」', description = '鹿児島県出水市は、日本有数の鶏肉・鶏卵の生産地であり、2011年に市内の飲食店の有志によって「いずみ親子ステーキごはん」というご当地グルメが開発されました。このメニューは、出水市産の鶏肉のステーキ、卵かけごはん（TKG）、チキンサラダ、たまごスープを含む鶏づくしの料理です。価格は1,500円（税込）で、現在市内の3店舗で提供されています。各店舗ごとにチキンサラダやスープの味付けが異なり、タレやデザートもオリジナルです。3店舗を食べ比べるのもおすすめです。店舗の詳細情報も掲載されています。' where id = '3Xh-CXk8GmrHi2cmyzW65';
update content_bodies set title = 'Kagoshima''s Izumi City: The Top Producer of Chicken Eggs with the ''Izumi Parent-Child Steak Rice'' Menu', description = 'In Izumi City, Kagoshima Prefecture, known for its high production of chicken and eggs, a local gourmet dish called ''Izumi Parent-Child Steak Rice'' was developed in 2011 by local restaurant volunteers. This dish features grilled chicken steak from Izumi, along with egg rice (TKG), chicken salad, and egg soup, showcasing the city''s chicken-centric cuisine. Priced at 1,500 yen (tax included), it is currently offered at three restaurants in the city. Each restaurant has its own unique flavors for the chicken salad and soup, as well as original sauces and desserts, making it a great idea to try all three for a comparison. Details of the restaurants are provided, including their locations, contact information, operating hours, and Instagram links.' where id = 'rsri-MQhlF4TH9HqnojFk';
update content_bodies set title = '花田舞太郎 魚釣りに挑戦', description = '北広島町の大暮養魚場で魚釣りに挑戦した花田舞太郎。最初はなかなか釣れなかったが、最後には釣果があった。さらに、愛ちゃんが運営する愛チャンネルの取材をテレビ局から依頼され、一緒に同行した様子も紹介されている。舞太郎はテレビカメラに映ることに喜びを感じていた。' where id = 'bujH52o2vXwyTcTaQZtkz';
update content_bodies set title = 'Mai Taro Hanada Tries Fishing', description = 'Mai Taro Hanada attempted fishing at the Okubo Fish Farm in Kitahiroshima Town. Although he struggled to catch fish at first, he eventually succeeded. Additionally, he accompanied a television crew that wanted to cover Ai-chan''s channel, capturing moments of the experience. He was excited to be on camera.' where id = '0tvzYd9IBUzp-VKJ4EZHn';
update content_bodies set title = 'かぶと作りに挑戦！指がないのにできるの？', description = '普段は花田植の準備で忙しい時期ですが、外出自粛の影響で自宅にいることになりました。そこで、こどもの日に向けてかぶとを作ってみることにしました。難しいですが、みんなも挑戦してみてください。' where id = 'ey-I-zVAZWbd7aEbq-_QO';
update content_bodies set title = 'Challenging to Make Kabuto! Can I Do It Without Fingers?', description = 'During a busy time preparing for the Hanada planting, I found myself stuck at home due to restrictions. So, I decided to try making a kabuto for Children''s Day. It''s quite difficult! I encourage everyone to give it a try too.' where id = 'PufNFzXfVTxZtF-AhqOM7';
update content_bodies set title = '住む人と土地の温もりに間近で触れる。鹿児島県・出水市で農泊体験', description = '出水市は鹿児島県と熊本県の県境に位置し、日本一のツルの観光地として知られています。江戸時代の雰囲気を残す武家屋敷や、日本一の大鈴を持つ神社など、多くの観光名所があります。出水市の魅力をより深く知るためには、農泊体験が推奨されます。田舎に滞在することで、その地域の生活様式に触れ、自然とふれあい、独自の食文化を学ぶことができます。1泊2日の旅行で、出水市の魅力を余すところなく体験できます。' where id = '9rYlZTHQBuxboWMxeQu0O';
update content_bodies set title = 'To experience the warmth of the residents and the land up close Farm Stay in Izumi city, Kagoshima', description = 'Izumi City, located on the border of Kagoshima and Kumamoto, is renowned as Japan''s top destination for cranes. The city features attractions like samurai residences from the Edo period and a shrine housing the largest bell in Japan. For a deeper understanding of Izumi''s charm, the ''farm stay'' accommodation is highly recommended. This experience allows visitors to immerse themselves in the local lifestyle, connect with nature, and explore the unique food culture of the area. A one-night, two-day trip offers a comprehensive experience of everything Izumi City has to offer.' where id = 'NaUHqk0qcf0o47wI1-BFi';
update content_bodies set title = '阿蘇市の立ち寄り湯～内牧エリア・前編～', description = '前回に引き続き、阿蘇市で日帰り入湯のできる湯処を紹介します。今年は寒さとコロナで例年より厳しい冬となっておりますが、感染対策をしっかりとして、ぜひ阿蘇の温泉へお越しください。今回紹介するのは、湯処が密集した温泉地の内牧エリアで、以下の4つの湯処を紹介しています。1. 旅の宿 阿蘇乃湯、2. 湯の宿 入船、3. 旅館金時、4. ホテル角萬。' where id = 'p7MQ-jq6tLagpuxB0ObXz';
update content_bodies set title = 'Day-Use Hot Springs in Aso City - Part 1: Inner Makik Area', description = 'Continuing from the previous article, this piece introduces day-use hot springs in Aso City. This winter has been particularly harsh due to cold weather and COVID-19, but with proper infection control measures, we encourage you to visit Aso''s hot springs. The focus is on the Inner Makik area, known for its concentration of hot spring facilities, featuring four specific locations: 1. Aso no Yu, a travel inn; 2. Yuno Yado Irifune; 3. Ryokan Kintoki; and 4. Hotel Kakuman.' where id = '_LaG-RLyyVXaN-j6wtNOw';
update content_bodies set title = '泉市からのバーチャルバードウォッチング', description = '鹿児島県の泉市は、10月から3月にかけて1万羽以上の鶴が渡来する特別なバードウォッチングのスポットです。この地域では、特に夜明けに大群で飛ぶ鶴の姿を目にすることができ、忘れられない体験となります。鶴は1952年に特別天然記念物に指定され、2021年11月18日にはラムサール条約の国際的重要湿地リストにも登録されました。また、泉市は田舎の宿泊体験でも知られており、訪問者は滞在中に農業体験を楽しむことができます。ぜひこの素晴らしい街を一緒に探検しましょう！' where id = 'T-XsVcU7cvV2oTZFkYgqa';
update content_bodies set title = 'Virtual Bird Watching from Izumi, the city of the country stay', description = 'Izumi City in Kagoshima Prefecture is a unique destination for bird watching, particularly known for the migration of over 10,000 cranes from October to March. This city offers the rare opportunity to witness these magnificent birds in flight, especially at dawn when they soar in large numbers. The cranes have been recognized as a Special Natural Monument since 1952 and were added to the Ramsar Convention''s List of Wetlands of International Importance on November 18, 2021. In addition to bird watching, Izumi is celebrated for its country stay hospitality, allowing visitors to engage in farm experiences during their visit. Join us in exploring this remarkable city!' where id = 'RkkyVOfZCq7tAj3aDKBaF';
update content_bodies set title = '出水麓武家屋敷群 空中散歩', description = '出水麓武家屋敷群では、歴史的な武家屋敷を空中から見学できるユニークな体験が提供されています。' where id = 'eCSENzyKI0PnrFXk9giBd';
update content_bodies set title = 'Izumi Fumoto Samurai Residences: A Sky Walk', description = 'Izumi Fumoto Samurai Residences offers a unique aerial experience, allowing visitors to explore the historical samurai houses from above.' where id = 'oxUEaWyfdCLDLvNw9kBsF';
update content_bodies set title = 'いずみファームステイ体験', description = 'ファームステイとは、伝統的な日本の農家での生活を体験できる宿泊のことです。鹿児島県いずみ市にあるこのユニークな体験では、農家の日常生活や仕事を直接体験することができます。' where id = '44VtV2c7cU2auffct5vm9';
update content_bodies set title = 'Izumi Farm Stay Experience', description = 'A farm stay allows visitors to immerse themselves in the daily life of a traditional Japanese farming household. This unique experience offers a firsthand look at the work and lifestyle of farmers in Izumi City, located in Kagoshima Prefecture.' where id = 'R4Oh080lxsjMZo0HEpxtw';
update content_bodies set title = '阿蘇市の立ち寄り湯～内牧エリア・後編～', description = '今回が最終回です！阿蘇市で日帰り入湯ができる温泉施設を紹介します。今年の冬は寒さとコロナの影響で例年より厳しい状況ですが、感染対策をしっかり行い、ぜひ阿蘇の温泉を訪れてください。紹介する温泉には、宝湯（温泉割烹がね政）、薬師温泉、五岳ホテル、民宿大阿蘇があります。' where id = 'y44eIpVre-qy1dUVsGr54';
update content_bodies set title = 'Aso City''s Day-Use Hot Springs - Inabakie Area Part 2', description = 'This is the final installment! We introduce day-use hot spring facilities in Aso City. This winter has been particularly harsh due to the cold and COVID-19, but we encourage you to visit Aso''s hot springs while taking proper infection prevention measures.' where id = 'TskF5y_KReya6cDoMV3_3';
update content_bodies set title = 'マチテラス〜出水の光〜　鹿児島県出水市', description = '鹿児島県出水市で開催される「いずみマチ・テラス」のプロモーションビデオです。このイベントは、地域の魅力を発信することを目的としており、竹灯籠やドラゴンランタンなどの美しい光の演出が特徴です。また、出水麓武家屋敷群や東光山公園などの観光名所も紹介されており、着物を着た観光牛車の姿も見られます。音楽はKAZRUによるもので、イベントの雰囲気を一層引き立てています。' where id = 'ON1REHTYeIi-zw8xby3aa';
update content_bodies set title = 'Machiterasu - Izumi''s Light - Izumi City, Kagoshima Prefecture', description = 'This is a promotional video for the ''Izumi Machi Terrace'' event held in Izumi City, Kagoshima Prefecture.' where id = 'jpjIXnOGKPGJf0wYODdDq';
update content_bodies set title = 'いずみ', description = '出水市観光情報サイト「出水ナビ」では、武家屋敷での着付け体験の様子が紹介されています。この体験は、日本の伝統文化に触れる貴重な機会であり、武家屋敷の独特な雰囲気の中で行われます。着物を着ることで、歴史的な背景を感じることができ、参加者は日本の文化を深く理解することができます。' where id = 'xpThhLmjlVeAWPGa7EMZi';
update content_bodies set title = 'Izumi', description = 'The description highlights the experience of wearing traditional clothing at a samurai residence. It provides insights into the cultural significance and the unique atmosphere of the setting, emphasizing the connection to Japan''s historical heritage.' where id = 'l7vHoBfzesGpk8OpIk-HQ';
update content_bodies set title = '阿蘇市のテイクアウトランチスポット～阿蘇エリア・その１～', description = 'この動画では、阿蘇の大自然の中でテイクアウトした食べ物を楽しめるおすすめの休憩スポットを紹介します。全4エリアに分けており、第1回目は外輪山エリアに焦点を当てています。このエリアには多くの展望スポットが整備されており、具体的には大観峰（01:04）、阿蘇スカイライン展望所（01:37）、かぶと岩展望所（02:08）、二重峠展望台（02:34）が紹介されています。' where id = 'wyBo0Tsf8JF2d80p2GNGp';
update content_bodies set title = 'Takeout Lunch Spots in Aso City - Aso Area Part 1', description = 'This video introduces recommended rest spots in Aso City where you can enjoy takeout food amidst the great nature of Aso. The first part focuses on the outer rim area of Aso, which is equipped with numerous scenic viewpoints. Featured locations include: 01:04 - Daikanbo, 01:37 - Aso Skyline Viewpoint, 02:08 - Kabuto Rock Viewpoint, and 02:34 - Niju Pass Viewpoint.' where id = 'NxDW9BmluOQOebji0Ia5M';
update content_bodies set title = '阿蘇市のテイクアウトランチスポット～一の宮エリア～', description = 'この動画では、阿蘇の大自然の中でテイクアウトした食べ物を楽しめるおすすめの休憩スポットを紹介します。第3回目は、阿蘇神社や門前町商店街がある一の宮エリアに焦点を当てています。門前町からアクセスしやすい絶景スポットや、阿蘇五岳周辺のスポットを紹介し、自然を満喫しながらランチを楽しむ方法を提案します。' where id = '21K6invamjew--y5sBkcp';
update content_bodies set title = 'Takeout Lunch Spots in Aso City - Ichinomiya Area', description = 'This video introduces recommended rest spots in Aso City where you can enjoy takeout food amidst the great nature of Aso. The third installment focuses on the Ichinomiya area, which features Aso Shrine and the Monzen-machi shopping district. It highlights scenic spots that are easily accessible from the shopping district and around the Aso Five Mountains.' where id = 'I2nT9lJussWCtf9ztL5B0';
update content_bodies set title = '出水の鶴　昼間のお食事', description = '出水市でのツルの食事風景を紹介する映像です。' where id = 'aYbzVAP4zvXK8bxTHBbBd';
update content_bodies set title = 'Crane Feeding in Izumi - Daytime Meal in 4K', description = 'A video showcasing the feeding behavior of cranes.' where id = 'x2EH_P6WsjuXrDydZa7sS';
update content_bodies set title = 'うさぎ号　潮汲み体験付き！「稲佐の浜と出雲大社＆日御碕神社の旅」', description = '「出雲周遊観光タクシーうさぎ号」は、神々の物語や出雲の風習を感じられるコースを提供しています。神迎神事が行われる稲佐の浜から出雲大社への参拝ルートでは、出雲の風習である「潮汲み」体験も楽しむことができます。神話の舞台を歩きながら、地元の伝統に触れてみませんか？' where id = 'U8WYgC86gEsXyCR8Pa_aR';
update content_bodies set title = 'Usagi-go: Experience Tide-Pulling on a Journey to Inasa Beach, Izumo Taisha, and Hinomisaki Shrine', description = 'The ''Usagi-go'' sightseeing taxi offers a course that allows you to feel the stories of the gods and the customs of Izumo. On the route from Inasa Beach, where the Kami-kuru Shinjitsu ceremony takes place, to Izumo Taisha, you can enjoy the local custom of ''tide-pulling.'' Walk through the settings of mythology while experiencing local traditions.' where id = 'RoW1SsUDQ-whLsXxvgyLZ';
update content_bodies set title = 'うさぎ号　1番人気！「海の出雲 神々由縁の地を巡る」', description = '「出雲周遊観光タクシーうさぎ号」は人気ナンバー１のコースです。このコースでは、神話の世界に足を踏み入れながら、出雲ならではの雰囲気や歴史を気軽に楽しむことができます。神々に会いに出かけてみませんか？' where id = 'DWIJCu5Orf2DF395zM8ZL';
update content_bodies set title = 'Usagi-go: The Most Popular Course! ''Exploring the Divine Land of the Sea of Izumo''', description = 'The ''Izumo Sightseeing Taxi Usagi-go'' offers the number one popular course. This experience allows you to step into the world of mythology while enjoying the unique atmosphere and history of Izumo. Why not go out and meet the gods?' where id = 'gs5i0yEfK_KutojntjF8b';
update content_bodies set title = '出雲〝日御碕〟の景色', description = '出雲観光大使「X＋（えくすと）」によるプロモーション動画では、出雲大社から車で15分の日御碕の景色を紹介しています。日御碕の景色は季節や天候、時間によって変化します。重要文化財である朱色の「日御碕神社」、日本一の高さを誇る石造りの灯台「出雲日御碕灯台」、うみねこの繁殖地「経島」などが見どころです。また、「大山隠岐国立公園」や「日本遺産 日が沈む聖地出雲」、「島根半島・宍道湖中海ジオパーク」に認定されている自然も楽しめます。' where id = 'ryqhTbzmM_0l0FAsy3dPN';
update content_bodies set title = 'Scenery of Hinomisaki in Izumo', description = 'This promotional video by Izumo tourism ambassador ''X+'' showcases Hinomisaki, located just 15 minutes by car from Izumo Taisha. The scenery of Hinomisaki in Shimane Prefecture changes with the seasons, weather, and time of day. Highlights include the vermilion-colored important cultural property Hinomisaki Shrine, the Izumo Hinomisaki Lighthouse, which boasts the tallest stone structure in Japan, and the breeding ground for black-tailed gulls on Kyoshima. Visitors can also enjoy the natural beauty of Hinomisaki, surrounded by sea and mountains, recognized as part of Daisen-Oki National Park, the Japan Heritage site ''Sacred Place Where the Sun Sets in Izumo,'' and the Shimane Peninsula and Lake Shinji Geopark.' where id = 'HfXxAJeAV4GkgGKEZg7pH';
update content_bodies set title = '「燃ゆる感動かごしま国体」出水市開催1000日前記念イベント', description = '平成30年1月7日（日）に「燃ゆる感動かごしま国体」開催まであと1000日となりました。この記念すべき日を祝うため、出水市では「出水市開催1000日前記念イベント」を開催しました。イベントでは、国体までのカウントダウンボードの除幕、競技団体の代表による決意表明、市民運動開始宣言、国体ダンス「ゆめ～KIBAIYANSE～」の披露が行われ、国体に向けたムードが高まっています。' where id = 'bDvSnp1qJFaKohbQEoYwC';
update content_bodies set title = '1000 Days Until the ''Burning Emotion Kagoshima National Sports Festival'' Event in Izumi City', description = 'On January 7, 2018, it was announced that there are 1000 days left until the ''Burning Emotion Kagoshima National Sports Festival''. To celebrate this milestone and to energize the community, the ''Izumi City 1000 Days Before Event'' was held. The event featured the unveiling of a countdown board, a declaration of commitment from representatives of sports organizations, the announcement of a citizen movement, and a performance of the national sports festival dance ''Yume~KIBAIYANSE~''. The atmosphere for the national sports festival is steadily building.' where id = 'w2PTJS-UyVzP1pv6QLrtL';
update content_bodies set title = 'みえのイマココ旅　「エコツアー×リトリート」編', description = '「みえのイマココ旅」は、三重の「イマしかない」「ココしかない」体験を楽しむことを目的とした旅行プランです。テーマは「歴史・文化」「自然」「食」「ナイト＆モーニング」「サスティナブル」で、特設サイトでは46の体験プランが紹介され、予約が可能です。「エコツアー」×「リトリート」では、樹齢100年の森との触れ合いや、尾鷲の町並みを見渡せる巨岩でのヨガなど、自然を楽しみながら心身を癒す特別な体験が提供されています。具体的な体験には、滝巡り、シーカヤック、真珠ジュエリー作りなどが含まれ、三重の自然と文化の魅力を伝えています。' where id = 'E-Y_5xt2TMldhAvT27dWX';
update content_bodies set title = 'Mie''s Imakoko Travel: EcoTourism and Retreat Edition', description = 'Mie''s Imakoko Travel invites visitors to experience unique aspects of Mie Prefecture, focusing on ''history and culture,'' ''nature,'' ''food,'' ''night and morning,'' and ''sustainability.'' The initiative offers 46 experiential plans that can be reserved through a special website. The ''EcoTour'' and ''Retreat'' segment features special activities that promote relaxation and connection with nature, such as yoga on giant rocks overlooking the town of Owase and interactions with century-old forests. Various experiences include waterfall tours, sea kayaking on the Kumano ancient road, premium forestry experiences, and more, showcasing the natural beauty and cultural richness of Mie.' where id = 'ToYMWGg5PWB1XFUbfYIum';
update content_bodies set title = '出雲周遊観光タクシー「うさぎ号」プロモーション動画（long.ver)', description = '出雲市内の名所を巡る「出雲周遊観光タクシー うさぎ号」では、タクシー1台に1人のガイドが同行し、各スポットの歴史や由緒、見どころをわかりやすく説明します。コロナ渦の中で密を避け、安全に出雲の魅力を楽しむことができる小回りのきく旅を提供します。詳しくは出雲観光協会のホームページをご覧ください。' where id = 'GzwoHL05CvZClr4J7a8VF';
update content_bodies set title = 'Izumo Sightseeing Taxi ''Usagi-gō'' Promotional Video (Long Version)', description = 'The ''Izumo Sightseeing Taxi Usagi-gō'' offers guided tours of famous spots in Izumo City. Each taxi is accompanied by a guide who provides easy-to-understand explanations of the history, significance, and highlights of each location. Amid the COVID-19 pandemic, this taxi service ensures a safe and secure way to explore the attractions of Izumo while avoiding crowded places, allowing for a flexible travel experience unique to taxis. For more details, please visit the Izumo Tourism Association website.' where id = 'U6-_BjEX3rknToZnapky1';
update content_bodies set title = '出雲大社・稲佐の浜ブルーライトアップ　～祈り～　（long ver.）', description = '2021年1月30日、出雲市内各地で新型コロナウイルスの終息を願い、医療従事者への感謝を込めてブルーライトアップが行われました。私たちは神々の恩恵を受け、疫病などの災いから守られてきました。一日でも早く平穏な日々が戻ることを願っています。この動画は「祈りの聖地・出雲」から、世界の安寧と終息への祈りを込めてお届けします。―出雲の日実行委員会―' where id = 'WL1alJnPseQHbMHiBeszN';
update content_bodies set title = 'Izumo Taisha & Inasa no Hama Blue Light Up - Prayer - (long ver.)', description = 'On January 30, 2021, various locations in Izumo City were illuminated with blue lights to wish for the end of the COVID-19 pandemic and to express gratitude to healthcare workers. We have received blessings from the gods and have been protected from various calamities, including epidemics. We hope for a swift return to peaceful days. This video is delivered from ''Izumo, the Sacred Place of Prayer,'' with prayers for global peace and the end of the pandemic. - Izumo Day Executive Committee -' where id = 'H0qKXCzcuMXUv6jvkvkka';
update content_bodies set title = '出雲大社・稲佐の浜ブルーライトアップ　～祈り～　（short ver.）', description = '2021年1月30日、新型コロナウイルス終息を願い、医療従事者への感謝を込めて出雲市内各地がブルーライトアップされました。私たちは神々の恩恵を受け、疫病などの災いから守られてきました。一日でも早く平穏な日々が戻ることを願っています。この動画は「祈りの聖地・出雲」から、世界の安寧と終息への祈りを込めてお届けします。―出雲の日実行委員会―' where id = 'N8dWKJt29YXXjpGLzwZ3d';
update content_bodies set title = 'Izumo Taisha & Inasa no Hama Blue Light Up - Prayer - (short ver.)', description = 'On January 30, 2021, various locations in Izumo City were illuminated with blue lights to wish for the end of the COVID-19 pandemic and to express gratitude to healthcare workers. We have received blessings from the deities and have been protected from various calamities, including epidemics. We hope for a swift return to peaceful days. This video is delivered from ''Izumo, the Sacred Place of Prayer,'' with prayers for global peace and the end of the pandemic.' where id = 'J2V6qszJ6ff8BNBkX7wGD';
update content_bodies set title = '【利尻島】ここにしかない体験、ガイドと探る利尻の旅', description = '日本最北の利尻島には、中心に雄大な利尻山がそびえ、氷河期から生き延びた美しい花や植物が点在しています。暖流と寒流が交わる豊かな海では、山からの湧水も加わり、豊富な海産物が獲れます。山と海と共に生きてきた人々の文化も色濃く残り、訪れる人々は多様なアクティビティを通じてこの自然を体感できます。島で活躍する3人のガイドと共に、利尻島の魅力を探る旅に出かけましょう。' where id = 'IT0QEzDnHg1QfYg9Tmpv4';
update content_bodies set title = 'Discover Rishiri Island with a Local Guide', description = 'Rishiri Island, located at Japan''s northernmost point, is home to the majestic Mt. Rishiri, surrounded by stunning flora that has thrived since the Ice Age. The island''s rich marine life benefits from the confluence of warm and cold currents, along with fresh spring water from the mountains. Visitors can immerse themselves in the vibrant culture of the island''s inhabitants, who have coexisted with nature for generations. A variety of activities allow guests to experience the island''s unique environment. Join three local guides as they reveal the charm of Rishiri Island through their expertise.' where id = 'cbP-QOhckGydpObgbOiLd';
update content_bodies set title = '阿蘇市のテイクアウトランチスポット～波野エリア～', description = 'この動画では、阿蘇市でテイクアウトした食べ物を楽しめるおすすめの休憩スポットを全4エリアに分けて紹介します。最終回となる今回は、大分県との県境に位置する波野エリアを取り上げます。蕎麦や神楽の里として知られる波野ならではの道の駅と、絶景スポットを紹介します。' where id = '_1Vo7wnJxW24-CqYWxnLm';
update content_bodies set title = 'Takeout Lunch Spots in Aso City - Namino Area', description = 'This video introduces recommended rest spots in Aso City where you can enjoy takeout food, divided into four areas. In this final episode, we explore the Namino area, located at the border with Oita Prefecture, known for its soba and Kagura. We will showcase a roadside station unique to Namino and a must-see scenic spot.' where id = 'GqwP4ksj1DI6cw7XYd7UZ';
update content_bodies set title = '【利尻島５分ver】大自然を旅する１年間 〜小さな島の大きな世界がここにある〜', description = '日本最北の利尻島には、中心に雄大な利尻山がそびえ、氷河期から生き延びた美しい花や植物が点在しています。暖流と寒流が交わる豊かな海では、山からの湧水とともに新鮮な海産物が豊富に獲れます。山と海に寄り添って生きてきた人々の文化も色濃く残っており、訪れる人々は多様なアクティビティを通じてこの自然を体感できます。この動画では、利尻島の大自然を旅する1年間を5分に凝縮しており、春のトドの群れや夏のSUPツアー、秋の星空観察、冬のスノーシューなど、四季折々の魅力を紹介しています。' where id = 'biPjc0T21VslAGmFR594V';
update content_bodies set title = 'A Year Traveling Through the Great Nature of Rishiri Island in 5 Minutes', description = 'Rishiri Island, located at Japan''s northernmost point, features the majestic Mt. Rishiri at its center. The island is home to a variety of beautiful flowers and plants that have thrived since the Ice Age. Its rich seas, nourished by both warm and cold currents along with mountain spring water, provide abundant seafood. The vibrant culture of the people who have lived in harmony with the mountains and the sea can be experienced through various activities. This video condenses a year of exploring Rishiri Island''s great nature into just five minutes, showcasing activities across all seasons, including sea urchin fishing, hiking, and stargazing.' where id = 'hWbQS7V_4Juk5a-N2LRmN';
update content_bodies set title = '稲佐の浜　夕景（春）', description = '島根県出雲市に位置する海岸「稲佐の浜」の夕景を紹介します。この写真は2020年4月14日に撮影されました。' where id = 'vFl0qDvMa-hloZdnPdY5L';
update content_bodies set title = 'Inasa no Hama Sunset (Spring)', description = 'This is a sunset view of Inasa no Hama, a beach located in Izumo City, Shimane Prefecture. The photo was taken on April 14, 2020.' where id = 'GDNjsbKwb_PjPiusHHYP0';
update content_bodies set title = '利尻島 「冬」', description = '現在作成中の利尻島PR動画の冬のシーンを一部事前公開します。利尻島の観光情報やガイド情報については、関連URLの「りしぷら」やガイド情報ページをご覧ください。' where id = 'pxnNqOEo9SIJ_tgedQoVg';